def now_iso() -> str:
    return _dt.datetime.now().replace(microsecond=0).isoformat()


class ThreadingHTTPServer(_BaseThreadingHTTPServer):
    daemon_threads = True

    def __init__(self, server_address: Tuple[str, int], RequestHandlerClass: type[BaseHTTPRequestHandler]) -> None:
        super().__init__(server_address, RequestHandlerClass)
        self.sprintos_started_at = now_iso()
        host, port = self.server_address[:2]
        self.sprintos_url = f"http://{host}:{port}"


