def normalize_timebox_minutes(value: Any) -> int:
    try:
        minutes = int(value)
    except (TypeError, ValueError) as exc:
        raise ValueError("timebox_minutes must be one of 30, 60, 120, 240") from exc
    if minutes not in TIMEBOX_MINUTES:
        raise ValueError("timebox_minutes must be one of 30, 60, 120, 240")
    return minutes


