ACTIVITY_EVENT_STATUSES = {"info", "success", "warning", "blocked", "failed"}
ACTIVITY_ACTORS = {"user", "sprintos", "codex_manual", "system"}
ACTIVITY_EVENT_RELATED_TYPES = {
    "project",
    "sprint",
    "prototype",
    "deploy_pack",
    "build_pack",
    "pipeline_run",
    "quick_launch",
    "demo_run",
    "verification_run",
    "workspace",
    "workspace_sync",
    "workspace_snapshot",
    "workspace_restore",
    "workspace_release",
    "focus_session",
    "ai_provider_eval",
    "ai_route",
    "app_generation_failure",
}
ACTIVITY_METADATA_REDACTED_KEYS = {
    "authorization",
    "headers",
    "api_key",
    "openai_api_key",
    "deepseek_api_key",
    "prompt",
    "prompts",
    "instructions",
    "response",
    "responses",
    "raw_prompt",
    "raw_response",
    "workspace_contents",
    "workspace_content",
    "file_contents",
    "file_content",
    "full_text",
    "body",
    "content",
}
ACTIVITY_SECRET_ASSIGNMENT_PATTERN = re.compile(
    r"(?i)\b(OPENAI_API_KEY|DEEPSEEK_API_KEY|API_KEY|AUTHORIZATION)\b\s*[:=]\s*([^\s,;]+)"
)
ACTIVITY_BEARER_PATTERN = re.compile(r"(?i)\bBearer\s+[A-Za-z0-9._-]+")


def normalize_activity_event_status(value: Any) -> str:
    status = str(value or "info").strip().lower() or "info"
    if status not in ACTIVITY_EVENT_STATUSES:
        raise ValueError("Unsupported activity event status")
    return status


def normalize_activity_actor(value: Any) -> str:
    actor = str(value or "sprintos").strip().lower() or "sprintos"
    if actor not in ACTIVITY_ACTORS:
        raise ValueError("Unsupported activity actor")
    return actor


def normalize_activity_related_type(value: Any) -> Optional[str]:
    related_type = str(value or "").strip().lower()
    if not related_type:
        return None
    return related_type if related_type in ACTIVITY_EVENT_RELATED_TYPES else related_type[:60]


def activity_redact_text(value: Any, limit: int = 500) -> str:
    text = str(value or "")
    text = ACTIVITY_SECRET_ASSIGNMENT_PATTERN.sub(lambda m: f"{m.group(1)}=[redacted]", text)
    text = ACTIVITY_BEARER_PATTERN.sub("Bearer [redacted]", text)
    text = redact_text(text)
    text = re.sub(r"\s+", " ", text).strip()
    return text[:limit].rstrip(" ,;:") if text else ""


def activity_sanitize_metadata(value: Any, *, depth: int = 0) -> Any:
    if depth > 3:
        return "[redacted]"
    if isinstance(value, dict):
        clean: Dict[str, Any] = {}
        for index, (key, item) in enumerate(value.items()):
            if index >= 12:
                break
            key_text = str(key).strip()
            lowered = key_text.lower()
            if lowered in ACTIVITY_METADATA_REDACTED_KEYS or "prompt" in lowered or "response" in lowered:
                continue
            if "authorization" in lowered or lowered.endswith("_token") or lowered.endswith("_secret") or lowered.endswith("_key"):
                continue
            if lowered.startswith("env") or lowered.endswith("_env"):
                continue
            clean[key_text[:80]] = activity_sanitize_metadata(item, depth=depth + 1)
        return clean
    if isinstance(value, list):
        return [activity_sanitize_metadata(item, depth=depth + 1) for item in value[:12]]
    if isinstance(value, str):
        return activity_redact_text(value, limit=240)
    if isinstance(value, (int, float, bool)) or value is None:
        return value
    return activity_redact_text(value, limit=240)


def activity_metadata_json(value: Any) -> str:
    return json.dumps(activity_sanitize_metadata(value), sort_keys=True)


def normalize_energy_level(value: Any) -> str:
    energy = str(value or "medium").strip().lower() or "medium"
    return energy if energy in {"low", "medium", "high"} else "medium"


