def activity_event_report_url(event: Dict[str, Any]) -> str:
    related_type = str(event.get("related_type") or "")
    related_id = str(event.get("related_id") or "")
    if not related_type or not related_id:
        return ""
    if related_type == "focus_session":
        return focus_session_report_url(related_id)
    if related_type == "deploy_pack":
        return f"/api/deploy_pack_file?id={urllib.parse.quote(related_id)}&file=DEPLOY.md"
    if related_type == "build_pack":
        return f"/api/build_pack_file?id={urllib.parse.quote(related_id)}&file=CODEX_BUILD_PROMPT.md"
    if related_type == "pipeline_run":
        return pipeline_report_url(related_id)
    if related_type == "quick_launch":
        return quick_launch_report_url(related_id)
    if related_type == "demo_run":
        return demo_run_report_url(related_id)
    if related_type == "verification_run":
        return verification_report_url(related_id)
    if related_type == "workspace_snapshot":
        return f"/api/workspace_snapshot_file?id={urllib.parse.quote(related_id)}&file=snapshot-report.md"
    if related_type == "workspace_restore":
        return workspace_restore_report_url(related_id)
    if related_type == "workspace_sync":
        return workspace_sync_report_url(related_id)
    if related_type == "workspace_release":
        return workspace_release_report_url(related_id)
    if related_type == "app_generation_failure":
        return app_generation_failure_report_url(related_id)
    return ""


def activity_event_row(row: sqlite3.Row | Dict[str, Any]) -> Dict[str, Any]:
    data = dict(row)
    metadata = safe_json_loads(str(data.get("metadata_json") or "{}"), {}) or {}
    event = {
        "id": str(data.get("id") or ""),
        "project_id": str(data.get("project_id") or "") or None,
        "project_title": str(data.get("project_title") or metadata.get("project_title") or ""),
        "created_at": str(data.get("created_at") or ""),
        "event_type": str(data.get("event_type") or ""),
        "event_status": normalize_activity_event_status(data.get("event_status") or "info"),
        "title": str(data.get("title") or ""),
        "summary": str(data.get("summary") or ""),
        "actor": normalize_activity_actor(data.get("actor") or "sprintos"),
        "related_type": normalize_activity_related_type(data.get("related_type")) or None,
        "related_id": str(data.get("related_id") or "") or None,
        "next_tiny_action": str(data.get("next_tiny_action") or "") or None,
        "report_path": str(data.get("report_path") or "") or None,
        "metadata": metadata,
    }
    event["report_url"] = activity_event_report_url(event)
    return event


def get_activity_event(event_id: str) -> Optional[Dict[str, Any]]:
    with db() as conn:
        row = conn.execute(
            """
            SELECT ae.*, p.title AS project_title
            FROM activity_events ae
            LEFT JOIN projects p ON p.id = ae.project_id
            WHERE ae.id = ?
            """,
            (event_id,),
        ).fetchone()
    if not row:
        return None
    return activity_event_row(row)


def record_activity_event(
    project_id: Optional[str],
    event_type: str,
    title: str,
    summary: str,
    event_status: str = "info",
    actor: str = "sprintos",
    related_type: Optional[str] = None,
    related_id: Optional[str] = None,
    next_tiny_action: Optional[str] = None,
    report_path: Optional[str] = None,
    metadata: Optional[Dict[str, Any]] = None,
) -> Optional[Dict[str, Any]]:
    try:
        clean_title = activity_redact_text(title, limit=140)
        clean_summary = activity_redact_text(summary, limit=500)
        if not clean_title or not clean_summary:
            return None
        created_at = now_iso()
        event_id = str(uuid.uuid4())
        normalized_status = normalize_activity_event_status(event_status)
        normalized_actor = normalize_activity_actor(actor)
        normalized_related_type = normalize_activity_related_type(related_type)
        clean_next_action = activity_redact_text(next_tiny_action, limit=240) if next_tiny_action else None
        clean_report_path = activity_redact_text(report_path, limit=300) if report_path else None
        clean_related_id = activity_redact_text(related_id, limit=100) if related_id else None
        clean_project_id = str(project_id or "").strip() or None
        safe_metadata = activity_sanitize_metadata(metadata or {})
        with db() as conn:
            conn.execute(
                """
                INSERT INTO activity_events (
                    id, project_id, created_at, event_type, event_status, title, summary,
                    actor, related_type, related_id, next_tiny_action, report_path, metadata_json
                )
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    event_id,
                    clean_project_id,
                    created_at,
                    activity_redact_text(event_type, limit=80) or "activity",
                    normalized_status,
                    clean_title,
                    clean_summary,
                    normalized_actor,
                    normalized_related_type,
                    clean_related_id,
                    clean_next_action,
                    clean_report_path,
                    json.dumps(safe_metadata, sort_keys=True),
                ),
            )
            if clean_project_id:
                conn.execute("UPDATE projects SET updated_at = ? WHERE id = ?", (created_at, clean_project_id))
            conn.commit()
        return get_activity_event(event_id)
    except Exception:
        return None


def get_project_timeline(project_id: str, limit: int = 50) -> List[Dict[str, Any]]:
    try:
        max_items = max(1, min(int(limit), 200))
    except (TypeError, ValueError):
        max_items = 50
    with db() as conn:
        rows = conn.execute(
            """
            SELECT ae.*, p.title AS project_title
            FROM activity_events ae
            LEFT JOIN projects p ON p.id = ae.project_id
            WHERE ae.project_id = ?
            ORDER BY ae.created_at DESC, ae.rowid DESC
            LIMIT ?
            """,
            (project_id, max_items),
        ).fetchall()
    return [activity_event_row(row) for row in rows]


