def project_activity_count(project_id: str) -> int:
    with db() as conn:
        row = conn.execute("SELECT COUNT(*) AS count FROM activity_events WHERE project_id = ?", (project_id,)).fetchone()
    return int((row["count"] if row else 0) or 0)


def global_activity_count() -> int:
    with db() as conn:
        row = conn.execute("SELECT COUNT(*) AS count FROM activity_events").fetchone()
    return int((row["count"] if row else 0) or 0)


def activity_event_markdown(events: List[Dict[str, Any]], heading: str, *, include_project: bool = False) -> str:
    lines = [f"# {heading}", ""]
    if not events:
        lines.extend(["No activity recorded yet.", ""])
        return "\n".join(lines)
    for event in events:
        project_prefix = ""
        if include_project and str(event.get("project_title") or "").strip():
            project_prefix = f"{event.get('project_title')} — "
        lines.extend(
            [
                f"## {event.get('created_at') or ''} — {project_prefix}{event.get('title') or 'Activity'}",
                f"- Status: {event.get('event_status') or 'info'}",
                f"- Actor: {event.get('actor') or 'sprintos'}",
                f"- Type: {event.get('event_type') or 'activity'}",
                f"- Summary: {event.get('summary') or ''}",
                f"- Next tiny action: {event.get('next_tiny_action') or 'n/a'}",
                f"- Report path: {event.get('report_path') or 'n/a'}",
                "",
            ]
        )
    return "\n".join(lines).strip() + "\n"


def project_timeline_markdown(project: Dict[str, Any], limit: int = 50) -> str:
    title = str(project.get("title") or (project.get("sprint") or {}).get("title") or "Sprint")
    return activity_event_markdown(get_project_timeline(str(project.get("id") or ""), limit=limit), f"Activity Timeline — {title}")


def activity_status_from_pipeline_status(status: Any) -> str:
    value = str(status or "").strip().lower()
    if value == "failed":
        return "failed"
    if value in {"partial", "completed_with_warnings"}:
        return "warning"
    return "success"


def activity_status_from_verification_status(status: Any) -> str:
    value = str(status or "").strip().lower()
    if value == "failed":
        return "failed"
    if value in {"partial", "passed_with_warnings"}:
        return "warning"
    return "success"


def activity_status_from_workspace_sync_status(status: Any) -> str:
    value = str(status or "").strip().lower()
    if value == "failed":
        return "failed"
    if value in {"partial", "passed_with_warnings"}:
        return "warning"
    return "success"


def activity_status_from_release_status(status: Any) -> str:
    value = str(status or "").strip().lower()
    if value == "blocked":
        return "blocked"
    if value in {"partial", "ready_with_warnings"}:
        return "warning"
    return "success"


def activity_status_from_project_status(status: Any) -> str:
    value = str(status or "").strip().lower()
    if value == "done":
        return "success"
    if value in {"parked", "abandoned"}:
        return "warning"
    return "info"


def default_next_tiny_action(sprint: Dict[str, Any]) -> str:
    restart = sprint.get("restart_card") or {}
    action = str(restart.get("next_tiny_action") or "").strip()
    vague_prefixes = ("continue ", "continue working", "improve ", "research ", "work on ", "make progress")
    if action and not any(action.lower().startswith(prefix) for prefix in vague_prefixes):
        return action
    artifacts = regular_artifacts(sprint)
    if artifacts:
        filename = sanitize_filename(str(artifacts[0].get("filename", "")) or "artifact.md")
        return f"Open {filename} and finish the first unfinished section."
    handoff = sprint.get("codex_handoff") or {}
    filename = str(handoff.get("filename") or "").strip()
    if filename:
        return f"Open {filename} and paste it into Codex."
    return "Run the smoke script."


def default_current_blocker(sprint: Dict[str, Any]) -> str:
    restart = sprint.get("restart_card") or {}
    blocker = str(restart.get("blocker_to_watch") or "").strip()
    return blocker or "No blocker recorded yet."


def build_resume_summary(raw_idea: str, desired_output: str, sprint: Dict[str, Any], last_progress_note: str = "") -> str:
    restart = sprint.get("restart_card") or {}
    parts = [
        str(sprint.get("one_sentence") or "").strip(),
        f"Best first version: {str(sprint.get('best_first_version') or '').strip()}",
        f"Where you left off: {str(restart.get('where_left_off') or '').strip()}",
    ]
    if last_progress_note:
        parts.append(f"Last progress note: {last_progress_note.strip()}")
    cleaned = [first_sentence(part) for part in parts if str(part).strip() and not part.endswith(": ")]
    if cleaned:
        return " ".join(cleaned)
    goal = desired_output.strip() or "one visible finished artifact"
    return f"This project exists to turn the idea '{raw_idea.strip()}' into {goal}."


def project_restart_goal(project: Dict[str, Any]) -> str:
    sprint = project.get("sprint") or {}
    desired_output = str(project.get("desired_output") or "").strip()
    best_first = str(sprint.get("best_first_version") or "").strip()
    done_definition = str(sprint.get("done_definition") or "").strip()
    return desired_output or best_first or done_definition or "one visible finished artifact"


def hydrate_project_resume_fields(project: Dict[str, Any]) -> Dict[str, Any]:
    sprint = project.get("sprint") or {}
    notes = project.get("progress_notes") or []
    latest_note = str(project.get("last_progress_note") or "").strip()
    if not latest_note and notes:
        latest_note = str(notes[0].get("note") or "").strip()
    project["status"] = normalize_project_status(project.get("status"))
    project["last_progress_note"] = latest_note
    project["next_tiny_action"] = str(project.get("next_tiny_action") or "").strip() or default_next_tiny_action(sprint)
    project["current_blocker"] = str(project.get("current_blocker") or "").strip() or default_current_blocker(sprint)
    project["last_resume_summary"] = str(project.get("last_resume_summary") or "").strip() or build_resume_summary(
        str(project.get("raw_idea") or ""),
        str(project.get("desired_output") or ""),
        sprint,
        latest_note,
    )
    return project


def backfill_resume_fields(conn: sqlite3.Connection) -> None:
    rows = conn.execute(
        "SELECT id, raw_idea, desired_output, status, sprint_json, last_resume_summary, next_tiny_action, current_blocker, last_progress_note, created_at, updated_at FROM projects"
    ).fetchall()
    for row in rows:
        sprint = safe_json_loads(row["sprint_json"], {}) or {}
        note_row = conn.execute(
            "SELECT note FROM progress_notes WHERE project_id = ? ORDER BY created_at DESC LIMIT 1",
            (row["id"],),
        ).fetchone()
        last_note = str(row["last_progress_note"] or (note_row["note"] if note_row else "") or "").strip()
        summary = str(row["last_resume_summary"] or "").strip() or build_resume_summary(
            str(row["raw_idea"] or ""),
            str(row["desired_output"] or ""),
            sprint,
            last_note,
        )
        next_action = str(row["next_tiny_action"] or "").strip() or default_next_tiny_action(sprint)
        blocker = str(row["current_blocker"] or "").strip() or default_current_blocker(sprint)
        status = normalize_project_status(row["status"])
        updated_at = str(row["updated_at"] or row["created_at"] or now_iso())
        conn.execute(
            """
            UPDATE projects
            SET status = ?, last_resume_summary = ?, next_tiny_action = ?, current_blocker = ?, last_progress_note = ?, updated_at = ?
            WHERE id = ?
            """,
            (status, summary, next_action, blocker, last_note, updated_at, row["id"]),
        )


def focus_session_metadata_json(value: Any) -> str:
    if not isinstance(value, dict):
        value = {}
    return json.dumps(value, sort_keys=True)


def focus_session_source_action_spec(action_id: str) -> Dict[str, str]:
    return COMMAND_CENTER_ACTION_SPECS.get(action_id, COMMAND_CENTER_ACTION_SPECS["none"])


def focus_session_elapsed_minutes(started_at: str, ended_at: str = "") -> int:
    start = command_center_timestamp(started_at)
    finish = command_center_timestamp(ended_at) if ended_at else _dt.datetime.now()
    if finish < start:
        finish = start
    elapsed_seconds = int((finish - start).total_seconds())
    return max(0, elapsed_seconds // 60)


def focus_session_checklist(session: Dict[str, Any]) -> List[str]:
    action_label = str(session.get("source_action_label") or focus_session_source_action_spec(str(session.get("source_action_id") or "")).get("label") or "the next action")
    return [
        f"Start with this exact move: {str(session.get('next_tiny_action') or '').strip()}",
        f"Stop when this is true: {str(session.get('done_definition') or '').strip()}",
        f"Do not drift into adjacent work. This session is only for {action_label.lower()}.",
    ]


def focus_session_response(row: sqlite3.Row | Dict[str, Any]) -> Dict[str, Any]:
    data = dict(row)
    metadata = safe_json_loads(str(data.get("metadata_json") or "{}"), {}) or {}
    focus_session_id = str(data.get("id") or metadata.get("focus_session_id") or "")
    session_status = normalize_focus_session_status(data.get("session_status") or metadata.get("session_status") or "planned")
    source_action_id = str(data.get("source_action_id") or metadata.get("source_action_id") or "")
    report_path = Path(str(data.get("report_path") or metadata.get("report_path") or ""))
    report_exists = report_path.exists() and report_path.is_dir()
    result = {
        "id": focus_session_id,
        "focus_session_id": focus_session_id,
        "project_id": str(data.get("project_id") or metadata.get("project_id") or ""),
        "created_at": str(data.get("created_at") or metadata.get("created_at") or ""),
        "updated_at": str(data.get("updated_at") or metadata.get("updated_at") or ""),
        "started_at": str(data.get("started_at") or metadata.get("started_at") or ""),
        "ended_at": str(data.get("ended_at") or metadata.get("ended_at") or ""),
        "session_status": session_status,
        "timebox_minutes": int(data.get("timebox_minutes") or metadata.get("timebox_minutes") or 30),
        "source_action_id": source_action_id,
        "source_action_label": str(metadata.get("source_action_label") or focus_session_source_action_spec(source_action_id).get("label") or ""),
        "title": str(data.get("title") or metadata.get("title") or ""),
        "done_definition": str(data.get("done_definition") or metadata.get("done_definition") or ""),
        "next_tiny_action": str(data.get("next_tiny_action") or metadata.get("next_tiny_action") or ""),
        "not_to_do": str(data.get("not_to_do") or metadata.get("not_to_do") or ""),
        "progress_note": str(data.get("progress_note") or metadata.get("progress_note") or ""),
        "outcome": str(data.get("outcome") or metadata.get("outcome") or ""),
        "report_path": str(report_path) if report_exists else "",
        "report_url": focus_session_report_url(focus_session_id) if report_exists else "",
        "zip_url": focus_session_zip_url(focus_session_id) if report_exists else "",
        "metadata": metadata,
    }
    result["elapsed_minutes"] = focus_session_elapsed_minutes(result["started_at"], result["ended_at"])
    result["timebox_elapsed"] = result["elapsed_minutes"] >= int(result["timebox_minutes"] or 0)
    result["is_active"] = session_status == "active"
    result["checklist"] = list(metadata.get("checklist") or focus_session_checklist(result))
    return result


def get_focus_session(focus_session_id: str) -> Optional[Dict[str, Any]]:
    with db() as conn:
        row = conn.execute("SELECT * FROM focus_sessions WHERE id = ?", (focus_session_id,)).fetchone()
    if not row:
        return None
    return focus_session_response(row)


def latest_project_focus_session(project_id: str) -> Optional[Dict[str, Any]]:
    with db() as conn:
        row = conn.execute(
            "SELECT * FROM focus_sessions WHERE project_id = ? ORDER BY created_at DESC, rowid DESC LIMIT 1",
            (project_id,),
        ).fetchone()
    if not row:
        return None
    return focus_session_response(row)


def active_project_focus_session(project_id: str) -> Optional[Dict[str, Any]]:
    with db() as conn:
        row = conn.execute(
            """
            SELECT * FROM focus_sessions
            WHERE project_id = ? AND session_status = 'active'
            ORDER BY created_at DESC, rowid DESC
            LIMIT 1
            """,
            (project_id,),
        ).fetchone()
    if not row:
        return None
    return focus_session_response(row)


def focus_session_report_url(focus_session_id: str, filename: str = "focus-session-report.md") -> str:
    return f"/api/focus_session_report?id={urllib.parse.quote(focus_session_id)}&file={urllib.parse.quote(filename)}"


def focus_session_zip_url(focus_session_id: str) -> str:
    return f"/api/focus_session_zip?id={urllib.parse.quote(focus_session_id)}"


def focus_session_file_path(focus_session: Dict[str, Any], filename: str) -> Path:
    return safe_flat_file_path(
        Path(str(focus_session.get("report_path") or "")),
        filename,
        FOCUS_SESSION_REPORT_FILES,
        "Invalid focus session report file",
    )


def build_focus_session_zip(focus_session: Dict[str, Any]) -> Tuple[str, bytes]:
    filename = sanitize_filename(
        f"{slugify(str((focus_session.get('metadata') or {}).get('project_title') or 'focus-session'), 'focus-session')}-{prototype_folder_timestamp(str(focus_session.get('created_at') or now_iso()))}.zip",
        default_stem="focus-session",
        default_suffix=".zip",
    )
    payload = build_zip_from_reader(
        FOCUS_SESSION_REPORT_FILES,
        lambda name: focus_session_file_path(focus_session, name).read_text(encoding="utf-8"),
    )
    return filename, payload


def create_focus_session_report_dir(project_title: str, created_at: str) -> Path:
    stamp = prototype_folder_timestamp(created_at)
    base_name = f"{slugify(project_title, 'project')}-{stamp}"
    report_dir = focus_session_export_dir() / base_name
    counter = 2
    while report_dir.exists():
        report_dir = focus_session_export_dir() / f"{base_name}-{counter}"
        counter += 1
    report_dir.mkdir(parents=True, exist_ok=True)
    return report_dir


def focus_session_generation_details(project: Dict[str, Any], command_summary: Dict[str, Any], action_id: str) -> Dict[str, str]:
    recommended = command_summary.get("recommended_action") or {}
    source_label = focus_session_source_action_spec(action_id).get("label") or action_id.replace("_", " ").title()
    default_next_tiny_action = command_summary.get("next_tiny_action") or project.get("next_tiny_action") or "Open the right SprintOS panel and start the first tiny step."
    defaults = {
        "generate_prototype": {
            "title": "Generate a local prototype package",
            "done_definition": "Prototype package exists locally with preview, ZIP, and codex-build-prompt.md.",
            "next_tiny_action": "Open the Prototype panel and generate the first local prototype package.",
            "not_to_do": "Do not redesign the concept or rewrite the scope before the package exists.",
        },
        "run_pipeline": {
            "title": "Create the next testable app draft",
            "done_definition": "The app draft and source package exist locally, with a clear next tiny action.",
            "next_tiny_action": "Create the testable app once with the current local defaults.",
            "not_to_do": "Do not manually recreate app packages one by one before this run finishes.",
        },
        "export_workspace": {
            "title": "Prepare a stable app workspace",
            "done_definition": "Workspace exists and CODEX_START_HERE.md is available.",
            "next_tiny_action": "Prepare the latest app source package for safe Codex editing.",
            "not_to_do": "Do not start redesigning the generated app yet.",
        },
        "create_workspace_snapshot": {
            "title": "Create a safe workspace snapshot",
            "done_definition": "Snapshot folder exists with snapshot-report.md and restore-instructions.md.",
            "next_tiny_action": "Create one local snapshot before more workspace changes.",
            "not_to_do": "Do not keep editing the workspace before the snapshot finishes.",
        },
        "sync_workspace": {
            "title": "Check app workspace changes",
            "done_definition": "The app-change report exists and the next Codex follow-up prompt is generated.",
            "next_tiny_action": "Check app changes once and read the changed-files summary first.",
            "not_to_do": "Do not manually inspect every file unless sync reports a blocker.",
        },
        "run_verification": {
            "title": "Run one clean verification pass",
            "done_definition": "The app test report exists with a clear pass, warning, or blocker outcome.",
            "next_tiny_action": "Test the latest local app artifacts.",
            "not_to_do": "Do not start fixing speculative problems before the report names the first blocker.",
        },
        "create_release_pack": {
            "title": "Create testing package",
            "done_definition": "The testing package ZIP exists with RELEASE.md, TESTER_INSTRUCTIONS.md, and CODEX_NEXT_PROMPT.md.",
            "next_tiny_action": "Create the testing package and read the warnings before doing anything else.",
            "not_to_do": "Do not deploy publicly before reading release warnings.",
        },
        "copy_codex_fix_prompt": {
            "title": "Extract the verification fix path",
            "done_definition": "The latest verification fix prompt is copied or saved and the first fix target is clear.",
            "next_tiny_action": "Open the latest verification report and capture the first fix target.",
            "not_to_do": "Do not start broad cleanup before the first blocker is explicit.",
        },
        "copy_release_codex_prompt": {
            "title": "Extract the release-fix handoff",
            "done_definition": "The latest release-pack Codex prompt is copied or saved and the blocker is explicit.",
            "next_tiny_action": "Open the latest release pack prompt and identify the one blocker to clear next.",
            "not_to_do": "Do not create another release pack until the current blocker is understood.",
        },
        "share_with_testers": {
            "title": "Prepare one tester handoff",
            "done_definition": "Tester message is ready and the exact release pack path is confirmed.",
            "next_tiny_action": "Open the latest release pack and copy the tester message.",
            "not_to_do": "Do not expand the tester list or rewrite the product scope during this session.",
        },
        "open_workspace": {
            "title": "Work inside the exported workspace",
            "done_definition": "The current workspace target is open and the first contained task is clearly defined.",
            "next_tiny_action": "Open the workspace README or CODEX_START_HERE.md and identify the first contained task.",
            "not_to_do": "Do not edit SprintOS internals from the generated workspace session.",
        },
    }
    details = defaults.get(action_id, {})
    title = str(details.get("title") or f"Focus on {source_label.lower()}").strip()
    done_definition = str(details.get("done_definition") or recommended.get("expected_output") or "").strip() or f"Done when {source_label.lower()} has one visible finished output."
    next_tiny_action = str(details.get("next_tiny_action") or default_next_tiny_action).strip() or "Take the first tiny step."
    not_to_do = str(details.get("not_to_do") or "").strip() or "Do not expand scope or start adjacent work during this session."
    return {
        "title": title,
        "done_definition": done_definition,
        "next_tiny_action": next_tiny_action,
        "not_to_do": not_to_do,
        "source_action_id": action_id,
    }


def focus_session_is_codex_relevant(action_id: str) -> bool:
    return action_id in {
        "export_workspace",
        "sync_workspace",
        "run_verification",
        "create_release_pack",
        "copy_codex_fix_prompt",
        "copy_release_codex_prompt",
        "open_workspace",
    }


def focus_session_resume_note(session: Dict[str, Any], *, blocker: str = "") -> str:
    lines = [
        f"# Focus Session {str(session.get('session_status') or '').title()}",
        "",
        f"- What I did: {str(session.get('outcome') or session.get('progress_note') or 'Captured session state.').strip()}",
        f"- Where I stopped: {str(session.get('progress_note') or session.get('outcome') or 'At the end of the current session.').strip()}",
        f"- Next tiny action: {str(session.get('next_tiny_action') or '').strip()}",
    ]
    if blocker.strip():
        lines.append(f"- Blocker: {blocker.strip()}")
    return "\n".join(lines).strip() + "\n"


def focus_session_codex_next_prompt(project: Dict[str, Any], session: Dict[str, Any]) -> str:
    action_id = str(session.get("source_action_id") or "")
    if not focus_session_is_codex_relevant(action_id):
        return "No Codex handoff is needed yet. Finish the next SprintOS action first.\n"
    source_label = str(session.get("source_action_label") or focus_session_source_action_spec(action_id).get("label") or action_id)
    verification = "\n".join(DEFAULT_VERIFICATION_COMMANDS)
    return textwrap.dedent(
        f"""\
        # Focus Session Codex Follow-Up — {project.get("title") or "Sprint"}

        Read AGENTS.md first.

        ## Source Action
        {source_label}

        ## Session Outcome
        {str(session.get("outcome") or "No explicit outcome recorded.").strip()}

        ## Where I Stopped
        {str(session.get("progress_note") or "No progress note recorded.").strip()}

        ## Done Definition
        {str(session.get("done_definition") or "").strip()}

        ## Next Tiny Action
        {str(session.get("next_tiny_action") or "").strip()}

        ## Constraints
        - Keep SprintOS local-first.
        - Do not expose API keys.
        - Do not deploy automatically.
        - Do not invoke Codex automatically from SprintOS.
        - Do not overbuild.

        ## Verification
        ```bash
        {verification}
        ```
        """
    ).strip() + "\n"


def focus_session_report_markdown(project: Dict[str, Any], session: Dict[str, Any], command_center: Dict[str, Any], codex_prompt: str) -> str:
    recommended = command_center.get("recommended_action") or {}
    next_action_label = str(recommended.get("label") or "No action").strip()
    next_action_reason = str(recommended.get("reason") or "").strip()
    lines = [
        f"# Focus Session Report — {project.get('title') or 'Sprint'}",
        "",
        "## Project Title",
        str(project.get("title") or ""),
        "",
        "## Session Title",
        str(session.get("title") or ""),
        "",
        "## Timebox",
        f"{int(session.get('timebox_minutes') or 0)} minutes",
        "",
        "## Source Action",
        str(session.get("source_action_label") or session.get("source_action_id") or ""),
        "",
        "## Done Definition",
        str(session.get("done_definition") or ""),
        "",
        "## Not To Do",
        str(session.get("not_to_do") or ""),
        "",
        "## Progress Note",
        str(session.get("progress_note") or "No progress note saved."),
        "",
        "## Outcome",
        str(session.get("outcome") or "No explicit outcome recorded."),
        "",
        "## Status",
        str(session.get("session_status") or ""),
        "",
        "## Next Tiny Action",
        str(session.get("next_tiny_action") or ""),
        "",
        "## Suggested Next SprintOS Action",
        f"{next_action_label} — {next_action_reason}".strip(" —"),
        "",
        "## Suggested Next Codex Prompt If Relevant",
        str(codex_prompt or "No Codex handoff is needed yet."),
    ]
    return "\n".join(lines).strip() + "\n"


def write_focus_session_report_folder(project: Dict[str, Any], session: Dict[str, Any], command_center: Dict[str, Any], report_dir: Optional[Path] = None) -> Path:
    report_dir = report_dir or create_focus_session_report_dir(str(project.get("title") or "project"), str(session.get("ended_at") or session.get("created_at") or now_iso()))
    blocker = ""
    if str(session.get("session_status") or "") == "stopped":
        blocker = str(session.get("outcome") or "").strip()
    resume_note = focus_session_resume_note(session, blocker=blocker)
    codex_prompt = focus_session_codex_next_prompt(project, session)
    recommended = command_center.get("recommended_action") or {}
    next_action_text = "\n".join(
        [
            str(command_center.get("next_tiny_action") or "").strip(),
            "",
            f"Suggested SprintOS action: {str(recommended.get('label') or 'No action').strip()}",
            str(recommended.get("reason") or "").strip(),
        ]
    ).strip() + "\n"
    summary_json = json.dumps(
        {
            "focus_session_id": session["focus_session_id"],
            "project_id": project["id"],
            "project_title": project.get("title") or "",
            "created_at": session.get("created_at") or "",
            "updated_at": session.get("updated_at") or "",
            "started_at": session.get("started_at") or "",
            "ended_at": session.get("ended_at") or "",
            "session_status": session.get("session_status") or "",
            "timebox_minutes": session.get("timebox_minutes") or 0,
            "source_action_id": session.get("source_action_id") or "",
            "source_action_label": session.get("source_action_label") or "",
            "title": session.get("title") or "",
            "done_definition": session.get("done_definition") or "",
            "next_tiny_action": session.get("next_tiny_action") or "",
            "not_to_do": session.get("not_to_do") or "",
            "progress_note": session.get("progress_note") or "",
            "outcome": session.get("outcome") or "",
            "report_path": str(report_dir),
            "recommended_action": {
                "action_id": recommended.get("action_id") or "",
                "label": recommended.get("label") or "",
                "reason": recommended.get("reason") or "",
            },
        },
        indent=2,
    ) + "\n"
    file_contents = {
        "focus-session-report.md": focus_session_report_markdown(project, session, command_center, codex_prompt),
        "session-summary.json": summary_json,
        "next-action.md": next_action_text,
        "codex-next-prompt.md": codex_prompt.strip() + "\n",
        "resume-note.md": resume_note,
    }
    return write_text_files(report_dir, file_contents)


def create_focus_session(project_id: str, timebox_minutes: Any, action_id: Optional[str] = None) -> Dict[str, Any]:
    project = get_project(project_id)
    if not project:
        raise ValueError("Project not found")
    active_session = project.get("active_focus_session") or active_project_focus_session(project_id)
    if active_session:
        raise ValueError("An active focus session already exists for this project")
    command_summary = project.get("command_center") or build_project_command_summary(project)
    recommended = command_summary.get("recommended_action") or {}
    resolved_action_id = str(action_id or recommended.get("source_action_id") or recommended.get("action_id") or "").strip()
    if resolved_action_id in {"start_focus_session", "continue_focus_session", "complete_focus_session"}:
        resolved_action_id = str(recommended.get("source_action_id") or "").strip()
    if not resolved_action_id or resolved_action_id == "none":
        raise ValueError("No recommended action is available for a focus session")
    timebox = normalize_focus_session_timebox_minutes(timebox_minutes)
    details = focus_session_generation_details(project, command_summary, resolved_action_id)
    created_at = now_iso()
    focus_session_id = str(uuid.uuid4())
    source_spec = focus_session_source_action_spec(resolved_action_id)
    metadata = {
        "focus_session_id": focus_session_id,
        "project_id": project_id,
        "project_title": str(project.get("title") or ""),
        "created_at": created_at,
        "updated_at": created_at,
        "started_at": created_at,
        "session_status": "active",
        "timebox_minutes": timebox,
        "source_action_id": resolved_action_id,
        "source_action_label": source_spec.get("label") or "",
        "source_action_reason": str(recommended.get("source_action_reason") or recommended.get("reason") or ""),
        "checklist": [],
    }
    session = {
        "focus_session_id": focus_session_id,
        "project_id": project_id,
        "created_at": created_at,
        "updated_at": created_at,
        "started_at": created_at,
        "ended_at": "",
        "session_status": "active",
        "timebox_minutes": timebox,
        "source_action_id": resolved_action_id,
        "source_action_label": metadata["source_action_label"],
        "title": details["title"],
        "done_definition": details["done_definition"],
        "next_tiny_action": details["next_tiny_action"],
        "not_to_do": details["not_to_do"],
        "progress_note": "",
        "outcome": "",
        "report_path": "",
        "metadata": metadata,
    }
    metadata["checklist"] = focus_session_checklist(session)
    with db() as conn:
        conn.execute(
            """
            INSERT INTO focus_sessions (
                id, project_id, created_at, updated_at, started_at, ended_at, session_status,
                timebox_minutes, source_action_id, title, done_definition, next_tiny_action,
                not_to_do, progress_note, outcome, report_path, metadata_json
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                focus_session_id,
                project_id,
                created_at,
                created_at,
                created_at,
                None,
                "active",
                timebox,
                resolved_action_id,
                details["title"],
                details["done_definition"],
                details["next_tiny_action"],
                details["not_to_do"],
                "",
                "",
                "",
                focus_session_metadata_json(metadata),
            ),
        )
        conn.commit()
    created = get_focus_session(focus_session_id)
    if not created:
        raise ValueError("Focus session was not created")
    refreshed_project = get_project(project_id) or project
    created["command_center"] = refreshed_project.get("command_center") or build_project_command_summary(refreshed_project)
    record_activity_event(
        project_id,
        "focus_session_started",
        "Focus session started",
        f"Started a {timebox}-minute focus session for {created.get('title') or 'the recommended action'}.",
        event_status="info",
        actor="user",
        related_type="focus_session",
        related_id=focus_session_id,
        next_tiny_action=str(created.get("next_tiny_action") or ""),
        metadata={"source_action_id": resolved_action_id, "timebox_minutes": timebox},
    )
    return created


def update_focus_session(
    focus_session_id: str,
    *,
    progress_note: Optional[str] = None,
    outcome: Optional[str] = None,
    session_status: Optional[str] = None,
) -> Dict[str, Any]:
    session = get_focus_session(focus_session_id)
    if not session:
        raise ValueError("Focus session not found")
    updated_at = now_iso()
    next_status = session["session_status"] if session_status is None else normalize_focus_session_status(session_status)
    ended_at = session.get("ended_at") or ""
    if next_status in {"completed", "stopped", "abandoned"} and not ended_at:
        ended_at = updated_at
    metadata = dict(session.get("metadata") or {})
    metadata.update(
        {
            "updated_at": updated_at,
            "session_status": next_status,
            "progress_note": str(progress_note if progress_note is not None else session.get("progress_note") or ""),
            "outcome": str(outcome if outcome is not None else session.get("outcome") or ""),
        }
    )
    with db() as conn:
        conn.execute(
            """
            UPDATE focus_sessions
            SET updated_at = ?, ended_at = ?, session_status = ?, progress_note = ?, outcome = ?, metadata_json = ?
            WHERE id = ?
            """,
            (
                updated_at,
                ended_at or None,
                next_status,
                str(progress_note if progress_note is not None else session.get("progress_note") or ""),
                str(outcome if outcome is not None else session.get("outcome") or ""),
                focus_session_metadata_json(metadata),
                focus_session_id,
            ),
        )
        conn.commit()
    updated = get_focus_session(focus_session_id)
    if not updated:
        raise ValueError("Focus session not found after update")
    return updated


def finalize_focus_session(
    focus_session_id: str,
    *,
    final_status: str,
    outcome: str,
    progress_note: str = "",
) -> Dict[str, Any]:
    session = get_focus_session(focus_session_id)
    if not session:
        raise ValueError("Focus session not found")
    if session["session_status"] in {"completed", "stopped", "abandoned"}:
        raise ValueError("Focus session has already ended")
    project = get_project(session["project_id"])
    if not project:
        raise ValueError("Project not found")
    ended_at = now_iso()
    next_progress_note = progress_note.strip() or str(session.get("progress_note") or "").strip()
    next_outcome = outcome.strip()
    metadata = dict(session.get("metadata") or {})
    metadata.update(
        {
            "updated_at": ended_at,
            "ended_at": ended_at,
            "session_status": final_status,
            "progress_note": next_progress_note,
            "outcome": next_outcome,
        }
    )
    with db() as conn:
        conn.execute(
            """
            UPDATE focus_sessions
            SET updated_at = ?, ended_at = ?, session_status = ?, progress_note = ?, outcome = ?, metadata_json = ?
            WHERE id = ?
            """,
            (
                ended_at,
                ended_at,
                final_status,
                next_progress_note,
                next_outcome,
                focus_session_metadata_json(metadata),
                focus_session_id,
            ),
        )
        conn.commit()
    updated = get_focus_session(focus_session_id)
    if not updated:
        raise ValueError("Focus session not found after update")
    blocker = next_outcome if final_status == "stopped" else ""
    resume_note = focus_session_resume_note(updated, blocker=blocker)
    add_progress_note(updated["project_id"], resume_note.strip(), record_event=False)
    refreshed_project = get_project(updated["project_id"])
    if not refreshed_project:
        raise ValueError("Project not found after focus session update")
    command_center = refreshed_project.get("command_center") or build_project_command_summary(refreshed_project)
    report_dir = write_focus_session_report_folder(refreshed_project, updated, command_center)
    metadata = dict(updated.get("metadata") or {})
    metadata["report_path"] = str(report_dir)
    with db() as conn:
        conn.execute(
            "UPDATE focus_sessions SET report_path = ?, metadata_json = ?, updated_at = ? WHERE id = ?",
            (str(report_dir), focus_session_metadata_json(metadata), now_iso(), focus_session_id),
        )
        conn.commit()
    finalized = get_focus_session(focus_session_id)
    if not finalized:
        raise ValueError("Focus session not found after report generation")
    finalized["command_center"] = refreshed_project.get("command_center") or build_project_command_summary(refreshed_project)
    record_activity_event(
        finalized["project_id"],
        f"focus_session_{final_status}",
        "Focus session completed" if final_status == "completed" else "Focus session stopped",
        next_outcome,
        event_status="success" if final_status == "completed" else "warning",
        actor="user",
        related_type="focus_session",
        related_id=focus_session_id,
        next_tiny_action=str(finalized.get("next_tiny_action") or ""),
        report_path=str(finalized.get("report_path") or ""),
        metadata={"source_action_id": finalized.get("source_action_id"), "timebox_minutes": finalized.get("timebox_minutes")},
    )
    return finalized


def complete_focus_session(focus_session_id: str, outcome: str, progress_note: str = "") -> Dict[str, Any]:
    cleaned_outcome = str(outcome or "").strip()
    if not cleaned_outcome:
        raise ValueError("outcome is required")
    return finalize_focus_session(
        focus_session_id,
        final_status="completed",
        outcome=cleaned_outcome,
        progress_note=progress_note,
    )


def stop_focus_session(focus_session_id: str, reason: str = "", progress_note: str = "") -> Dict[str, Any]:
    cleaned_reason = str(reason or "").strip() or "Stopped before the done definition was met."
    return finalize_focus_session(
        focus_session_id,
        final_status="stopped",
        outcome=cleaned_reason,
        progress_note=progress_note,
    )


def normalize_feedback_choice(value: Any) -> Optional[str]:
    choice = str(value or "").strip().lower()
    return choice if choice in FEEDBACK_CHOICE_VALUES else None


def normalize_feedback_score(value: Any) -> Optional[int]:
    if value is None or str(value).strip() == "":
        return None
    try:
        score = int(value)
    except (TypeError, ValueError):
        return None
    return score if 1 <= score <= 5 else None


def normalize_feedback_text(value: Any) -> str:
    return str(value or "").strip()


def feedback_storage_scope(project: Dict[str, Any], prototype_id: Optional[str]) -> Tuple[str, Optional[str]]:
    latest_prototype = project.get("latest_prototype") or latest_project_prototype(project["id"], include_prompt=False)
    if prototype_id:
        return "prototype", prototype_id
    if latest_prototype:
        return "prototype", str(latest_prototype.get("id") or "")
    return "project", None


def validate_project_and_prototype(project_id: str, prototype_id: Optional[str]) -> Optional[Dict[str, Any]]:
    if not project_id:
        raise ValueError("project_id is required")
    project = get_project(project_id)
    if not project:
        raise ValueError("Project not found")
    if prototype_id:
        prototype = get_prototype(prototype_id, include_prompt=False)
        if not prototype:
            raise ValueError("Prototype not found")
        if str(prototype.get("project_id") or "") != project_id:
            raise ValueError("Prototype does not belong to this project")
        return prototype
    return project.get("latest_prototype") or latest_project_prototype(project_id, include_prompt=False)


def feedback_row_to_dict(row: sqlite3.Row | Dict[str, Any]) -> Dict[str, Any]:
    data = dict(row)
    return {
        "id": str(data.get("id") or ""),
        "prototype_id": str(data.get("prototype_id") or "") or None,
        "project_id": str(data.get("project_id") or ""),
        "created_at": str(data.get("created_at") or ""),
        "tester_label": normalize_feedback_text(data.get("tester_label")),
        "source": normalize_feedback_text(data.get("source")) or "manual",
        "rating": normalize_feedback_score(data.get("rating")),
        "pain_level": normalize_feedback_score(data.get("pain_level")),
        "would_use": normalize_feedback_choice(data.get("would_use")),
        "would_pay": normalize_feedback_choice(data.get("would_pay")),
        "confusing_parts": normalize_feedback_text(data.get("confusing_parts")),
        "missing_features": normalize_feedback_text(data.get("missing_features")),
        "favorite_part": normalize_feedback_text(data.get("favorite_part")),
        "freeform_feedback": normalize_feedback_text(data.get("freeform_feedback")),
        "raw_json": normalize_feedback_text(data.get("raw_json")),
    }


def feedback_query_parts(project_id: str, prototype_id: Optional[str]) -> Tuple[str, Tuple[Any, ...]]:
    if prototype_id:
        return "project_id = ? AND prototype_id = ?", (project_id, prototype_id)
    return "project_id = ?", (project_id,)


def list_feedback(project_id: str, prototype_id: Optional[str] = None, limit: Optional[int] = None) -> List[Dict[str, Any]]:
    clause, params = feedback_query_parts(project_id, prototype_id)
    query = f"SELECT * FROM prototype_feedback WHERE {clause} ORDER BY created_at DESC, rowid DESC"
    if limit is not None:
        query += f" LIMIT {int(limit)}"
    with db() as conn:
        rows = conn.execute(query, params).fetchall()
    return [feedback_row_to_dict(row) for row in rows]


def feedback_count(project_id: str, prototype_id: Optional[str] = None) -> int:
    clause, params = feedback_query_parts(project_id, prototype_id)
    with db() as conn:
        row = conn.execute(f"SELECT COUNT(*) AS count FROM prototype_feedback WHERE {clause}", params).fetchone()
    return int((row["count"] if row else 0) or 0)


def latest_iteration(project_id: str, prototype_id: Optional[str] = None) -> Optional[Dict[str, Any]]:
    clause, params = feedback_query_parts(project_id, prototype_id)
    with db() as conn:
        row = conn.execute(
            f"SELECT * FROM prototype_iterations WHERE {clause} ORDER BY created_at DESC, rowid DESC LIMIT 1",
            params,
        ).fetchone()
    if not row:
        return None
    data = dict(row)
    return {
        "id": str(data.get("id") or ""),
        "project_id": str(data.get("project_id") or ""),
        "prototype_id": str(data.get("prototype_id") or "") or None,
        "created_at": str(data.get("created_at") or ""),
        "feedback_count": int(data.get("feedback_count") or 0),
        "summary": str(data.get("summary") or ""),
        "iteration_brief": str(data.get("iteration_brief") or ""),
        "codex_prompt": str(data.get("codex_prompt") or ""),
        "decision": str(data.get("decision") or ""),
        "suggested_next_tiny_action": str(data.get("suggested_next_tiny_action") or ""),
    }


def latest_iteration_for_project(project: Dict[str, Any], prototype_id: Optional[str] = None) -> Optional[Dict[str, Any]]:
    scope, scoped_prototype_id = feedback_storage_scope(project, prototype_id)
    return latest_iteration(project["id"], scoped_prototype_id if scope == "prototype" else None)


def feedback_summary_blob(project: Dict[str, Any], prototype_id: Optional[str] = None) -> Dict[str, Any]:
    scope, scoped_prototype_id = feedback_storage_scope(project, prototype_id)
    entries = list_feedback(project["id"], scoped_prototype_id if scope == "prototype" else None, limit=5)
    count = feedback_count(project["id"], scoped_prototype_id if scope == "prototype" else None)
    iteration = latest_iteration(project["id"], scoped_prototype_id if scope == "prototype" else None)
    return {
        "scope": scope,
        "prototype_id": scoped_prototype_id if scope == "prototype" else None,
        "count": count,
        "recent": entries,
        "latest_iteration": iteration,
    }


def extract_feedback_entries_from_json(raw: Any) -> Tuple[List[Dict[str, Any]], List[str]]:
    warnings: List[str] = []
    if isinstance(raw, list):
        items = raw
    elif isinstance(raw, dict):
        if isinstance(raw.get("entries"), list):
            items = raw.get("entries") or []
        elif isinstance(raw.get("feedback_entries"), list):
            items = raw.get("feedback_entries") or []
        else:
            items = [raw]
    else:
        raise ValueError("Feedback JSON must be an object or array")
    entries: List[Dict[str, Any]] = []
    for idx, item in enumerate(items, start=1):
        if not isinstance(item, dict):
            warnings.append(f"Skipped feedback item {idx}: expected an object.")
            continue
        entries.append(item)
    if not entries and not warnings:
        warnings.append("No feedback entries were found in the JSON payload.")
    return entries, warnings


def add_feedback_entry(
    project_id: str,
    *,
    prototype_id: Optional[str] = None,
    tester_label: str = "",
    source: str = "manual",
    rating: Any = None,
    pain_level: Any = None,
    would_use: Any = None,
    would_pay: Any = None,
    confusing_parts: str = "",
    missing_features: str = "",
    favorite_part: str = "",
    freeform_feedback: str = "",
    raw_json: str = "",
    record_event: bool = True,
) -> Dict[str, Any]:
    prototype = validate_project_and_prototype(project_id, prototype_id)
    resolved_prototype_id = prototype_id or (str(prototype.get("id") or "") if prototype and prototype.get("id") else None)
    feedback_id = str(uuid.uuid4())
    created_at = now_iso()
    normalized_source = normalize_feedback_text(source) or "manual"
    with db() as conn:
        conn.execute(
            """
            INSERT INTO prototype_feedback (
                id, prototype_id, project_id, created_at, tester_label, source, rating, pain_level,
                would_use, would_pay, confusing_parts, missing_features, favorite_part, freeform_feedback, raw_json
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                feedback_id,
                resolved_prototype_id,
                project_id,
                created_at,
                normalize_feedback_text(tester_label),
                normalized_source,
                normalize_feedback_score(rating),
                normalize_feedback_score(pain_level),
                normalize_feedback_choice(would_use),
                normalize_feedback_choice(would_pay),
                normalize_feedback_text(confusing_parts),
                normalize_feedback_text(missing_features),
                normalize_feedback_text(favorite_part),
                normalize_feedback_text(freeform_feedback),
                normalize_feedback_text(raw_json),
            ),
        )
        conn.execute("UPDATE projects SET updated_at = ? WHERE id = ?", (created_at, project_id))
        conn.commit()
    result = {
        "feedback_id": feedback_id,
        "feedback_count": feedback_count(project_id, resolved_prototype_id),
        "prototype_id": resolved_prototype_id,
    }
    if record_event:
        record_activity_event(
            project_id,
            "feedback_added",
            "Feedback added",
            f"Saved feedback from {normalize_feedback_text(tester_label) or 'a tester'}.",
            event_status="info",
            actor="user",
            related_type="prototype",
            related_id=resolved_prototype_id,
            next_tiny_action="Review the feedback and generate an iteration brief when patterns are clear.",
            metadata={"feedback_id": feedback_id, "source": normalized_source},
        )
    return result


def import_feedback_json(project_id: str, json_text: str, prototype_id: Optional[str] = None) -> Dict[str, Any]:
    validate_project_and_prototype(project_id, prototype_id)
    if not normalize_feedback_text(json_text):
        raise ValueError("json_text is required")
    parsed = json.loads(json_text)
    entries, warnings = extract_feedback_entries_from_json(parsed)
    feedback_ids: List[str] = []
    resolved_prototype_id = prototype_id
    for item in entries:
        item_prototype_id = normalize_feedback_text(item.get("prototype_id")) or resolved_prototype_id
        try:
            saved = add_feedback_entry(
                project_id,
                prototype_id=item_prototype_id,
                tester_label=normalize_feedback_text(item.get("tester_label")),
                source=normalize_feedback_text(item.get("source")) or "imported_json",
                rating=item.get("rating"),
                pain_level=item.get("pain_level"),
                would_use=item.get("would_use"),
                would_pay=item.get("would_pay"),
                confusing_parts=normalize_feedback_text(item.get("confusing_parts")),
                missing_features=normalize_feedback_text(item.get("missing_features")),
                favorite_part=normalize_feedback_text(item.get("favorite_part")),
                freeform_feedback=normalize_feedback_text(item.get("freeform_feedback")),
                raw_json=json.dumps(item, indent=2),
                record_event=False,
            )
            feedback_ids.append(saved["feedback_id"])
            resolved_prototype_id = saved.get("prototype_id") or resolved_prototype_id
        except ValueError as exc:
            warnings.append(str(exc))
    count = feedback_count(project_id, resolved_prototype_id)
    response: Dict[str, Any] = {
        "feedback_count": count,
        "warnings": warnings,
    }
    if len(feedback_ids) == 1:
        response["feedback_id"] = feedback_ids[0]
    else:
        response["feedback_ids"] = feedback_ids
    if feedback_ids:
        record_activity_event(
            project_id,
            "feedback_imported",
            "Feedback imported",
            f"Imported {len(feedback_ids)} feedback entr{'y' if len(feedback_ids) == 1 else 'ies'} from JSON.",
            event_status="success",
            actor="user",
            related_type="prototype",
            related_id=resolved_prototype_id,
            next_tiny_action="Review imported feedback and generate an iteration brief when ready.",
            metadata={"imported_count": len(feedback_ids), "warnings": warnings[:3]},
        )
    return response


def normalize_release_iteration_decision(value: Any) -> str:
    decision = str(value or "").strip().lower()
    return decision if decision in RELEASE_ITERATION_DECISIONS else "test_more"


def release_feedback_redact_text(value: Any, limit: int = 1200) -> str:
    text = str(value or "")
    text = ACTIVITY_SECRET_ASSIGNMENT_PATTERN.sub(lambda m: f"{m.group(1)}=[redacted]", text)
    text = ACTIVITY_BEARER_PATTERN.sub("Bearer [redacted]", text)
    text = redact_text(text)
    text = re.sub(r"\s+", " ", text).strip()
    return text[:limit].rstrip(" ,;:") if text else ""


def release_feedback_sanitize_json(value: Any, *, depth: int = 0) -> Any:
    if depth > 4:
        return "[redacted]"
    if isinstance(value, dict):
        clean: Dict[str, Any] = {}
        for index, (key, item) in enumerate(value.items()):
            if index >= 20:
                break
            key_text = str(key).strip()[:80]
            lowered = key_text.lower()
            if lowered in ACTIVITY_METADATA_REDACTED_KEYS or "prompt" in lowered or "response" in lowered:
                continue
            if "authorization" in lowered or lowered.endswith("_token") or lowered.endswith("_secret") or lowered.endswith("_key"):
                continue
            if lowered.startswith("env") or lowered.endswith("_env"):
                continue
            clean[key_text] = release_feedback_sanitize_json(item, depth=depth + 1)
        return clean
    if isinstance(value, list):
        return [release_feedback_sanitize_json(item, depth=depth + 1) for item in value[:20]]
    if isinstance(value, str):
        return release_feedback_redact_text(value, limit=400)
    if isinstance(value, (int, float, bool)) or value is None:
        return value
    return release_feedback_redact_text(value, limit=400)


def release_feedback_raw_json_text(value: Any) -> str:
    if value is None or value == "":
        return ""
    parsed: Any = value
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return ""
        try:
            parsed = json.loads(text)
        except json.JSONDecodeError:
            return release_feedback_redact_text(text, limit=2000)
    sanitized = release_feedback_sanitize_json(parsed)
    return json.dumps(sanitized, indent=2, sort_keys=True)[:4000].rstrip() + "\n"


def release_feedback_metadata_json(value: Any) -> str:
    return json.dumps(release_feedback_sanitize_json(value), sort_keys=True)


def feedback_text_counter(entries: List[Dict[str, Any]], field: str) -> Counter:
    counts = Counter()
    for entry in entries:
        text = normalize_feedback_text(entry.get(field))
        if text:
            counts[text] += 1
    return counts


def most_common_feedback_text(entries: List[Dict[str, Any]], field: str) -> Tuple[str, int]:
    counts = feedback_text_counter(entries, field)
    if not counts:
        return "", 0
    text, count = counts.most_common(1)[0]
    return text, count


def validate_project_and_release_pack(project_id: str, release_pack_id: Optional[str]) -> Dict[str, Any]:
    if not project_id:
        raise ValueError("project_id is required")
    project = get_project(project_id)
    if not project:
        raise ValueError("Project not found")
    release_pack = (
        get_workspace_release_pack(release_pack_id)
        if release_pack_id
        else project.get("latest_workspace_release_pack") or latest_project_workspace_release_pack(project_id)
    )
    if not release_pack:
        raise ValueError("No workspace release pack exists for this project yet")
    if str(release_pack.get("project_id") or "") != project_id:
        raise ValueError("Workspace release pack does not belong to this project")
    return release_pack


