def write_default_workflows() -> None:
    ensure_dirs()
    for workflow_id, data in DEFAULT_WORKFLOWS.items():
        path = WORKFLOW_DIR / f"{workflow_id}.json"
        if not path.exists():
            write_json_file(path, data)


def load_workflows() -> Dict[str, Dict[str, Any]]:
    write_default_workflows()
    workflows: Dict[str, Dict[str, Any]] = {}
    for path in sorted(WORKFLOW_DIR.glob("*.json")):
        try:
            data = read_json_file(path, None)
            if not isinstance(data, dict):
                raise ValueError("workflow file is not a JSON object")
            workflows[data["id"]] = data
        except Exception as exc:
            print(f"Warning: could not load workflow {path.name}: {exc}")
    return workflows or DEFAULT_WORKFLOWS.copy()


