def current_ai_config() -> AIProviderConfig:
    return load_ai_provider_config()


def app_generation_budget_config(config: AIProviderConfig) -> AIProviderConfig:
    timeout = int(config.timeout_seconds or 0)
    max_output_tokens = int(config.max_output_tokens or 0)
    if not str(os.environ.get("SPRINTOS_AI_TIMEOUT_SECONDS", "")).strip():
        timeout = APP_GENERATION_MIN_TIMEOUT_SECONDS
    if not str(os.environ.get("SPRINTOS_AI_MAX_OUTPUT_TOKENS", "")).strip():
        max_output_tokens = APP_GENERATION_MIN_OUTPUT_TOKENS
    if timeout == config.timeout_seconds and max_output_tokens == config.max_output_tokens:
        return config
    return AIProviderConfig(
        provider=config.provider,
        enabled=config.enabled,
        model=config.model,
        base_url=config.base_url,
        timeout_seconds=timeout,
        max_output_tokens=max_output_tokens,
        api_key_present=config.api_key_present,
    )


