def prototype_index_html(ctx: Dict[str, Any]) -> str:
    shape = str(ctx.get("offline_template_shape") or "")
    if shape == "business_idea_scorer":
        return business_idea_scorer_html(ctx)
    if shape == "budget_calculator":
        return budget_calculator_html(ctx)
    if shape == "pricing_roi_calculator":
        return pricing_roi_calculator_html(ctx)
    if shape == "decision_matrix":
        return decision_matrix_html(ctx)
    if shape == "flashcard_helper":
        return flashcard_helper_html(ctx)
    if shape == "quiz_recommender":
        return quiz_recommender_html(ctx)
    if ctx["prototype_type"] == "landing_page":
        return landing_page_html(ctx)
    if ctx["prototype_type"] == "ai_text_tool":
        return ai_text_tool_html(ctx)
    if ctx["prototype_type"] == "calculator":
        return calculator_html(ctx)
    if ctx["prototype_type"] == "quiz_funnel":
        return quiz_funnel_html(ctx)
    return codex_app_brief_html(ctx)


def prototype_feedback_js(ctx: Dict[str, Any]) -> str:
    meta = {
        "prototype_id": str(ctx.get("prototype_id") or ""),
        "prototype_type": str(ctx.get("prototype_type") or ""),
        "project_title": str(ctx.get("title") or ""),
    }
    return textwrap.dedent(
        f"""\
        const prototypeFeedbackMeta = {json.dumps(meta, indent=2)};
        const feedbackStorageKey = 'sprintos-prototype-feedback::' + (
          prototypeFeedbackMeta.prototype_id ||
          prototypeFeedbackMeta.project_title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') ||
          'prototype'
        );
        const feedbackFieldMap = {{
          tester_label: 'feedback-tester-label',
          rating: 'feedback-rating',
          pain_level: 'feedback-pain-level',
          would_use: 'feedback-would-use',
          would_pay: 'feedback-would-pay',
          confusing_parts: 'feedback-confusing-parts',
          missing_features: 'feedback-missing-features',
          favorite_part: 'feedback-favorite-part',
          freeform_feedback: 'feedback-freeform'
        }};
        function feedbackNode(id) {{
          return document.getElementById(id);
        }}
        function feedbackValue(name) {{
          const node = feedbackNode(feedbackFieldMap[name]);
          return node ? node.value.trim() : '';
        }}
        function setFeedbackStatus(message, muted = false) {{
          const status = feedbackNode('feedback-local-status');
          if (!status) return;
          status.textContent = message;
          status.classList.toggle('muted', muted);
        }}
        function currentFeedbackPayload() {{
          const payload = {{
            prototype_id: prototypeFeedbackMeta.prototype_id || null,
            prototype_type: prototypeFeedbackMeta.prototype_type,
            project_title: prototypeFeedbackMeta.project_title,
            timestamp: new Date().toISOString(),
            tester_label: feedbackValue('tester_label'),
            source: 'local_preview',
            rating: feedbackValue('rating') ? Number(feedbackValue('rating')) : null,
            pain_level: feedbackValue('pain_level') ? Number(feedbackValue('pain_level')) : null,
            would_use: feedbackValue('would_use') || null,
            would_pay: feedbackValue('would_pay') || null,
            confusing_parts: feedbackValue('confusing_parts'),
            missing_features: feedbackValue('missing_features'),
            favorite_part: feedbackValue('favorite_part'),
            freeform_feedback: feedbackValue('freeform_feedback')
          }};
          return payload;
        }}
        function applyFeedbackPayload(payload) {{
          if (!payload || typeof payload !== 'object') return;
          Object.keys(feedbackFieldMap).forEach((field) => {{
            const node = feedbackNode(feedbackFieldMap[field]);
            if (!node) return;
            const value = payload[field];
            node.value = value == null ? '' : String(value);
          }});
        }}
        function clearFeedbackForm() {{
          applyFeedbackPayload({{}});
        }}
        function exportFeedbackJson() {{
          const payload = currentFeedbackPayload();
          const blob = new Blob([JSON.stringify(payload, null, 2)], {{ type: 'application/json' }});
          const slug = (prototypeFeedbackMeta.project_title || 'prototype')
            .toLowerCase()
            .replace(/[^a-z0-9]+/g, '-')
            .replace(/^-+|-+$/g, '') || 'prototype';
          const stamp = payload.timestamp.replace(/[:.]/g, '-');
          const link = document.createElement('a');
          link.href = URL.createObjectURL(blob);
          link.download = `feedback-${{slug}}-${{stamp}}.json`;
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
          URL.revokeObjectURL(link.href);
          setFeedbackStatus('Feedback exported as JSON. It is still only local unless you import it elsewhere.');
        }}
        document.getElementById('feedback-save').addEventListener('click', () => {{
          const payload = currentFeedbackPayload();
          localStorage.setItem(feedbackStorageKey, JSON.stringify(payload));
          setFeedbackStatus('Feedback saved locally in this browser. Export JSON if you want to import it into SprintOS.');
        }});
        document.getElementById('feedback-export').addEventListener('click', exportFeedbackJson);
        document.getElementById('feedback-clear').addEventListener('click', () => {{
          localStorage.removeItem(feedbackStorageKey);
          clearFeedbackForm();
          setFeedbackStatus('Local feedback cleared from this browser.', true);
        }});
        (() => {{
          const raw = localStorage.getItem(feedbackStorageKey);
          if (!raw) return;
          try {{
            const payload = JSON.parse(raw);
            applyFeedbackPayload(payload);
            setFeedbackStatus('Loaded saved local feedback from this browser.', true);
          }} catch (err) {{
            localStorage.removeItem(feedbackStorageKey);
          }}
        }})();
        """
    ).strip() + "\n"


def prototype_app_js(ctx: Dict[str, Any]) -> str:
    title_js = json.dumps(ctx["title"])
    next_action_js = json.dumps(ctx["next_tiny_action"])
    publish_action_js = json.dumps(ctx["publish_or_test_action"])
    feedback_js = prototype_feedback_js(ctx)
    shape = str(ctx.get("offline_template_shape") or "")
    if shape == "business_idea_scorer":
        base_js = textwrap.dedent(
            f"""\
            const ideaInput = document.getElementById('idea-input');
            const scoreNode = document.getElementById('idea-score');
            const bandNode = document.getElementById('idea-band');
            const clarityNode = document.getElementById('idea-clarity');
            const risksNode = document.getElementById('idea-risks');
            const smallestNode = document.getElementById('idea-smallest-test');
            const nextNode = document.getElementById('idea-next-action');
            const fallbackNextAction = {next_action_js};
            function countMatches(text, words) {{
              return words.reduce((count, word) => count + (text.includes(word) ? 1 : 0), 0);
            }}
            function scoreIdea() {{
              const text = ideaInput.value.trim().toLowerCase();
              const words = text.split(/\\s+/).filter(Boolean);
              const audience = countMatches(text, ['for ', 'people', 'teams', 'parents', 'students', 'freelancers', 'businesses']);
              const pain = countMatches(text, ['problem', 'pain', 'waste', 'save', 'stress', 'manual', 'expensive', 'slow']);
              const payment = countMatches(text, ['pay', 'price', 'subscription', 'budget', 'revenue', 'customers']);
              const clarity = Math.min(100, Math.round((Math.min(words.length, 80) / 80) * 50 + audience * 15 + pain * 10 + payment * 10));
              const score = Math.max(10, Math.min(100, clarity + (words.length > 12 ? 10 : 0)));
              const band = score >= 75 ? 'Strong' : score >= 50 ? 'Test' : 'Clarify';
              const risks = [];
              risks.push(audience ? 'Demand risk: medium. A target user is named, but willingness still needs proof.' : 'Demand risk: high. The target user is not specific yet.');
              risks.push(pain ? 'Problem risk: medium. The pain is visible, but frequency is not proven.' : 'Problem risk: high. The painful moment is not concrete yet.');
              risks.push(payment ? 'Business risk: medium. A money signal is mentioned, but pricing is untested.' : 'Business risk: high. No payment or budget signal is visible.');
              scoreNode.textContent = String(score);
              bandNode.textContent = band;
              clarityNode.textContent = String(clarity);
              risksNode.innerHTML = risks.map((risk) => '<li>' + risk + '</li>').join('');
              smallestNode.textContent = score >= 75
                ? 'Create a one-screen demo and ask three target users to react to the exact promise.'
                : 'Write a one-sentence offer for one target user and ask one person if this is painful enough to try.';
              nextNode.textContent = score >= 50 ? 'Book one short validation conversation this week.' : fallbackNextAction;
            }}
            document.getElementById('score-idea').addEventListener('click', scoreIdea);
            """
        ).strip() + "\n"
        return base_js + "\n" + feedback_js
    if shape == "budget_calculator":
        base_js = textwrap.dedent(
            """\
            function money(value) {
              return '$' + Math.round(value).toLocaleString();
            }
            function numberValue(id) {
              return Math.max(0, Number(document.getElementById(id).value || 0));
            }
            function calculateBudget() {
              const income = numberValue('budget-income');
              const housing = numberValue('budget-housing');
              const food = numberValue('budget-food');
              const transport = numberValue('budget-transport');
              const other = numberValue('budget-other');
              const totalExpenses = housing + food + transport + other;
              const savings = income - totalExpenses;
              const rate = income > 0 ? Math.round((savings / income) * 100) : 0;
              const status = savings < 0 ? 'Deficit' : rate >= 20 ? 'Strong' : rate >= 10 ? 'Stable' : 'Tight';
              document.getElementById('budget-savings').textContent = money(savings);
              document.getElementById('budget-rate').textContent = rate + '%';
              document.getElementById('budget-status').textContent = status;
              document.getElementById('budget-breakdown').textContent =
                'Income: ' + money(income) + '\\n' +
                'Housing: ' + money(housing) + '\\n' +
                'Food: ' + money(food) + '\\n' +
                'Transport: ' + money(transport) + '\\n' +
                'Other: ' + money(other) + '\\n' +
                'Total expenses: ' + money(totalExpenses);
              document.getElementById('budget-recommendation').textContent =
                savings < 0
                  ? 'Recommendation: cut or defer one non-essential expense before adding new commitments.'
                  : rate >= 20
                    ? 'Recommendation: keep the plan and assign the surplus to a named goal.'
                    : 'Recommendation: pick the largest flexible category and reduce it by 10% for one month.';
            }
            document.getElementById('budget-run').addEventListener('click', calculateBudget);
            calculateBudget();
            """
        ).strip() + "\n"
        return base_js + "\n" + feedback_js
    if shape == "pricing_roi_calculator":
        base_js = textwrap.dedent(
            """\
            function roiMoney(value) {
              return '$' + Math.round(value).toLocaleString();
            }
            function roiNumber(id, label, invalid) {
              const raw = document.getElementById(id).value;
              const value = Number(raw);
              if (raw.trim() === '') return 0;
              if (!Number.isFinite(value) || value < 0) {
                invalid.push(label);
                return 0;
              }
              return value;
            }
            function calculateRoi() {
              const invalid = [];
              const price = roiNumber('roi-price', 'price', invalid);
              const cost = roiNumber('roi-cost', 'cost', invalid);
              const customers = roiNumber('roi-customers', 'customers', invalid);
              const timeSaved = roiNumber('roi-time-saved', 'time saved', invalid);
              const investment = roiNumber('roi-investment', 'investment', invalid);
              const monthlyRevenue = price * customers;
              const totalCost = cost * customers;
              const grossProfit = monthlyRevenue - totalCost;
              const margin = monthlyRevenue > 0 ? Math.round((grossProfit / monthlyRevenue) * 100) : 0;
              const breakEvenUnits = price > cost ? Math.ceil(investment / (price - cost)) : 0;
              const paybackMonths = grossProfit > 0 && investment > 0 ? Math.ceil(investment / grossProfit) : 0;
              const simpleRoi = investment > 0 ? Math.round(((grossProfit * 12 - investment) / investment) * 100) : 0;
              document.getElementById('roi-summary').textContent = 'Monthly profit: ' + roiMoney(grossProfit);
              document.getElementById('roi-margin').textContent = margin + '%';
              document.getElementById('roi-payback').textContent = paybackMonths ? paybackMonths + ' mo' : 'n/a';
              document.getElementById('roi-breakdown').textContent =
                'Monthly revenue: ' + roiMoney(monthlyRevenue) + '\\n' +
                'Monthly cost: ' + roiMoney(totalCost) + '\\n' +
                'Gross profit: ' + roiMoney(grossProfit) + '\\n' +
                'Gross margin: ' + margin + '%\\n' +
                'Break-even units: ' + (breakEvenUnits || 'n/a') + '\\n' +
                'Simple annual ROI: ' + simpleRoi + '%\\n' +
                'Time saved estimate: ' + (timeSaved * customers).toLocaleString() + ' hour(s) per month' +
                (invalid.length ? '\\nValidation: invalid or negative values treated as 0: ' + invalid.join(', ') + '.' : '\\nValidation: inputs look usable; blanks count as 0.');
              document.getElementById('roi-recommendation').textContent =
                grossProfit <= 0
                  ? 'Recommendation: raise price, reduce unit cost, or narrow the offer before investing more.'
                  : margin < 35
                    ? 'Recommendation: margin is thin. Test a higher price or lower delivery cost before scaling.'
                    : paybackMonths && paybackMonths <= 3
                      ? 'Recommendation: payback looks fast enough for a small test. Validate with real customers next.'
                      : 'Recommendation: run a small pricing test and watch whether customer volume supports the payback period.';
            }
            function resetRoi() {
              ['roi-price','roi-cost','roi-customers','roi-time-saved','roi-investment'].forEach((id) => {
                document.getElementById(id).value = '';
              });
              calculateRoi();
              document.getElementById('roi-price').focus();
            }
            document.getElementById('roi-run').addEventListener('click', calculateRoi);
            document.getElementById('roi-reset').addEventListener('click', resetRoi);
            calculateRoi();
            """
        ).strip() + "\n"
        return base_js + "\n" + feedback_js
    if shape == "decision_matrix":
        base_js = textwrap.dedent(
            """\
            const decisionOptions = document.getElementById('decision-options');
            const decisionCriteria = document.getElementById('decision-criteria');
            const decisionRanking = document.getElementById('decision-ranking');
            const decisionRecommendation = document.getElementById('decision-recommendation');
            const decisionTradeoffs = document.getElementById('decision-tradeoffs');
            function lines(value) {
              return String(value || '').split(/\\n+/).map((item) => item.trim()).filter(Boolean);
            }
            function parseCriteria(value) {
              const parsed = lines(value).map((item) => {
                const parts = item.split(':');
                const label = parts[0].trim();
                const weight = Math.max(1, Math.min(5, Number(parts[1]) || 1));
                return { label, weight };
              }).filter((item) => item.label);
              return parsed.length ? parsed : [{ label: 'overall fit', weight: 1 }];
            }
            function scoreOption(option, criteria, index) {
              const normalized = option.toLowerCase();
              return criteria.reduce((total, criterion, criterionIndex) => {
                const words = criterion.label.toLowerCase().split(/\\s+/).filter(Boolean);
                const keywordHits = words.filter((word) => normalized.includes(word)).length;
                const lengthSignal = Math.min(3, Math.ceil(option.length / 18));
                const tieBreak = ((index + 1) * (criterionIndex + 2)) % 3;
                return total + criterion.weight * (keywordHits * 3 + lengthSignal + tieBreak);
              }, 0);
            }
            function compareDecisionOptions() {
              const options = lines(decisionOptions.value);
              const criteria = parseCriteria(decisionCriteria.value);
              if (options.length < 2 || !criteria.length) {
                decisionRanking.innerHTML = '<li>Empty state: enter at least two options and one criterion to compare.</li>';
                decisionRecommendation.textContent = 'Add options and criteria before choosing a recommendation.';
                decisionTradeoffs.textContent = 'Tradeoffs will appear after the comparison has enough input.';
                return;
              }
              const ranked = options.map((option, index) => ({
                option,
                score: scoreOption(option, criteria, index)
              })).sort((a, b) => b.score - a.score || a.option.localeCompare(b.option));
              const best = ranked[0];
              const second = ranked[1];
              decisionRanking.innerHTML = ranked.map((item, index) => '<li><strong>#' + (index + 1) + ' ' + item.option + '</strong> - local score ' + item.score + '</li>').join('');
              decisionRecommendation.textContent = 'Recommendation: choose ' + best.option + ' first. It scored highest against ' + criteria.map((item) => item.label).join(', ') + '.';
              decisionTradeoffs.textContent = second
                ? 'Tradeoff: ' + best.option + ' leads by ' + (best.score - second.score) + ' point(s) over ' + second.option + '. If that gap is small, run a quick real-world test before committing.'
                : 'Tradeoff: add another option to make the comparison meaningful.';
            }
            function clearDecision() {
              decisionOptions.value = '';
              decisionCriteria.value = '';
              decisionRanking.innerHTML = '<li>Ranking will appear here.</li>';
              decisionRecommendation.textContent = 'Add at least two options and one criterion, then compare.';
              decisionTradeoffs.textContent = 'Tradeoff notes will appear here.';
              decisionOptions.focus();
            }
            document.getElementById('compare-options').addEventListener('click', compareDecisionOptions);
            document.getElementById('clear-decision').addEventListener('click', clearDecision);
            """
        ).strip() + "\n"
        return base_js + "\n" + feedback_js
    if shape == "flashcard_helper":
        base_js = textwrap.dedent(
            """\
            const notesInput = document.getElementById('notes-input');
            const cardOutput = document.getElementById('card-output');
            function escapeHtml(value) {
              return String(value).replace(/[&<>"']/g, (char) => ({
                '&': '&amp;',
                '<': '&lt;',
                '>': '&gt;',
                '"': '&quot;',
                "'": '&#39;'
              }[char]));
            }
            function sentenceCards(text) {
              const sentences = text
                .split(/[.!?\\n]+/)
                .map((item) => item.trim())
                .filter((item) => item.length > 8)
                .slice(0, 6);
              if (!sentences.length) {
                return [{ question: 'What should you paste first?', answer: 'Paste short study notes, then build flashcards.' }];
              }
              return sentences.map((sentence, index) => {
                const words = sentence.split(/\\s+/).filter(Boolean);
                const key = words.slice(0, Math.min(6, words.length)).join(' ');
                return {
                  question: 'Card ' + (index + 1) + ': What is the key point about "' + key + '"?',
                  answer: sentence
                };
              });
            }
            function buildCards() {
              const cards = sentenceCards(notesInput.value);
              cardOutput.innerHTML = cards.map((card) => (
                '<div class="result flashcard-card" data-template-marker="qa-card"><strong>' + escapeHtml(card.question) + '</strong><p>' + escapeHtml(card.answer) + '</p></div>'
              )).join('');
            }
            document.getElementById('build-cards').addEventListener('click', buildCards);
            """
        ).strip() + "\n"
        return base_js + "\n" + feedback_js
    if shape == "quiz_recommender":
        base_js = textwrap.dedent(
            f"""\
            const nextAction = {next_action_js};
            const publishAction = {publish_action_js};
            function showRecommendation() {{
              const priority = document.getElementById('quiz-priority').value;
              const confidence = document.getElementById('quiz-confidence').value;
              const effort = document.getElementById('quiz-effort').value;
              let score = 0;
              score += priority === 'speed' ? 1 : priority === 'quality' ? 2 : 0;
              score += confidence === 'high' ? 3 : confidence === 'medium' ? 2 : 1;
              score += effort === 'large' ? 2 : effort === 'medium' ? 1 : 0;
              const recommendation = score >= 5
                ? 'Recommendation: run a focused build sprint. ' + publishAction
                : score >= 3
                  ? 'Recommendation: test the smallest version first. ' + nextAction
                  : 'Recommendation: use a low-effort validation page before building more.';
              document.getElementById('quiz-recommendation').textContent =
                recommendation + ' Local score: ' + score + '/7. Inputs: ' + priority + ', ' + confidence + ', ' + effort + '.';
            }}
            document.getElementById('quiz-run').addEventListener('click', showRecommendation);
            """
        ).strip() + "\n"
        return base_js + "\n" + feedback_js
    if ctx["prototype_type"] == "landing_page":
        base_js = textwrap.dedent(
            """\
            const formResult = document.getElementById('waitlist-result');
            document.getElementById('waitlist-submit').addEventListener('click', () => {
              const name = document.getElementById('waitlist-name').value.trim() || 'Tester';
              const email = document.getElementById('waitlist-email').value.trim() || 'no email given';
              const note = document.getElementById('waitlist-note').value.trim() || 'No extra note.';
              formResult.textContent = `Thanks, ${name}. This prototype stays local-only. Mock signup captured for ${email}. Useful note: ${note}`;
              formResult.classList.remove('muted');
            });
            """
        ).strip() + "\n"
        return base_js + "\n" + feedback_js
    if ctx["prototype_type"] == "ai_text_tool":
        base_js = textwrap.dedent(
            f"""\
            const input = document.getElementById('tool-input');
            const output = document.getElementById('tool-output');
            const projectTitle = {title_js};
            const nextAction = {next_action_js};
            function mockedResponse(value) {{
              const text = value.trim() || 'No input provided.';
              const words = text.split(/\\s+/).filter(Boolean);
              const snippet = words.slice(0, 10).join(' ');
              const checksum = words.reduce((sum, word) => sum + word.length, 0);
              return [
                'Simulated result for ' + projectTitle,
                '',
                'Input summary: ' + snippet,
                'Likely user intent: turn the messy input into one useful next step.',
                'Deterministic angle score: ' + ((checksum % 7) + 3) + '/9',
                'Suggested next step: ' + nextAction,
              ].join('\\n');
            }}
            document.getElementById('generate-output').addEventListener('click', () => {{
              output.textContent = mockedResponse(input.value);
            }});
            """
        ).strip() + "\n"
        return base_js + "\n" + feedback_js
    if ctx["prototype_type"] == "calculator":
        base_js = textwrap.dedent(
            f"""\
            const projectTitle = {title_js};
            const publishAction = {publish_action_js};
            const nextAction = {next_action_js};
            function calculate() {{
              const frequency = Number(document.getElementById('calc-frequency').value || 0);
              const hours = Number(document.getElementById('calc-hours').value || 0);
              const confidence = Number(document.getElementById('calc-confidence').value || 0);
              const score = Math.max(0, Math.round((frequency * hours * confidence) / 2));
              let band = 'Low';
              let next = 'Wait';
              if (score >= 40) {{
                band = 'High';
                next = 'Build';
              }} else if (score >= 20) {{
                band = 'Medium';
                next = 'Test';
              }}
              document.getElementById('calc-score').textContent = String(score);
              document.getElementById('calc-band').textContent = band;
              document.getElementById('calc-next').textContent = next;
              document.getElementById('calc-explanation').textContent =
                'This score combines pain frequency, potential time saved, and confidence. ' +
                'For ' + projectTitle + ', a ' + band.toLowerCase() + ' score means the next move is: ' +
                (band === 'High' ? publishAction : nextAction);
            }}
            document.getElementById('calc-run').addEventListener('click', calculate);
            calculate();
            """
        ).strip() + "\n"
        return base_js + "\n" + feedback_js
    if ctx["prototype_type"] == "quiz_funnel":
        base_js = textwrap.dedent(
            f"""\
            const questions = {json.dumps(ctx["quiz_questions"], indent=2)};
            const publishAction = {publish_action_js};
            const nextAction = {next_action_js};
            const stage = document.getElementById('quiz-stage');
            const result = document.getElementById('quiz-result');
            let index = 0;
            let score = 0;
            function renderQuestion() {{
              const current = questions[index];
              if (!current) {{
                const band = score >= 10 ? 'High intent' : score >= 7 ? 'Medium intent' : 'Early interest';
                const nextStep = score >= 10 ? publishAction : nextAction;
                stage.innerHTML = '<strong>Quiz complete.</strong><p>Use the result panel to review the recommendation.</p>';
                result.textContent = band + ': suggested next step -> ' + nextStep;
                return;
              }}
              stage.innerHTML = '';
              const title = document.createElement('h3');
              title.textContent = current.question;
              stage.appendChild(title);
              const options = document.createElement('div');
              options.className = 'options';
              current.options.forEach((option) => {{
                const button = document.createElement('button');
                button.type = 'button';
                button.textContent = option.label;
                button.addEventListener('click', () => {{
                  score += Number(option.score || 0);
                  index += 1;
                  renderQuestion();
                }});
                options.appendChild(button);
              }});
              stage.appendChild(options);
            }}
            renderQuestion();
            """
        ).strip() + "\n"
        return base_js + "\n" + feedback_js
    base_js = textwrap.dedent(
        f"""\
        const notice = document.createElement('p');
        notice.className = 'footer';
        notice.textContent = 'Open codex-build-prompt.md next. This package is a build brief, not a full app.';
        document.querySelector('.shell').appendChild(notice);
        """
    ).strip() + "\n"
    return base_js + "\n" + feedback_js


def prototype_readme(ctx: Dict[str, Any]) -> str:
    app_title = prototype_app_title(ctx)
    manual_steps = {
        "landing_page": "Open the page, read the message, fill the mock CTA, and sanity-check whether the promise is clear.",
        "ai_text_tool": "Paste rough input, click generate, inspect the mocked output, and judge whether the simulated result feels directionally useful.",
        "calculator": "Change the input values, click calculate, and verify the result/explanation respond deterministically.",
        "quiz_funnel": "Answer each question, verify the result screen appears, and judge whether the recommendation feels believable.",
        "codex_app_brief": "Open the overview page, then read codex-build-prompt.md and confirm the build brief is specific enough to hand to Codex.",
    }
    shape_manual_steps = {
        "business_idea_scorer": "Paste a business idea, click Score Idea, and confirm the score, risks, smallest testable version, and next action update.",
        "budget_calculator": "Enter income and expense numbers, click Calculate Budget, and confirm savings, breakdown, and recommendation update.",
        "decision_matrix": "Enter options and criteria, click Compare Options, and confirm the ranking, recommendation, and tradeoff notes update.",
        "flashcard_helper": "Paste study notes, click Build Flashcards, and confirm question/answer cards are created from the notes.",
        "pricing_roi_calculator": "Enter price, cost, customers, and investment assumptions, click Calculate ROI, and confirm summary, breakdown, payback, and recommendation update.",
        "quiz_recommender": "Answer the quiz, click Show Recommendation, and confirm the recommendation changes from local inputs.",
        "waitlist_page": "Open the page, read the message, fill the mock CTA, and sanity-check whether the promise is clear.",
    }
    shape = str(ctx.get("offline_template_shape") or "")
    manual_step = shape_manual_steps.get(shape, manual_steps[ctx["prototype_type"]])
    local_logic_notes = {
        "business_idea_scorer": "The score is deterministic. It checks for target-user clarity, pain language, and money/budget signals.",
        "budget_calculator": "Budget output is deterministic arithmetic over the income and expense fields.",
        "decision_matrix": "This prototype ranks options locally using simple deterministic rules. It does not call live AI or external services inside the browser.",
        "flashcard_helper": "This prototype builds study cards locally from your notes. It does not call live AI or external services inside the browser.",
        "pricing_roi_calculator": "This prototype estimates pricing and ROI locally using simple deterministic calculations. It does not call live AI or external services inside the browser.",
        "quiz_recommender": "The recommendation is a small deterministic score from the selected quiz answers.",
        "waitlist_page": "The waitlist confirmation is a mock local state change. It does not submit data.",
    }
    what_it_does = {
        "business_idea_scorer": "Idea Scorecard scores a rough business idea, shows the main risks, suggests the smallest testable version, and gives one next action.",
        "budget_calculator": "Budget Snapshot calculates monthly savings from income and expense inputs, shows a spending breakdown, and gives a practical recommendation.",
        "decision_matrix": "Decision Matrix compares options against criteria, ranks them locally, and explains the recommendation and tradeoffs.",
        "flashcard_helper": "Study Card Builder turns pasted study notes into local question/answer cards for quick review.",
        "pricing_roi_calculator": "Pricing ROI Calculator estimates revenue, costs, margin, break-even, payback, and a practical recommendation from local assumptions.",
        "quiz_recommender": "Quiz Recommender turns a few local answers into a deterministic recommendation.",
        "waitlist_page": "Waitlist Launch Page tests a simple signup promise with a local-only mock confirmation.",
    }
    local_logic_note = local_logic_notes.get(shape, "The prototype uses deterministic local browser logic.")
    return textwrap.dedent(
        f"""\
        # {app_title}

        This is a small local prototype generated by SprintOS for this idea:

        > {ctx["raw_idea"]}

        ## What this app does
        {what_it_does.get(shape, "This app gives the main idea one browser-openable local workflow.")}

        ## What this prototype is
        - A static, browser-openable package for quick validation.
        - A deliberately small test artifact, not a production app.
        - A way to get feedback before heavier build work.

        ## Run locally
        ```bash
        python3 -m http.server 8080
        ```

        Then open `http://127.0.0.1:8080/index.html`.

        ## Local logic
        {local_logic_note}

        ## Deterministic / local / mocked
        - The app runs entirely from local static files.
        - Browser logic is deterministic and inspectable in `app.js`.
        - No OpenAI, DeepSeek, or other provider is called from the browser.
        - No data is sent to a backend or external service.

        ## Manual testing
        - {manual_step}
        - Fill in the Tester Feedback section, save it locally, and export JSON.
        - Check the feedback CTA section and confirm it does not require a backend.
        - Verify the page still works offline after the files are generated.

        ## Intentionally fake / simulated
        - No backend.
        - No auth.
        - No real data storage.
        - No external API calls.
        - Any output or signup behavior is mocked on purpose.
        """
    ).strip() + "\n"


def prototype_feedback_markdown(ctx: Dict[str, Any]) -> str:
    lines = [f"# Feedback Questions — {ctx['title']}", ""]
    for idx, question in enumerate(ctx["feedback_questions"], start=1):
        lines.append(f"{idx}. {question}")
    return "\n".join(lines).strip() + "\n"


def prototype_test_plan(ctx: Dict[str, Any]) -> str:
    app_title = prototype_app_title(ctx)
    extra_step = {
        "landing_page": "Enter a fake name/email/note and confirm the page shows a local-only confirmation message.",
        "ai_text_tool": "Paste text, click generate, and confirm the output is deterministic for the same input.",
        "calculator": "Change the numeric inputs and confirm the score, band, and explanation update with no network access.",
        "quiz_funnel": "Answer every question and confirm the result screen appears with a suggested next step.",
        "codex_app_brief": "Open codex-build-prompt.md and confirm the brief can be copied directly into Codex.",
    }
    shape_extra_step = {
        "business_idea_scorer": "In Idea Scorecard, paste a business idea and confirm the output includes a score, risks, smallest testable version, and next action.",
        "budget_calculator": "In Budget Snapshot, enter income and expenses and confirm monthly savings, spending breakdown, and recommendation update.",
        "decision_matrix": "In Decision Matrix, enter at least two options and one criterion, then confirm the ranked list, recommendation, and tradeoff notes update.",
        "flashcard_helper": "In Study Card Builder, paste study notes and confirm question/answer cards appear with the visible note: This prototype builds study cards locally from your notes. It does not call live AI or external services inside the browser.",
        "pricing_roi_calculator": "In Pricing ROI Calculator, enter price, cost, customers, and investment assumptions, then confirm revenue, cost, margin, payback, breakdown, and recommendation update.",
        "quiz_recommender": "Change quiz answers and confirm the recommendation text changes deterministically.",
        "waitlist_page": "Enter a fake name/email/note and confirm the page shows a local-only confirmation message.",
    }
    shape = str(ctx.get("offline_template_shape") or "")
    return textwrap.dedent(
        f"""\
        # Test Plan — {app_title}

        - [ ] Open `index.html` in a browser.
        - [ ] Or serve locally with `python3 -m http.server 8080` and open the preview URL.
        - [ ] Click through the main flow.
        - [ ] {shape_extra_step.get(shape, extra_step[ctx["prototype_type"]])}
        - [ ] Save tester feedback locally and export a JSON file.
        - [ ] Open `feedback-import-instructions.md` and confirm the import steps match SprintOS.
        - [ ] Verify no external calls are required.
        - [ ] Verify the prototype label is visible.
        - [ ] Verify the feedback CTA is visible.
        - [ ] Verify the package still works with JavaScript enabled and no backend.
        """
    ).strip() + "\n"


def prototype_codex_prompt(ctx: Dict[str, Any]) -> str:
    app_title = prototype_app_title(ctx)
    shape = str(ctx.get("offline_template_shape") or "")
    effective_key = shape if shape in {"business_idea_scorer", "budget_calculator", "decision_matrix", "flashcard_helper", "pricing_roi_calculator"} else str(ctx["prototype_type"])
    files = "\n".join(f"- `{name}`" for name in PROTOTYPE_FILES)
    feature_lines = "\n".join(f"- {item}" for item in ctx["feature_bullets"])
    screen_lines = "\n".join(f"- {item}" for item in ctx["screens"])
    data_model_lines = {
        "business_idea_scorer": "- `idea_runs`: idea text, score, risk breakdown, smallest testable version, next action, created_at if local history is later added.",
        "budget_calculator": "- `budget_snapshots`: income, expenses, monthly savings, spending breakdown, recommendation, created_at if local history is later added.",
        "decision_matrix": "- `decision_runs`: options, criteria, ranked results, recommendation, tradeoff notes, created_at if local browser or file persistence is later added.",
        "flashcard_helper": "- `flashcard_sets`: source notes, generated question/answer cards, created_at if local browser or file persistence is later added.",
        "pricing_roi_calculator": "- `pricing_roi_runs`: price, cost, customers, investment, revenue, margin, payback, recommendation, created_at if local browser or file persistence is later added.",
        "landing_page": "- `interest_signals`: optional local capture shape with `name`, `email`, `note`, `created_at` if persistence is later added.",
        "ai_text_tool": "- `runs`: input text, deterministic output, created_at if the real app later saves runs locally.",
        "calculator": "- `scenarios`: input values, score, explanation, created_at if saved comparisons become necessary.",
        "quiz_funnel": "- `responses`: question answers, final segment, created_at if local session history is added.",
        "codex_app_brief": "- Define only the minimum entities needed for the main workflow. Avoid speculative tables.",
    }
    api_route_lines = {
        "business_idea_scorer": "- No API route is required for v1; keep scoring in `app.js` unless a later local save endpoint is added.",
        "budget_calculator": "- No API route is required for v1; keep budget math in `app.js` unless snapshots need local persistence.",
        "decision_matrix": "- No API route is required for v1; keep option ranking in `app.js` unless a later local save endpoint is added.",
        "flashcard_helper": "- No API route is required for v1; keep card building in `app.js` unless a later local import/export endpoint is added.",
        "pricing_roi_calculator": "- No API route is required for v1; keep pricing and ROI math in `app.js` unless local scenario persistence is later added.",
        "landing_page": "- Avoid API routes unless you later add a real local save endpoint for feedback.",
        "ai_text_tool": "- One local generation route only if the real build moves mocked logic to a backend process.",
        "calculator": "- No API route is required unless calculations need persisted scenarios.",
        "quiz_funnel": "- No API route is required for v1 unless you decide to save quiz results locally.",
        "codex_app_brief": "- Add only the smallest route set needed for the core path. Skip admin and analytics routes.",
    }
    test_lines = {
        "business_idea_scorer": "- Test `index.html` + `app.js`: paste an idea, click Score Idea, and assert score, risks, smallest testable version, and next action update.",
        "budget_calculator": "- Test `index.html` + `app.js`: change income/expenses, click Calculate Budget, and assert monthly savings, spending breakdown, and recommendation update.",
        "decision_matrix": "- Test `index.html` + `app.js`: enter options and criteria, click Compare Options, and assert ranking, recommendation, and tradeoff notes update from local input.",
        "flashcard_helper": "- Test `index.html` + `app.js`: paste notes, click Build Flashcards, and assert visible question/answer cards appear while this note remains visible: \"This prototype builds study cards locally from your notes. It does not call live AI or external services inside the browser.\"",
        "pricing_roi_calculator": "- Test `index.html` + `app.js`: change price, cost, customers, and investment, click Calculate ROI, and assert summary, breakdown, payback, and recommendation update from local input.",
        "landing_page": "- Test the main CTA state change and confirm no network is required.",
        "ai_text_tool": "- Test deterministic output for the same input and an empty-input fallback.",
        "calculator": "- Test score calculation, band thresholds, and explanation text.",
        "quiz_funnel": "- Test question progression, final result calculation, and reset/replay if added.",
        "codex_app_brief": "- Add the smallest tests that prove the core path and reject scope creep.",
    }
    next_improvement_lines = {
        "business_idea_scorer": "Improve Idea Scorecard by making the risk breakdown more specific while preserving the existing `idea-input`, `score-idea`, `idea-score`, `idea-risks`, `idea-smallest-test`, and `idea-next-action` surfaces.",
        "budget_calculator": "Improve Budget Snapshot by adding one clearer budget category insight while preserving the existing `budget-income`, expense inputs, `budget-savings`, `budget-breakdown`, and `budget-recommendation` surfaces.",
        "decision_matrix": "Improve Decision Matrix by making the tradeoff explanation more useful while preserving `decision-options`, `decision-criteria`, `compare-options`, `decision-ranking`, `decision-recommendation`, and `decision-tradeoffs`.",
        "flashcard_helper": "Improve Study Card Builder by making generated cards easier to review while preserving `notes-input`, `build-cards`, `card-output`, and the visible limitation note: \"This prototype builds study cards locally from your notes. It does not call live AI or external services inside the browser.\"",
        "pricing_roi_calculator": "Improve Pricing ROI Calculator by making one assumption or recommendation clearer while preserving `roi-price`, `roi-cost`, `roi-customers`, `roi-run`, `roi-summary`, `roi-breakdown`, and `roi-recommendation`.",
        "landing_page": "Improve the local CTA confirmation copy without adding backend submission.",
        "ai_text_tool": "Improve the deterministic output formatting without adding provider calls.",
        "calculator": "Improve the explanation text for one score band without changing the local calculation contract.",
        "quiz_funnel": "Improve the recommendation clarity for one quiz outcome without adding new questions.",
        "codex_app_brief": "Turn one part of the brief into the smallest working local screen.",
    }
    return textwrap.dedent(
        f"""\
        # Codex Build Prompt — {app_title}

        Read AGENTS.md first if present before editing.

        ## Objective
        Turn {app_title} into the smallest serious app that proves: {ctx["objective"]}.

        ## Context
        - App name: {app_title}
        - Project title: {ctx["title"]}
        - Raw idea: {ctx["raw_idea"]}
        - Prototype type: {ctx["prototype_label"]}
        - App shape: {shape or ctx["prototype_type"]}
        - Project status: {ctx["status"]}
        - Workflow: {ctx["workflow_id"]}
        - Current blocker: {ctx["current_blocker"]}
        - Next tiny action: {ctx["next_tiny_action"]}
        - Target user: {ctx["target_user"]}
        - Current sprint summary: {ctx["one_sentence"]}
        - Existing Codex handoff summary: {ctx["codex_handoff_summary"] or 'See the SprintOS project for the full handoff.'}

        ## Current Prototype Files
        {files}

        ## Small Next Improvement
        {next_improvement_lines.get(effective_key, "Improve one small part of the main local workflow without adding dependencies.")}

        ## Data Model If Needed
        {data_model_lines.get(effective_key, data_model_lines[ctx["prototype_type"]])}

        ## API Routes If Needed
        {api_route_lines.get(effective_key, api_route_lines[ctx["prototype_type"]])}

        ## Implementation Constraints
        - Keep it local-first where possible.
        - Do not overbuild.
        - Do not add auth unless the repo already requires it.
        - Do not add cloud sync.
        - Do not wire real deployment yet.
        - Keep one obvious core path working before secondary features.
        - Preserve the useful message and feedback loop already present in the prototype.

        ## Acceptance Criteria
        - The app has one working core flow tied to this prototype.
        - The implementation stays small enough for one PR and one verification pass.
        - The user can test the main path without reading internal notes.
        - The following scope remains visible in the implementation:
        {feature_lines}
        - The app includes or clearly maps to these screens:
        {screen_lines}
        - The build includes a way to capture feedback or next-step signal.

        ## Tests
        {test_lines.get(effective_key, test_lines[ctx["prototype_type"]])}
        - Keep tests focused on the changed path.

        ## Verification Commands
        ```bash
        python3 -m http.server 8080
        ```

        ## Non-Goals
        - Full platform rewrite.
        - Premature integrations.
        - Real billing, deployment, or growth tooling.
        - Building more than the main path required to test the idea.
        """
    ).strip() + "\n"


def prototype_metadata(
    project: Dict[str, Any],
    prototype_id: str,
    prototype_type: str,
    created_at: str,
    files_generated: List[str],
    ai_source: Optional[Dict[str, Any]] = None,
    app_payload: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    metadata = {
        "prototype_id": prototype_id,
        "project_id": project["id"],
        "project_title": project.get("title") or project.get("sprint", {}).get("title") or "Prototype",
        "prototype_type": prototype_type,
        "created_at": created_at,
        "source_status": project.get("status") or DEFAULT_PROJECT_STATUS,
        "next_tiny_action": project.get("next_tiny_action") or "",
        "current_blocker": project.get("current_blocker") or "",
        "files_generated": files_generated,
    }
    if app_payload:
        metadata.update(
            {
                "app_name": str(app_payload.get("app_name") or project.get("title") or "Prototype"),
                "app_type": str(app_payload.get("app_type") or prototype_type),
                "short_description": str(app_payload.get("short_description") or ""),
                "user_flow": list(app_payload.get("user_flow") or []),
                "run_instructions": str(app_payload.get("run_instructions") or ""),
                "test_instructions": str(app_payload.get("test_instructions") or ""),
                "codex_next_prompt": str(app_payload.get("codex_next_prompt") or ""),
                "limitations": list(app_payload.get("limitations") or []),
                "mocked_parts": list(app_payload.get("mocked_parts") or []),
                "generated_files": [
                    str(item.get("filename") or "")
                    for item in (app_payload.get("files") or [])
                    if isinstance(item, dict) and str(item.get("filename") or "").strip()
                ],
            }
        )
    if ai_source:
        for key in (
            "used_ai",
            "ai_provider",
            "ai_model",
            "ai_task_name",
            "generation_mode_requested",
            "route_used",
            "route_id",
            "resolved_provider",
            "resolved_model",
            "ai_fallback_reason",
            "ai_error_summary",
            "ai_validation_warnings",
            "app_generation_fallback_mode",
            "app_generation_fallback_used",
            "_mode",
            "_note",
            "offline_template_shape",
        ):
            if key in ai_source and ai_source.get(key) not in (None, ""):
                metadata[key] = ai_source.get(key)
        metadata["provider"] = str(ai_source.get("ai_provider") or "offline")
        metadata["model"] = str(ai_source.get("ai_model") or "")
        metadata["fallback_reason"] = str(ai_source.get("ai_fallback_reason") or "")
    return metadata


def write_prototype_package(
    project: Dict[str, Any],
    prototype_type: str,
    generation_mode: str = "auto",
    fallback_mode: str = "",
) -> Dict[str, Any]:
    prototype_type = normalize_prototype_type(prototype_type)
    created_at = now_iso()
    prototype_id = str(uuid.uuid4())
    package_slug = slugify(str(project.get("title") or project.get("sprint", {}).get("title") or "prototype"), "prototype")
    base_name = f"{package_slug}-{prototype_folder_timestamp(created_at)}"
    if prototype_type == "codex_app_brief":
        ctx = prototype_context(project, prototype_type, prototype_id=prototype_id, generation_mode=generation_mode)
        app_payload = prototype_offline_app_file_generation_payload(project, prototype_type, prototype_id, ctx=ctx)
        primary_files = prototype_files_from_app_payload(app_payload)
    else:
        ctx, app_payload, app_provider_result = generate_prototype_app_files(
            project,
            prototype_type,
            prototype_id,
            generation_mode=generation_mode,
            fallback_mode=fallback_mode,
        )
        ctx = apply_ai_metadata(ctx, "app_file_generation", app_provider_result)
        ctx["app_generation_fallback_mode"] = normalize_app_generation_fallback_mode(fallback_mode)
        ctx["app_generation_fallback_used"] = not bool(app_provider_result.used_ai)
        primary_files = prototype_files_from_app_payload(app_payload)
    package_dir = prototype_export_dir() / base_name
    counter = 2
    while package_dir.exists():
        package_dir = prototype_export_dir() / f"{base_name}-{counter}"
        counter += 1
    package_dir.mkdir(parents=True, exist_ok=True)
    primary_files = ensure_prototype_feedback_capture(ctx, primary_files)
    files = {
        "index.html": primary_files["index.html"],
        "style.css": primary_files["style.css"],
        "app.js": primary_files["app.js"],
        "README.md": primary_files["README.md"],
        "feedback-questions.md": prototype_feedback_markdown(ctx),
        "feedback-import-instructions.md": prototype_feedback_import_instructions(ctx),
        "TEST_PLAN.md": primary_files["TEST_PLAN.md"],
        "test-plan.md": primary_files["test-plan.md"],
        "codex-build-prompt.md": prototype_codex_prompt(ctx),
    }
    metadata = prototype_metadata(project, prototype_id, prototype_type, created_at, list(PROTOTYPE_FILES), ai_source=ctx, app_payload=app_payload)
    files["prototype.json"] = json.dumps(metadata, indent=2)
    for name, content in files.items():
        (package_dir / name).write_text(content, encoding="utf-8")
    title = f"{str(app_payload.get('app_name') or ctx['title'])} — {ctx['prototype_label']}"
    with db() as conn:
        conn.execute(
            """
            INSERT INTO prototypes (id, project_id, prototype_type, title, path, created_at, metadata_json)
            VALUES (?, ?, ?, ?, ?, ?, ?)
            """,
            (
                prototype_id,
                project["id"],
                prototype_type,
                title,
                str(package_dir),
                created_at,
                json.dumps(metadata),
            ),
        )
        conn.execute("UPDATE projects SET updated_at = ? WHERE id = ?", (created_at, project["id"]))
        conn.commit()
    prototype = get_prototype(prototype_id, include_prompt=True)
    if prototype is None:
        raise ValueError("Prototype was not saved correctly")
    record_activity_event(
        project["id"],
        "prototype_generated",
        "Prototype generated",
        f"Generated a {prototype_type.replace('_', ' ')} prototype package.",
        event_status="success",
        actor="sprintos",
        related_type="prototype",
        related_id=prototype_id,
        next_tiny_action="Review the prototype and collect one round of feedback.",
        report_path=str(package_dir),
        metadata={"prototype_type": prototype_type, "path": str(package_dir)},
    )
    return prototype


def prototype_response(row: sqlite3.Row | Dict[str, Any], include_prompt: bool = False) -> Dict[str, Any]:
    data = dict(row)
    metadata = safe_json_loads(str(data.get("metadata_json") or "{}"), {}) or {}
    path = Path(str(data.get("path") or ""))
    result = {
        "id": str(data.get("id") or ""),
        "project_id": str(data.get("project_id") or metadata.get("project_id") or ""),
        "prototype_type": str(data.get("prototype_type") or metadata.get("prototype_type") or ""),
        "prototype_label": PROTOTYPE_TYPES.get(str(data.get("prototype_type") or metadata.get("prototype_type") or ""), "Prototype"),
        "title": str(data.get("title") or metadata.get("project_title") or "Prototype"),
        "app_name": str(metadata.get("app_name") or metadata.get("project_title") or data.get("title") or "Prototype"),
        "app_type": str(metadata.get("app_type") or metadata.get("prototype_type") or ""),
        "path": str(path),
        "created_at": str(data.get("created_at") or metadata.get("created_at") or ""),
        "metadata": metadata,
        "files_generated": metadata.get("files_generated") or list(PROTOTYPE_FILES),
        "preview_url": f"/prototype/{data.get('id')}/index.html",
        "zip_url": f"/api/prototype_zip?id={urllib.parse.quote(str(data.get('id') or ''))}",
        "prompt_url": f"/api/prototype_file?id={urllib.parse.quote(str(data.get('id') or ''))}&file=codex-build-prompt.md",
        "feedback_count": feedback_count(str(data.get("project_id") or metadata.get("project_id") or ""), str(data.get("id") or "")),
        "latest_iteration": latest_iteration(str(data.get("project_id") or metadata.get("project_id") or ""), str(data.get("id") or "")),
    }
    if include_prompt:
        prompt_path = path / "codex-build-prompt.md"
        result["codex_prompt"] = prompt_path.read_text(encoding="utf-8") if prompt_path.exists() else ""
    return result


def get_prototype(prototype_id: str, include_prompt: bool = False) -> Optional[Dict[str, Any]]:
    with db() as conn:
        row = conn.execute("SELECT * FROM prototypes WHERE id = ?", (prototype_id,)).fetchone()
    if not row:
        return None
    return prototype_response(row, include_prompt=include_prompt)


def latest_project_prototype(project_id: str, include_prompt: bool = False) -> Optional[Dict[str, Any]]:
    with db() as conn:
        row = conn.execute(
            "SELECT * FROM prototypes WHERE project_id = ? ORDER BY created_at DESC, rowid DESC LIMIT 1",
            (project_id,),
        ).fetchone()
    if not row:
        return None
    return prototype_response(row, include_prompt=include_prompt)


def list_project_prototypes(project_id: str) -> List[Dict[str, Any]]:
    with db() as conn:
        rows = conn.execute(
            "SELECT * FROM prototypes WHERE project_id = ? ORDER BY created_at DESC, rowid DESC",
            (project_id,),
        ).fetchall()
    return [prototype_response(row, include_prompt=False) for row in rows]


def prototype_file_path(prototype: Dict[str, Any], filename: str) -> Path:
    return safe_flat_file_path(
        Path(str(prototype.get("path") or "")),
        filename,
        PROTOTYPE_FILES,
        "Invalid prototype file",
    )


def build_prototype_zip(prototype: Dict[str, Any]) -> Tuple[str, bytes]:
    filename = prototype_zip_name(prototype)
    payload = build_zip_from_reader(
        PROTOTYPE_FILES,
        lambda name: prototype_file_path(prototype, name).read_text(encoding="utf-8"),
    )
    return filename, payload


def deploy_pack_zip_name(deploy_pack: Dict[str, Any]) -> str:
    base = slugify(str(deploy_pack.get("title") or "deploy-pack"), "deploy-pack")
    stamp = prototype_folder_timestamp(str(deploy_pack.get("created_at") or now_iso()))
    return sanitize_filename(f"{base}-{stamp}.zip", default_stem="deploy-pack", default_suffix=".zip")


def metadata_has_unsafe_path(value: Any) -> bool:
    return helper_metadata_has_unsafe_path(value)


def prototype_has_feedback_or_cta(index_html: str) -> bool:
    lowered = index_html.lower()
    markers = (
        "feedback",
        "join waitlist",
        "share feedback",
        "request access",
        "get started",
        "start now",
        "book a demo",
        "sign up",
    )
    return any(marker in lowered for marker in markers)


def prototype_has_input_and_result(index_html: str) -> bool:
    lowered = index_html.lower()
    has_input = any(marker in lowered for marker in ("<input", "<textarea", "<select", "<form"))
    has_action = "<button" in lowered or 'type="submit"' in lowered or "type='submit'" in lowered
    has_result = any(
        marker in lowered
        for marker in (
            'id="result"',
            "id='result'",
            'id="output"',
            "id='output'",
            'class="result"',
            "class='result'",
            "score",
            "quiz-result",
            "tool-output",
            "waitlist-result",
            "card-output",
            "budget-savings",
            "budget-breakdown",
            "decision-ranking",
            "decision-recommendation",
            "decision-tradeoffs",
            "roi-summary",
            "roi-breakdown",
        )
    ) or bool(
        re.search(
            r"\b(?:id|class)\s*=\s*['\"][^'\"]*(?:result|output|summary|progress|message|list|status|preview|report|recommendation|breakdown|ranking|cards|timeline|empty-state)[^'\"]*['\"]",
            lowered,
        )
    )
    return has_input and has_action and has_result


def app_js_has_interaction(app_js: str) -> bool:
    lowered = app_js.lower()
    return any(marker in lowered for marker in ("addeventlistener", ".onclick", ".onsubmit", ".onchange"))


def browser_provider_call_markers(file_name: str, text: str) -> List[str]:
    lowered = text.lower()
    blockers: List[str] = []
    if any(marker in lowered for marker in ("api.openai.com", "openai.com/v1", "api.deepseek.com", "/chat/completions", "/v1/responses")):
        blockers.append(f"{file_name} references a provider endpoint, which must stay server-side or mocked.")
    return blockers


def prototype_network_blockers(file_name: str, text: str) -> List[str]:
    return external_network_markers(file_name, text) + browser_provider_call_markers(file_name, text)


def check_deploy_readiness(prototype: Dict[str, Any]) -> Dict[str, Any]:
    blockers: List[str] = []
    warnings: List[str] = []
    checked_files: List[str] = []
    base = Path(str(prototype.get("path") or ""))
    text_files: Dict[str, str] = {}
    required_files = ("index.html", "style.css", "app.js", "README.md")
    extra_files = ("feedback-questions.md", "test-plan.md", "codex-build-prompt.md", "prototype.json")
    for name in required_files:
        path = base / name
        if not path.exists():
            blockers.append(f"Missing required file: {name}.")
            continue
        checked_files.append(name)
        text_files[name] = path.read_text(encoding="utf-8")
    for name in extra_files:
        path = base / name
        if not path.exists():
            if name == "prototype.json":
                blockers.append("Missing prototype.json, so metadata safety cannot be verified.")
            continue
        checked_files.append(name)
        text_files[name] = path.read_text(encoding="utf-8")

    index_html = text_files.get("index.html", "")
    if index_html and 'href="style.css"' not in index_html and "href='style.css'" not in index_html:
        blockers.append("index.html does not link style.css.")
    if index_html and 'src="app.js"' not in index_html and "src='app.js'" not in index_html:
        blockers.append("index.html does not link app.js.")

    for name in ("index.html", "style.css", "app.js"):
        if name in text_files:
            blockers.extend(prototype_network_blockers(name, text_files[name]))

    app_js = text_files.get("app.js", "")
    if app_js and not app_js_has_interaction(app_js):
        blockers.append("app.js does not contain a clear event listener or form handling behavior.")
    if "localStorage" in app_js:
        user_copy = " ".join(
            text_files.get(name, "")
            for name in ("index.html", "README.md", "feedback-questions.md", "test-plan.md", "app.js")
            if name in text_files
        ).lower()
        if not any(marker in user_copy for marker in ("local", "browser", "this device")):
            blockers.append("app.js uses localStorage but the package does not clearly say the data stays local/browser-only.")
        misleading_markers = ("saved to server", "stored on our servers", "synced to cloud", "uploaded automatically")
        if any(marker in user_copy for marker in misleading_markers):
            blockers.append("The package implies server-side storage even though feedback is only local/browser storage.")

    if index_html and not prototype_has_feedback_or_cta(index_html):
        blockers.append("index.html does not contain an obvious feedback or call-to-action section.")
    if index_html and not prototype_has_input_and_result(index_html):
        blockers.append("index.html does not expose a clear input, action, and visible result area.")

    prototype_metadata = safe_json_loads(text_files.get("prototype.json", ""), None)
    if prototype_metadata is None:
        blockers.append("prototype.json is not valid JSON.")
    elif metadata_has_unsafe_path(prototype_metadata):
        blockers.append("prototype metadata contains path traversal or absolute system paths.")

    seen_blockers: set[str] = set()
    unique_blockers: List[str] = []
    for item in blockers:
        if item not in seen_blockers:
            unique_blockers.append(item)
            seen_blockers.add(item)
    seen_warnings: set[str] = set()
    unique_warnings: List[str] = []
    for item in warnings:
        if item not in seen_warnings:
            unique_warnings.append(item)
            seen_warnings.add(item)
    return {
        "ready": not unique_blockers,
        "warnings": unique_warnings,
        "blockers": unique_blockers,
        "checked_files": checked_files,
    }


def suggested_share_message(project: Dict[str, Any]) -> str:
    idea = plain_text(str(project.get("title") or project.get("raw_idea") or "this idea"), 90) or "this idea"
    return (
        f"Built a rough prototype for {idea}. It is not polished yet. "
        "Could you try the main flow and tell me what confused you, whether you would use it, and what is missing?"
    )


def suggested_feedback_instruction() -> str:
    return (
        "Ask testers to try the main flow, answer the built-in feedback questions, export the feedback JSON, "
        "and paste or import that JSON back into SprintOS."
    )


def deploy_pack_target_files(hosting_target: str) -> Dict[str, str]:
    target = normalize_hosting_target(hosting_target)
    if target == "github_pages":
        return {".nojekyll": ""}
    if target == "netlify":
        return {
            "netlify.toml": textwrap.dedent(
                """\
                [build]
                publish = "."
                """
            ).strip() + "\n"
        }
    if target == "vercel":
        return {
            "vercel.json": json.dumps(
                {
                    "cleanUrls": False,
                    "trailingSlash": False,
                },
                indent=2,
            )
            + "\n"
        }
    return {}


def deploy_pack_target_steps(hosting_target: str) -> List[str]:
    target = normalize_hosting_target(hosting_target)
    if target == "github_pages":
        return [
            "Create a new GitHub repository.",
            "Upload the full Deploy Pack contents to the repository root on the `main` branch.",
            "Open the repository settings and enable GitHub Pages from the `main` branch and root folder.",
            "Wait for the Pages site to build, then open the published Pages URL and test the main flow.",
        ]
    if target == "netlify":
        return [
            "Use the drag-and-drop deploy option in Netlify and drop this folder, or connect a repository that contains these files.",
            "Set the publish directory to the repository root (`.`) if Netlify asks for one.",
            "Publish the site and open the generated Netlify URL.",
            "Retest the main flow and the built-in feedback capture on the hosted URL.",
        ]
    if target == "vercel":
        return [
            "Import the project into Vercel from a folder-backed repository.",
            "Choose the framework preset `Other` or a plain static site option if Vercel prompts for a framework.",
            "Keep the output behavior rooted at this folder with no build step.",
            "Deploy the site and confirm the hosted URL still loads `index.html` with relative assets intact.",
        ]
    return [
        "Copy the folder to any basic static web server.",
        "Serve the folder root as static files with no build step.",
        "Open `index.html` from that server and test the main flow.",
    ]


def deploy_pack_readme(readme_text: str, hosting_target: str) -> str:
    if normalize_hosting_target(hosting_target) != "github_pages":
        return readme_text
    note = textwrap.dedent(
        """

        ## GitHub Pages Note
        This package is compatible with GitHub Pages. Upload the folder contents to the repository root, enable Pages from the `main` branch/root, and use `DEPLOY.md` for the full checklist.
        """
    ).strip()
    if "## GitHub Pages Note" in readme_text:
        return readme_text
    return readme_text.rstrip() + "\n\n" + note + "\n"


def deploy_pack_deploy_md(
    project: Dict[str, Any],
    prototype: Dict[str, Any],
    hosting_target: str,
    files_generated: List[str],
    readiness: Dict[str, Any],
    share_message: str,
) -> str:
    target_label = DEPLOY_TARGETS[hosting_target]
    prototype_type = prototype.get("prototype_label") or prototype.get("prototype_type") or "Prototype"
    readiness_lines = ["Ready for Deploy Pack generation." if readiness.get("ready") else "Not ready for Deploy Pack generation."]
    if readiness.get("warnings"):
        readiness_lines.extend(f"- Warning: {item}" for item in readiness["warnings"])
    if readiness.get("blockers"):
        readiness_lines.extend(f"- Blocker: {item}" for item in readiness["blockers"])
    included = "\n".join(f"- `{name}`" for name in files_generated)
    target_steps = "\n".join(f"{idx}. {step}" for idx, step in enumerate(deploy_pack_target_steps(hosting_target), start=1))
    troubleshooting = "\n".join(
        [
            "- If the page looks broken when opened directly from Finder, run `python3 -m http.server 8080` and open the local server instead of `file://`.",
            "- If styles or scripts are missing, confirm the host is serving the folder root and that `index.html`, `style.css`, and `app.js` are in the same directory.",
            "- If feedback JSON is missing, ask testers to use the built-in export button before closing the page.",
            "- If the hosted URL is blank, verify the platform is publishing the root directory with no build step.",
        ]
    )
    return "\n".join(
        [
            f"# Deploy Pack — {project.get('title', 'Sprint')}",
            "",
            "## What This Package Is",
            f"This is a boring, static Deploy Pack for the latest {prototype_type} prototype. It is meant for low-friction hosting on {target_label} or any other simple static web server.",
            "",
            "## What Is Included",
            included,
            "",
            "## What Is Simulated/Fake",
            "- This is still a prototype. Auth, payments, backend persistence, and cloud sync are not implemented here.",
            "- Feedback capture stays in the tester's browser until the tester exports the JSON manually.",
            "- Any dynamic behavior is front-end-only and intentionally inspectable.",
            "",
            "## Current Readiness Snapshot",
            *readiness_lines,
            "",
            "## How To Run Locally",
            "```bash",
            "python3 -m http.server 8080",
            "```",
            "Then open `http://127.0.0.1:8080/index.html`.",
            "",
            f"## How To Deploy To {target_label}",
            target_steps,
            "",
            "## How To Share With Testers",
            "- Send the hosted URL after you verify the main path once yourself.",
            "- Set expectations clearly: this is a rough prototype, not a polished product.",
            "- Ask testers to focus on where they got confused, whether they would use it, and what is missing.",
            "",
            "## Suggested Share Message",
            share_message,
            "",
            "## How To Collect Feedback",
            "- Use the built-in feedback section in the prototype.",
            "- Ask testers to export the feedback JSON after they finish.",
            "- Keep feedback focused on the main flow instead of feature brainstorming.",
            "",
            "## How To Bring Feedback Back Into SprintOS",
            "- Open the project in SprintOS.",
            "- Use the Feedback Loop panel.",
            "- Paste or import the exported tester JSON.",
            "- Generate an iteration brief once a few directional responses are in.",
            "",
            "## Common Troubleshooting",
            troubleshooting,
            "",
            "## Safety Note",
            "Do not collect sensitive personal data in this prototype.",
            "",
            "## Suggested Feedback Instruction",
            suggested_feedback_instruction(),
        ]
    ).strip() + "\n"


def deploy_pack_metadata(
    project: Dict[str, Any],
    prototype: Dict[str, Any],
    deploy_pack_id: str,
    hosting_target: str,
    created_at: str,
    files_generated: List[str],
    readiness: Dict[str, Any],
    share_message: str,
) -> Dict[str, Any]:
    return {
        "deploy_pack_id": deploy_pack_id,
        "project_id": project["id"],
        "project_title": project.get("title") or project.get("sprint", {}).get("title") or "Sprint",
        "prototype_id": prototype["id"],
        "prototype_type": prototype.get("prototype_type") or "",
        "hosting_target": hosting_target,
        "created_at": created_at,
        "source_prototype_path": export_relative_path(Path(str(prototype.get("path") or ""))),
        "files_generated": files_generated,
        "readiness": readiness,
        "suggested_share_message": share_message,
        "suggested_feedback_instruction": suggested_feedback_instruction(),
    }


def write_deploy_pack(project: Dict[str, Any], prototype: Dict[str, Any], hosting_target: str) -> Dict[str, Any]:
    hosting_target = normalize_hosting_target(hosting_target)
    readiness = check_deploy_readiness(prototype)
    if readiness["blockers"]:
        raise ValueError("Prototype is not ready for a Deploy Pack")
    created_at = now_iso()
    deploy_pack_id = str(uuid.uuid4())
    project_slug = slugify(str(project.get("title") or project.get("sprint", {}).get("title") or "prototype"), "prototype")
    base_name = f"{project_slug}-{hosting_target.replace('_', '-')}-{prototype_folder_timestamp(created_at)}"
    package_dir = deploy_pack_export_dir() / base_name
    counter = 2
    while package_dir.exists():
        package_dir = deploy_pack_export_dir() / f"{base_name}-{counter}"
        counter += 1
    package_dir.mkdir(parents=True, exist_ok=True)

    copied_files = {
        "index.html": prototype_file_path(prototype, "index.html").read_text(encoding="utf-8"),
        "style.css": prototype_file_path(prototype, "style.css").read_text(encoding="utf-8"),
        "app.js": prototype_file_path(prototype, "app.js").read_text(encoding="utf-8"),
        "README.md": deploy_pack_readme(
            prototype_file_path(prototype, "README.md").read_text(encoding="utf-8"),
            hosting_target,
        ),
        "feedback-questions.md": prototype_file_path(prototype, "feedback-questions.md").read_text(encoding="utf-8"),
        "test-plan.md": prototype_file_path(prototype, "test-plan.md").read_text(encoding="utf-8"),
        "codex-build-prompt.md": prototype_file_path(prototype, "codex-build-prompt.md").read_text(encoding="utf-8"),
    }
    extra_files = deploy_pack_target_files(hosting_target)
    files_generated = list(DEPLOY_PACK_FILES) + list(extra_files.keys())
    share_message = suggested_share_message(project)
    copied_files["DEPLOY.md"] = deploy_pack_deploy_md(project, prototype, hosting_target, files_generated, readiness, share_message)
    metadata = deploy_pack_metadata(project, prototype, deploy_pack_id, hosting_target, created_at, files_generated, readiness, share_message)
    copied_files["deploy-pack.json"] = json.dumps(metadata, indent=2) + "\n"
    all_files = {**copied_files, **extra_files}
    for name, content in all_files.items():
        (package_dir / name).write_text(content, encoding="utf-8")

    title = f"{project.get('title', 'Sprint')} — {DEPLOY_TARGETS[hosting_target]} Deploy Pack"
    with db() as conn:
        conn.execute(
            """
            INSERT INTO deploy_packs (id, project_id, prototype_id, created_at, hosting_target, title, path, metadata_json)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                deploy_pack_id,
                project["id"],
                prototype["id"],
                created_at,
                hosting_target,
                title,
                str(package_dir),
                json.dumps(metadata),
            ),
        )
        conn.execute("UPDATE projects SET updated_at = ? WHERE id = ?", (created_at, project["id"]))
        conn.commit()
    deploy_pack = get_deploy_pack(deploy_pack_id, include_instructions=True)
    if deploy_pack is None:
        raise ValueError("Deploy Pack was not saved correctly")
    record_activity_event(
        project["id"],
        "deploy_pack_generated",
        "Deploy Pack generated",
        f"Generated a {hosting_target} deploy pack from the latest prototype.",
        event_status="success",
        actor="sprintos",
        related_type="deploy_pack",
        related_id=deploy_pack_id,
        next_tiny_action="Review DEPLOY.md and share the static preview when ready.",
        report_path=str(package_dir),
        metadata={"hosting_target": hosting_target, "prototype_id": prototype.get("id")},
    )
    return deploy_pack


def deploy_pack_response(row: sqlite3.Row | Dict[str, Any], include_instructions: bool = False) -> Dict[str, Any]:
    data = dict(row)
    metadata = safe_json_loads(str(data.get("metadata_json") or "{}"), {}) or {}
    path = Path(str(data.get("path") or ""))
    result = {
        "id": str(data.get("id") or ""),
        "project_id": str(data.get("project_id") or metadata.get("project_id") or ""),
        "prototype_id": str(data.get("prototype_id") or metadata.get("prototype_id") or ""),
        "title": str(data.get("title") or "Deploy Pack"),
        "hosting_target": str(data.get("hosting_target") or metadata.get("hosting_target") or "static"),
        "hosting_target_label": DEPLOY_TARGETS.get(str(data.get("hosting_target") or metadata.get("hosting_target") or "static"), "Static"),
        "path": str(path),
        "created_at": str(data.get("created_at") or metadata.get("created_at") or ""),
        "metadata": metadata,
        "prototype_type": str(metadata.get("prototype_type") or ""),
        "files_generated": list(metadata.get("files_generated") or list(DEPLOY_PACK_FILES)),
        "readiness": metadata.get("readiness") or {"ready": True, "warnings": [], "blockers": [], "checked_files": []},
        "suggested_share_message": str(metadata.get("suggested_share_message") or ""),
        "suggested_feedback_instruction": str(metadata.get("suggested_feedback_instruction") or ""),
        "preview_url": f"/deploy_pack/{data.get('id')}/index.html",
        "zip_url": f"/api/deploy_pack_zip?id={urllib.parse.quote(str(data.get('id') or ''))}",
    }
    if include_instructions:
        deploy_path = path / "DEPLOY.md"
        result["deploy_instructions"] = deploy_path.read_text(encoding="utf-8") if deploy_path.exists() else ""
    return result


def get_deploy_pack(deploy_pack_id: str, include_instructions: bool = False) -> Optional[Dict[str, Any]]:
    with db() as conn:
        row = conn.execute("SELECT * FROM deploy_packs WHERE id = ?", (deploy_pack_id,)).fetchone()
    if not row:
        return None
    return deploy_pack_response(row, include_instructions=include_instructions)


def latest_project_deploy_pack(project_id: str, prototype_id: Optional[str] = None, include_instructions: bool = False) -> Optional[Dict[str, Any]]:
    with db() as conn:
        if prototype_id:
            row = conn.execute(
                "SELECT * FROM deploy_packs WHERE project_id = ? AND prototype_id = ? ORDER BY created_at DESC, rowid DESC LIMIT 1",
                (project_id, prototype_id),
            ).fetchone()
        else:
            row = conn.execute(
                "SELECT * FROM deploy_packs WHERE project_id = ? ORDER BY created_at DESC, rowid DESC LIMIT 1",
                (project_id,),
            ).fetchone()
    if not row:
        return None
    return deploy_pack_response(row, include_instructions=include_instructions)


def deploy_pack_file_path(deploy_pack: Dict[str, Any], filename: str) -> Path:
    return safe_flat_file_path(
        Path(str(deploy_pack.get("path") or "")),
        filename,
        deploy_pack.get("files_generated") or [],
        "Invalid deploy pack file",
    )


def build_deploy_pack_zip(deploy_pack: Dict[str, Any]) -> Tuple[str, bytes]:
    filename = deploy_pack_zip_name(deploy_pack)
    payload = build_zip_from_reader(
        deploy_pack.get("files_generated") or [],
        lambda name: deploy_pack_file_path(deploy_pack, name).read_text(encoding="utf-8"),
    )
    return filename, payload


def build_pack_files_for_target(build_target: str) -> List[str]:
    target = normalize_build_target(build_target)
    return list(BUILD_PACK_ROOT_FILES) + list(BUILD_PACK_TARGET_FILES[target])


def build_pack_run_command(build_target: str) -> str:
    target = normalize_build_target(build_target)
    if target == "static_app":
        return "python3 -m http.server 8080 -d src"
    if target in {"python_stdlib_app", "ai_tool_stub"}:
        return "python3 app.py"
    return "n/a (documentation-only build brief)"


def build_pack_test_command(build_target: str) -> str:
    target = normalize_build_target(build_target)
    if target == "static_app":
        return "python3 tests/smoke_static.py"
    if target in {"python_stdlib_app", "ai_tool_stub"}:
        return "python3 tests/smoke_app.py"
    return "n/a (documentation-only build brief)"


def build_pack_verification_commands(build_target: str) -> List[str]:
    target = normalize_build_target(build_target)
    commands = [build_pack_test_command(target)]
    if target in {"python_stdlib_app", "ai_tool_stub"}:
        commands.append("python3 -m py_compile app.py tests/smoke_app.py")
    return commands


def build_pack_preview_path(build_target: str) -> Optional[str]:
    target = normalize_build_target(build_target)
    if target == "static_app":
        return "src/index.html"
    return None


def build_pack_non_goals(project: Dict[str, Any], build_target: str) -> List[str]:
    sprint = project.get("sprint") or {}
    items = [str(item).strip() for item in (sprint.get("not_building") or []) if str(item).strip()]
    common = [
        "auth",
        "payments",
        "cloud sync",
        "external analytics",
        "automatic repo creation",
        "automatic deployment",
    ]
    if build_target == "ai_tool_stub":
        common = [
            "browser-side provider calls",
            "requiring API keys for startup or tests",
        ] + common
    seen: set[str] = set()
    result: List[str] = []
    for item in items + common:
        lowered = item.lower()
        if lowered in seen:
            continue
        seen.add(lowered)
        result.append(item)
    return result[:8]


def build_pack_suggested_first_task(project: Dict[str, Any], build_target: str, latest_iteration_info: Optional[Dict[str, Any]]) -> str:
    top_change = ""
    if latest_iteration_info:
        summary = str(latest_iteration_info.get("summary") or "").strip()
        top_change = plain_text(summary, 140)
    if build_target == "static_app":
        return (
            f"Tighten the current static app's core path and CTA without adding dependencies. "
            f"Start with the main confusion signal: {top_change or project.get('next_tiny_action') or 'make the first screen clearer.'}"
        )
    if build_target == "python_stdlib_app":
        return (
            "Keep the stdlib server tiny. Start by making the current prototype flow clearer through the served template, "
            "then add one deterministic local route or state improvement only if it directly improves the happy path."
        )
    if build_target == "ai_tool_stub":
        return (
            "Preserve the mocked/offline fallback and explicit server-side provider boundary. Improve the prompt form, "
            "response formatting, and local UX without making AI required for tests or startup."
        )
    return (
        "Choose the thinnest runnable slice from the brief and create the first local executable path "
        "without expanding into auth, deployment, or platform features."
    )


def build_pack_fake_scope(build_target: str, deploy_pack: Optional[Dict[str, Any]]) -> List[str]:
    items = [
        "No auth, payments, or cloud sync are implemented.",
        "The app is still scoped as an MVP build handoff, not a production platform.",
    ]
    if deploy_pack:
        items.append("Any shareability/readiness work from the Deploy Pack remains a local/static reference, not an automated deploy pipeline.")
    if build_target == "static_app":
        items.append("All behavior is front-end-only and deterministic.")
    elif build_target == "python_stdlib_app":
        items.append("The local server is intentionally tiny and does not include a database or background workers.")
    elif build_target == "ai_tool_stub":
        items.append("The default runtime stays mocked/offline, but a local `.env` can opt into a server-side OpenAI call.")
        items.append("The browser should only call the local `/api/generate` endpoint and must never receive the API key.")
    else:
        items.append("This target is documentation-only. It does not include a serious implementation yet.")
    return items


def replace_asset_links(index_html: str, css_ref: str, js_ref: str) -> str:
    updated = re.sub(r'href=(["\'])style\.css\1', f'href="{css_ref}"', index_html)
    updated = re.sub(r'src=(["\'])app\.js\1', f'src="{js_ref}"', updated)
    return updated


def build_pack_context(
    project: Dict[str, Any],
    prototype: Dict[str, Any],
    deploy_pack: Optional[Dict[str, Any]],
    build_target: str,
    build_pack_id: str = "",
    created_at: str = "",
) -> Dict[str, Any]:
    hydrate_project_resume_fields(project)
    sprint = project.get("sprint") or {}
    prototype_metadata = prototype.get("metadata") or {}
    feedback_info = project.get("feedback") or feedback_summary_blob(project, str(prototype.get("id") or ""))
    latest_iteration_info = feedback_info.get("latest_iteration") if isinstance(feedback_info, dict) else None
    project_title = str(project.get("title") or sprint.get("title") or "Sprint").strip()
    objective = plain_text(str(project.get("desired_output") or project_restart_goal(project)), 140) or "a visible, testable result"
    prototype_readme_text = ""
    prototype_readme_path = Path(str(prototype.get("path") or "")) / "README.md"
    if prototype_readme_path.exists():
        prototype_readme_text = prototype_readme_path.read_text(encoding="utf-8")
    current_scope = build_feature_bullets(project)
    if not current_scope:
        current_scope = [
            plain_text(str(sprint.get("best_first_version") or objective), 120),
            plain_text(str(sprint.get("done_definition") or "Keep the first version visibly testable."), 120),
        ]
    artifact_titles = [
        f"{artifact.get('title', artifact.get('filename', 'Artifact'))} ({artifact.get('filename', '')})"
        for artifact in regular_artifacts(sprint)[:4]
    ]
    run_command = build_pack_run_command(build_target)
    test_command = build_pack_test_command(build_target)
    non_goals = build_pack_non_goals(project, build_target)
    feedback_summary = str((latest_iteration_info or {}).get("summary") or "")
    if not feedback_summary:
        feedback_summary = (
            f"{(feedback_info or {}).get('count', 0)} stored feedback entr{'y' if (feedback_info or {}).get('count', 0) == 1 else 'ies'}; "
            "no iteration brief generated yet."
        )
    deploy_readiness = project.get("deploy_readiness") or check_deploy_readiness(prototype)
    acceptance = workflow_acceptance_criteria(str(project.get("workflow_id") or sprint.get("_workflow_id") or "software_mvp"), objective)
    acceptance.append("The generated repo stays dependency-free and runnable with only the standard library or static files.")
    if build_target == "static_app":
        acceptance.append("The app remains browser-openable and keeps deterministic local interactions.")
    elif build_target == "python_stdlib_app":
        acceptance.append("The local stdlib app serves one clear route and its static assets without external services.")
    elif build_target == "ai_tool_stub":
        acceptance.append("Mocked/offline output remains deterministic and clearly labeled as simulated.")
        acceptance.append("A local `.env` can opt into server-side OpenAI usage without requiring a key for startup, tests, or smoke checks.")
        acceptance.append("Provider failures, timeouts, or malformed responses fall back safely to mocked output without exposing secrets.")
    else:
        acceptance.append("The brief is specific enough that Codex can start improving it without asking planning questions.")
    suggested_first_task = build_pack_suggested_first_task(project, build_target, latest_iteration_info)
    suggested_share_message = (
        f"Here is the Codex Build Pack for {project_title}. Start with CODEX_BUILD_PROMPT.md, keep the scope local-first, "
        f"and take this first PR-sized task: {suggested_first_task}"
    )
    return {
        "build_pack_id": build_pack_id,
        "build_target": build_target,
        "build_target_label": BUILD_TARGETS[build_target],
        "project_id": project["id"],
        "project_title": project_title,
        "raw_idea": plain_text(str(project.get("raw_idea") or ""), 500),
        "one_sentence": first_sentence(str(sprint.get("one_sentence") or sprint.get("best_first_version") or project_title)),
        "objective": objective,
        "target_user": infer_target_user(project),
        "current_scope": current_scope[:5],
        "fake_scope": build_pack_fake_scope(build_target, deploy_pack),
        "status": str(project.get("status") or DEFAULT_PROJECT_STATUS),
        "workflow_id": str(project.get("workflow_id") or sprint.get("_workflow_id") or "software_mvp"),
        "current_blocker": str(project.get("current_blocker") or default_current_blocker(sprint)),
        "next_tiny_action": str(project.get("next_tiny_action") or default_next_tiny_action(sprint)),
        "best_first_version": str(sprint.get("best_first_version") or ""),
        "done_definition": str(sprint.get("done_definition") or ""),
        "artifact_titles": artifact_titles or ["Sprint plan", "Resume context", "Codex handoff"],
        "codex_handoff_summary": plain_text(str((sprint.get("codex_handoff") or {}).get("content") or ""), 900),
        "prototype_id": str(prototype.get("id") or ""),
        "prototype_type": str(prototype.get("prototype_type") or ""),
        "prototype_label": str(prototype.get("prototype_label") or prototype.get("prototype_type") or "Prototype"),
        "prototype_path": str(prototype.get("path") or ""),
        "prototype_summary": plain_text(prototype_readme_text, 700),
        "prototype_files": list(prototype.get("files_generated") or PROTOTYPE_FILES),
        "prototype_app_name": str(prototype_metadata.get("app_name") or prototype.get("app_name") or project_title),
        "prototype_app_type": str(prototype_metadata.get("app_type") or prototype.get("app_type") or prototype.get("prototype_type") or "prototype"),
        "prototype_used_ai": bool(prototype_metadata.get("used_ai")),
        "prototype_ai_provider": str(prototype_metadata.get("ai_provider") or "offline"),
        "prototype_ai_model": str(prototype_metadata.get("ai_model") or ""),
        "prototype_generated_files": list(prototype_metadata.get("generated_files") or []),
        "prototype_user_flow": list(prototype_metadata.get("user_flow") or []),
        "prototype_limitations": list(prototype_metadata.get("limitations") or []),
        "prototype_mocked_parts": list(prototype_metadata.get("mocked_parts") or []),
        "feedback_count": int((feedback_info or {}).get("count") or 0),
        "feedback_summary": feedback_summary,
        "latest_iteration_brief": plain_text(str((latest_iteration_info or {}).get("iteration_brief") or ""), 1200),
        "latest_iteration_prompt_summary": plain_text(str((latest_iteration_info or {}).get("codex_prompt") or ""), 700),
        "deploy_pack_id": str((deploy_pack or {}).get("id") or "") or None,
        "deploy_pack_path": str((deploy_pack or {}).get("path") or ""),
        "deploy_pack_target": str((deploy_pack or {}).get("hosting_target") or ""),
        "deploy_readiness": deploy_readiness,
        "created_at": created_at,
        "run_command": run_command,
        "test_command": test_command,
        "verification_commands": build_pack_verification_commands(build_target),
        "acceptance_criteria": acceptance,
        "non_goals": non_goals,
        "suggested_first_codex_task": suggested_first_task,
        "suggested_share_message": suggested_share_message,
        "source_prototype_path": export_relative_path(Path(str(prototype.get("path") or ""))),
        "source_deploy_pack_path": export_relative_path(Path(str((deploy_pack or {}).get("path") or ""))) if deploy_pack else "",
    }


def build_pack_gitignore(build_target: str) -> str:
    lines = ["__pycache__/", "*.pyc", ".DS_Store"]
    if build_target == "ai_tool_stub":
        lines.append(".env")
    return "\n".join(lines) + "\n"


def build_pack_readme(ctx: Dict[str, Any]) -> str:
    scope_lines = "\n".join(f"- {item}" for item in ctx["current_scope"])
    fake_lines = "\n".join(f"- {item}" for item in ctx["fake_scope"])
    non_goal_lines = "\n".join(f"- {item}" for item in ctx["non_goals"])
    feedback_return = (
        "If the generated app preserves the prototype-style local feedback/export loop, import that JSON back into SprintOS. "
        "Otherwise add tester notes through the Feedback Loop panel manually."
    )
    if ctx["build_target"] == "ai_tool_stub":
        return textwrap.dedent(
            f"""\
            # {ctx["project_title"]} — Codex Build Pack v1

            ## What this app is
            This generated app is a local prototype/test scaffold for an AI tool. It stays fully usable in deterministic mocked/offline mode by default, and it exposes one server-side `/api/generate` route for optional runtime AI later.

            ## Target user
            {ctx["target_user"]}

            ## Current MVP scope
            {scope_lines}

            ## What is intentionally fake/simulated
            {fake_lines}

            ## Default mode
            The default runtime is mocked/offline. No API key is required for startup, smoke tests, health checks, or normal local use.

            ## How to run locally
            ```bash
            python3 app.py
            ```

            ## How to run tests
            ```bash
            python3 tests/smoke_app.py
            ```

            ## Enable real AI locally
            1. Copy `.env.example` to `.env`.
            2. Set `AI_ENABLED=true`.
            3. Add `OPENAI_API_KEY` locally.
            4. Optionally set `MODEL`, `AI_TIMEOUT_SECONDS`, and `AI_MAX_OUTPUT_TOKENS`.
            5. If you want DeepSeek runtime support later, add it as a separate workspace task instead of changing the mocked default first.

            ## Security notes
            - Do not commit `.env`.
            - The generated app uses only the Python standard library.
            - The browser only calls the local `/api/generate` endpoint.
            - The generated app never prints, returns, or writes the API key.
            - If AI is disabled, the key is missing, the request fails, times out, or returns malformed output, the app falls back to mock mode.
            - This generated runtime supports local OpenAI opt-in today; DeepSeek runtime can be added later as a separate workspace task.

            ## How to hand this folder to Codex
            1. Open `CODEX_BUILD_PROMPT.md`.
            2. Paste it into Codex with this folder as the working directory.
            3. Ask Codex to start with the suggested first PR-sized task.

            ## What not to build yet
            {non_goal_lines}

            ## How to deploy manually later
            Keep the server local-first and boring. Choose hosting only after the mocked flow and optional AI runtime both feel directionally useful.

            ## How to bring feedback back into SprintOS
            {feedback_return}
            """
        ).strip() + "\n"
    run_text = (
        f"```bash\n{ctx['run_command']}\n```"
        if not str(ctx["run_command"]).startswith("n/a")
        else "This target is documentation-only. Read `README.md` and `CODEX_BUILD_PROMPT.md` first."
    )
    test_text = (
        f"```bash\n{ctx['test_command']}\n```"
        if not str(ctx["test_command"]).startswith("n/a")
        else "No runtime test command is defined for the documentation-only target."
    )
    deploy_later = {
        "static_app": "Serve the `src/` folder on any boring static host after the static smoke test passes.",
        "python_stdlib_app": "Containerize it or place it behind a tiny Python process manager later, but do not add platform plumbing yet.",
        "ai_tool_stub": "Add a real provider integration later, keep the provider boundary local and explicit, and treat DeepSeek runtime support as a separate workspace task after the mocked flow feels right.",
        "codex_repo_brief": "Turn the brief into the first runnable local slice before thinking about deployment.",
    }[ctx["build_target"]]
    return textwrap.dedent(
        f"""\
        # {ctx["project_title"]} — Codex Build Pack v1

        ## What this app is
        This Build Pack turns the latest SprintOS prototype into a small repo-style handoff that Codex can improve into a more serious app without starting from zero.

        ## Target user
        {ctx["target_user"]}

        ## Current MVP scope
        {scope_lines}

        ## What is intentionally fake/simulated
        {fake_lines}

        ## How to run locally
        {run_text}

        ## How to run tests
        {test_text}

        ## How to hand this folder to Codex
        1. Open `CODEX_BUILD_PROMPT.md`.
        2. Paste it into Codex with this folder as the working directory.
        3. Ask Codex to start with the suggested first PR-sized task.

        ## What not to build yet
        {non_goal_lines}

        ## How to deploy manually later
        {deploy_later}

        ## How to bring feedback back into SprintOS
        {feedback_return}
        """
    ).strip() + "\n"


