    mocked_lines = "\n".join(f"- {item}" for item in ctx.get("prototype_mocked_parts") or []) or "- Keep any mocked behavior clearly labeled."
    api_constraint = "- Do not call external APIs unless a later explicit task asks for a real provider integration."
    extra_constraints = ""
