def build_pack_static_smoke_test() -> str:
    lines = [
        "#!/usr/bin/env python3",
        "",
        "from pathlib import Path",
        "import re",
        "",
        "ROOT = Path(__file__).resolve().parents[1]",
        'required = [ROOT / "src" / "index.html", ROOT / "src" / "style.css", ROOT / "src" / "app.js"]',
        "for path in required:",
        '    assert path.exists(), f"Missing required file: {path}"',
        "",
        'index_html = (ROOT / "src" / "index.html").read_text(encoding="utf-8")',
        'style_css = (ROOT / "src" / "style.css").read_text(encoding="utf-8")',
        'app_js = (ROOT / "src" / "app.js").read_text(encoding="utf-8")',
        'assert \'href="style.css"\' in index_html or "href=\'style.css\'" in index_html',
        'assert \'src="app.js"\' in index_html or "src=\'app.js\'" in index_html',
        'assert any(marker in index_html.lower() for marker in ("<input", "<textarea", "<select", "<form"))',
        'assert "button" in index_html.lower()',
        'assert any(marker in index_html.lower() for marker in ("result", "output", "score"))',
        'assert any(marker in app_js.lower() for marker in ("addeventlistener", ".onclick", ".onsubmit", ".onchange"))',
        'assert "fetch(" not in app_js',
        'assert "xmlhttprequest" not in app_js.lower()',
        'assert "sendbeacon" not in app_js.lower()',
        "browser_text = '\\n'.join([index_html, style_css, app_js]).lower()",
        'assert "api.openai.com" not in browser_text',
        'assert "api.deepseek.com" not in browser_text',
        'assert not re.search(r"https?://(?!127\\\\.0\\\\.0\\\\.1|localhost)[^\\\\s\\"\\\')>]+", \'\\\\n\'.join([index_html, style_css, app_js]), re.IGNORECASE)',
        "",
        'print("smoke_static ok")',
    ]
    return "\n".join(lines) + "\n"


def build_pack_python_smoke_test(build_target: str) -> str:
    if build_target == "ai_tool_stub":
        return textwrap.dedent(
            """\
            #!/usr/bin/env python3

            import importlib.util
            import os
            import py_compile
            from pathlib import Path

            ROOT = Path(__file__).resolve().parents[1]
            required = [
                ROOT / "app.py",
                ROOT / "src" / "templates" / "index.html",
                ROOT / "src" / "static" / "style.css",
                ROOT / "src" / "static" / "app.js",
                ROOT / ".env.example",
                ROOT / "README.md",
                ROOT / "AGENTS.md",
                ROOT / "CODEX_BUILD_PROMPT.md",
            ]
            for path in required:
                assert path.exists(), f"Missing required file: {path}"

            app_text = (ROOT / "app.py").read_text(encoding="utf-8")
            index_html = (ROOT / "src" / "templates" / "index.html").read_text(encoding="utf-8")
            app_js = (ROOT / "src" / "static" / "app.js").read_text(encoding="utf-8")
            env_example = (ROOT / ".env.example").read_text(encoding="utf-8")

            assert "/api/generate" in app_text
            assert "urllib.request" in app_text
            assert "def mocked_output" in app_text
            assert "OPENAI_API_KEY" in app_text
            assert "AI_ENABLED" in app_text
            assert "sk-" not in app_text
            assert "/api/generate" in app_js
            assert "/api/generate" in index_html
            assert "prototype/test app" in index_html.lower()
            assert "AI_ENABLED=false" in env_example
            assert "AI_PROVIDER=openai" in env_example
            assert "OPENAI_API_KEY=" in env_example
            assert "AI_TIMEOUT_SECONDS=20" in env_example
            assert "AI_MAX_OUTPUT_TOKENS=1200" in env_example
            assert "import openai" not in app_text
            assert "from openai" not in app_text

            py_compile.compile(str(ROOT / "app.py"), doraise=True)

            os.environ["AI_ENABLED"] = "false"
            spec = importlib.util.spec_from_file_location("generated_ai_tool_app", ROOT / "app.py")
            assert spec and spec.loader
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)
            result = module.generate_output("Turn rough notes into one next step")
            assert result["ok"] is True
            assert result["used_ai"] is False
            assert result["output"]
            assert result["fallback_reason"]

            print("smoke_app ok")
            """
        ).strip() + "\n"
    required = [
        'ROOT / "app.py"',
        'ROOT / "src" / "templates" / "index.html"',
        'ROOT / "src" / "static" / "style.css"',
        'ROOT / "src" / "static" / "app.js"',
    ]
    if build_target == "ai_tool_stub":
        required.append('ROOT / ".env.example"')
    required_lines = "\n".join(f"    {item}," for item in required)
    return (
        "#!/usr/bin/env python3\n\n"
        "import py_compile\n"
        "from pathlib import Path\n\n"
        "ROOT = Path(__file__).resolve().parents[1]\n"
        "required = [\n"
        f"{required_lines}\n"
        "]\n"
        "for path in required:\n"
        "    assert path.exists(), f\"Missing required file: {path}\"\n\n"
        "index_html = (ROOT / \"src\" / \"templates\" / \"index.html\").read_text(encoding=\"utf-8\")\n"
        "assert \"/static/style.css\" in index_html\n"
        "assert \"/static/app.js\" in index_html\n\n"
        "py_compile.compile(str(ROOT / \"app.py\"), doraise=True)\n"
        "print(\"smoke_app ok\")\n"
    )


def build_pack_ai_runtime_app(ctx: Dict[str, Any]) -> str:
    default_model = "gpt-4.1-mini"
    fallback_prompt = "Help me turn this rough input into one useful next step."
    return textwrap.dedent(
        f"""\
        #!/usr/bin/env python3
        from __future__ import annotations

        import json
        import mimetypes
        import os
        import socket
        import urllib.error
        import urllib.request
        from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
        from pathlib import Path

        HOST = os.environ.get("HOST", "127.0.0.1")
        PORT = int(os.environ.get("PORT", "8080"))
        BASE_DIR = Path(__file__).resolve().parent
        TEMPLATE_PATH = BASE_DIR / "src" / "templates" / "index.html"
        STATIC_DIR = BASE_DIR / "src" / "static"
        STATIC_FILES = {{"style.css", "app.js"}}
        ENV_PATH = BASE_DIR / ".env"
        OPENAI_RESPONSES_URL = "https://api.openai.com/v1/responses"


        def load_env_file() -> None:
            if not ENV_PATH.exists():
                return
            for raw_line in ENV_PATH.read_text(encoding="utf-8").splitlines():
                line = raw_line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                key, value = line.split("=", 1)
                key = key.strip()
                value = value.strip()
                if not key:
                    continue
                if len(value) >= 2 and value[0] == value[-1] and value[0] in ('"', "'"):
                    value = value[1:-1]
                os.environ.setdefault(key, value)


        def env_flag(name: str, default: bool = False) -> bool:
            value = str(os.environ.get(name, "") or "").strip().lower()
            if not value:
                return default
            return value == "true"


        def env_int(name: str, default: int) -> int:
            try:
                value = int(str(os.environ.get(name, default) or default))
            except (TypeError, ValueError):
                return default
            return value if value > 0 else default


        def runtime_config() -> dict[str, object]:
            provider = str(os.environ.get("AI_PROVIDER", "openai") or "openai").strip().lower() or "openai"
            model = str(os.environ.get("MODEL", {json.dumps(default_model)}) or "").strip() or {json.dumps(default_model)}
            return {{
                "enabled": env_flag("AI_ENABLED", False),
                "provider": provider,
                "api_key": str(os.environ.get("OPENAI_API_KEY", "") or "").strip(),
                "model": model,
                "timeout": env_int("AI_TIMEOUT_SECONDS", 20),
                "max_output_tokens": env_int("AI_MAX_OUTPUT_TOKENS", 1200),
            }}


        def normalize_prompt(prompt: str) -> str:
            return " ".join((prompt or "").split()).strip()


        def mocked_output(prompt: str) -> str:
            cleaned = normalize_prompt(prompt) or "empty input"
            words = [word.strip(".,!?").lower() for word in cleaned.split() if word.strip(".,!?")]
            focus = ", ".join(words[:3]) or "the core task"
            return "\\n".join(
                [
                    "Mocked output for {ctx["project_title"]}",
                    "",
                    "Focus: " + focus,
                    "Suggested move: turn the messy input into one concrete next step.",
                    "Why mocked: this prototype stays fully usable without any API key.",
                    "Next builder step: {ctx["suggested_first_codex_task"]}",
                ]
            )


        def safe_error_summary(exc: Exception) -> str:
            summary = " ".join(str(exc).split()) or exc.__class__.__name__
            return summary[:180]


        def fallback_result(prompt: str, reason: str, error_summary: str = "") -> dict[str, object]:
            payload: dict[str, object] = {{
                "ok": True,
                "used_ai": False,
                "output": mocked_output(prompt),
                "fallback_reason": reason,
            }}
            if error_summary:
                payload["error_summary"] = error_summary
            return payload


        def extract_output_text(payload: dict[str, object]) -> str:
            direct = payload.get("output_text")
            if isinstance(direct, str) and direct.strip():
                return direct.strip()
            parts: list[str] = []
            for item in payload.get("output") or []:
                if not isinstance(item, dict):
                    continue
                for content in item.get("content") or []:
                    if not isinstance(content, dict):
                        continue
                    text = content.get("text") or content.get("output_text") or ""
                    if isinstance(text, str) and text.strip():
                        parts.append(text.strip())
            if parts:
                return "\\n\\n".join(parts)
            raise ValueError("Provider response did not include output text.")


        def call_openai_runtime(prompt: str, config: dict[str, object]) -> str:
            body = json.dumps(
                {{
                    "model": config["model"],
                    "input": prompt or {json.dumps(fallback_prompt)},
                    "max_output_tokens": config["max_output_tokens"],
                }}
            ).encode("utf-8")
            request = urllib.request.Request(
                OPENAI_RESPONSES_URL,
                data=body,
                headers={{
                    "Content-Type": "application/json",
                    "Authorization": "Bearer " + str(config["api_key"]),
                }},
                method="POST",
            )
            timeout = int(config["timeout"])
            try:
                with urllib.request.urlopen(request, timeout=timeout) as response:
                    payload = json.loads(response.read().decode("utf-8"))
            except urllib.error.HTTPError as exc:
                raise RuntimeError(f"Provider returned HTTP {{exc.code}}.") from exc
            except urllib.error.URLError as exc:
                if isinstance(exc.reason, socket.timeout):
                    raise TimeoutError(f"Timed out after {{timeout}} seconds.") from exc
                raise RuntimeError("Network error contacting the provider.") from exc
            except socket.timeout as exc:
                raise TimeoutError(f"Timed out after {{timeout}} seconds.") from exc
            except json.JSONDecodeError as exc:
                raise ValueError("Provider returned invalid JSON.") from exc
            return extract_output_text(payload)


        def generate_output(prompt: str) -> dict[str, object]:
            cleaned = normalize_prompt(prompt)
            config = runtime_config()
            if not config["enabled"]:
                return fallback_result(cleaned, "AI mode is disabled.")
            if str(config["provider"]) != "openai":
                return fallback_result(cleaned, "Unsupported AI provider.")
            if not str(config["api_key"]):
                return fallback_result(cleaned, "OPENAI_API_KEY is missing.")
            try:
                output = call_openai_runtime(cleaned, config)
            except TimeoutError as exc:
                return fallback_result(cleaned, "The AI request timed out.", safe_error_summary(exc))
            except ValueError as exc:
                return fallback_result(cleaned, "The AI response was malformed.", safe_error_summary(exc))
            except Exception as exc:
                return fallback_result(cleaned, "The AI request failed.", safe_error_summary(exc))
            return {{
                "ok": True,
                "used_ai": True,
                "output": output,
                "fallback_reason": "",
            }}


        load_env_file()


        class AppHandler(BaseHTTPRequestHandler):
            server_version = "BuildPackAI/1.0"

            def log_message(self, fmt: str, *args: object) -> None:
                if os.environ.get("VERBOSE"):
                    super().log_message(fmt, *args)

            def send_text(self, text: str, status: int = 200, content_type: str = "text/plain; charset=utf-8") -> None:
                data = text.encode("utf-8")
                self.send_response(status)
                self.send_header("Content-Type", content_type)
                self.send_header("Content-Length", str(len(data)))
                self.end_headers()
                self.wfile.write(data)

            def send_bytes(self, data: bytes, status: int = 200, content_type: str = "application/octet-stream") -> None:
                self.send_response(status)
                self.send_header("Content-Type", content_type)
                self.send_header("Content-Length", str(len(data)))
                self.end_headers()
                self.wfile.write(data)

            def send_json(self, payload: dict[str, object], status: int = 200) -> None:
                self.send_text(json.dumps(payload, indent=2), status=status, content_type="application/json; charset=utf-8")

            def read_json(self) -> dict[str, object]:
                length = int(self.headers.get("Content-Length", "0") or "0")
                raw = self.rfile.read(length).decode("utf-8") if length else "{{}}"
                try:
                    payload = json.loads(raw or "{{}}")
                except json.JSONDecodeError as exc:
                    raise ValueError("Request body is not valid JSON.") from exc
                if not isinstance(payload, dict):
                    raise ValueError("Request body must be a JSON object.")
                return payload

            def do_GET(self) -> None:  # noqa: N802
                if self.path in {{"/", "/index.html"}}:
                    self.send_bytes(TEMPLATE_PATH.read_bytes(), content_type="text/html; charset=utf-8")
                    return
                if self.path == "/healthz":
                    config = runtime_config()
                    self.send_json(
                        {{
                            "ok": True,
                            "mode": "ai_tool_stub",
                            "ai_enabled": bool(config["enabled"]),
                            "provider": str(config["provider"]),
                        }}
                    )
                    return
                if self.path.startswith("/static/"):
                    name = self.path.split("/", 2)[2] if self.path.count("/") >= 2 else ""
                    if name not in STATIC_FILES:
                        self.send_text("Not found", status=404)
                        return
                    target = STATIC_DIR / name
                    if not target.exists():
                        self.send_text("Not found", status=404)
                        return
                    content_type = mimetypes.guess_type(target.name)[0] or "text/plain; charset=utf-8"
                    self.send_bytes(target.read_bytes(), content_type=content_type)
                    return
                self.send_text("Not found", status=404)

            def do_POST(self) -> None:  # noqa: N802
                if self.path == "/api/generate":
                    try:
                        payload = self.read_json()
                    except ValueError as exc:
                        self.send_json(
                            {{
                                "ok": False,
                                "used_ai": False,
                                "output": mocked_output(""),
                                "fallback_reason": "Invalid request body.",
                                "error_summary": safe_error_summary(exc),
                            }},
                            status=400,
                        )
                        return
                    self.send_json(generate_output(str(payload.get("prompt") or "")))
                    return
                self.send_text("Not found", status=404)


        def main() -> None:
            server = ThreadingHTTPServer((HOST, PORT), AppHandler)
            print(f"Serving on http://{{HOST}}:{{PORT}}")
            try:
                server.serve_forever()
            except KeyboardInterrupt:
                pass
            finally:
                server.server_close()


        if __name__ == "__main__":
            main()
        """
    ).rstrip() + "\n"


def build_pack_python_app(ctx: Dict[str, Any], enable_mock_api: bool) -> str:
    mock_route = textwrap.indent('self.send_text("Not found", status=404)', " " * 16)
    mock_helper = ""
    if enable_mock_api:
        mock_helper = textwrap.indent(
            textwrap.dedent(
                f"""\
                def mocked_response(prompt: str) -> dict[str, object]:
                    cleaned = " ".join((prompt or "").split())
                    if not cleaned:
                        cleaned = "empty input"
                    words = [word.strip(".,!?").lower() for word in cleaned.split() if word.strip(".,!?")]
                    focus = ", ".join(words[:3]) or "the main idea"
                    return {{
                        "mode": "mocked",
                        "summary": "Mocked result for {ctx['project_title']}: focus on " + focus + ".",
                        "bullets": [
                            "Clarify the first user-visible step.",
                            "Keep the output deterministic and inspectable.",
                            "Improve the main result before adding breadth.",
                        ],
                        "next_step": {json.dumps(ctx["suggested_first_codex_task"])},
                    }}
                """
            ).rstrip(),
            " " * 8,
        )
        mock_route = textwrap.indent(
            textwrap.dedent(
                """\
                if self.path == "/api/mock_ai":
                    payload = self.read_json()
                    self.send_json(mocked_response(str(payload.get("prompt") or "")))
                    return
                self.send_text("Not found", status=404)
                """
            ).rstrip(),
            " " * 16,
        )
    return textwrap.dedent(
        f"""\
        #!/usr/bin/env python3
        from __future__ import annotations

        import json
        import mimetypes
        import os
        from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
        from pathlib import Path

        HOST = os.environ.get("HOST", "127.0.0.1")
        PORT = int(os.environ.get("PORT", "8080"))
        BASE_DIR = Path(__file__).resolve().parent
        TEMPLATE_PATH = BASE_DIR / "src" / "templates" / "index.html"
        STATIC_DIR = BASE_DIR / "src" / "static"
        STATIC_FILES = {{"style.css", "app.js"}}
{mock_helper}

        class AppHandler(BaseHTTPRequestHandler):
            server_version = "BuildPack/1.0"

            def log_message(self, fmt: str, *args: object) -> None:
                if os.environ.get("VERBOSE"):
                    super().log_message(fmt, *args)

            def send_text(self, text: str, status: int = 200, content_type: str = "text/plain; charset=utf-8") -> None:
                data = text.encode("utf-8")
                self.send_response(status)
                self.send_header("Content-Type", content_type)
                self.send_header("Content-Length", str(len(data)))
                self.end_headers()
                self.wfile.write(data)

            def send_bytes(self, data: bytes, status: int = 200, content_type: str = "application/octet-stream") -> None:
                self.send_response(status)
                self.send_header("Content-Type", content_type)
                self.send_header("Content-Length", str(len(data)))
                self.end_headers()
                self.wfile.write(data)

            def send_json(self, payload: dict[str, object], status: int = 200) -> None:
                self.send_text(json.dumps(payload, indent=2), status=status, content_type="application/json; charset=utf-8")

            def read_json(self) -> dict[str, object]:
                length = int(self.headers.get("Content-Length", "0") or "0")
                raw = self.rfile.read(length).decode("utf-8") if length else "{{}}"
                return json.loads(raw or "{{}}")

            def do_GET(self) -> None:  # noqa: N802
                if self.path in {{"/", "/index.html"}}:
                    self.send_bytes(TEMPLATE_PATH.read_bytes(), content_type="text/html; charset=utf-8")
                    return
                if self.path == "/healthz":
                    self.send_json({{"ok": True, "mode": {json.dumps(ctx["build_target"])}}})
                    return
                if self.path.startswith("/static/"):
                    name = self.path.split("/", 2)[2] if self.path.count("/") >= 2 else ""
                    if name not in STATIC_FILES:
                        self.send_text("Not found", status=404)
                        return
                    target = STATIC_DIR / name
                    if not target.exists():
                        self.send_text("Not found", status=404)
                        return
                    content_type = mimetypes.guess_type(target.name)[0] or "text/plain; charset=utf-8"
                    self.send_bytes(target.read_bytes(), content_type=content_type)
                    return
                self.send_text("Not found", status=404)

            def do_POST(self) -> None:  # noqa: N802
{mock_route}


        def main() -> None:
            server = ThreadingHTTPServer((HOST, PORT), AppHandler)
            print(f"Serving on http://{{HOST}}:{{PORT}}")
            try:
                server.serve_forever()
            except KeyboardInterrupt:
                pass
            finally:
                server.server_close()


        if __name__ == "__main__":
            main()
        """
    ).rstrip() + "\n"


