def build_pack_ai_app_js(ctx: Dict[str, Any]) -> str:
    feedback_js = prototype_feedback_js(
        {
            "prototype_id": ctx["prototype_id"],
            "prototype_type": ctx["prototype_type"],
            "title": ctx["project_title"],
        }
    )
    return textwrap.dedent(
        f"""\
        const input = document.getElementById('prompt-input');
        const submit = document.getElementById('prompt-submit');
        const output = document.getElementById('generated-output');
        const runtimeMode = document.getElementById('runtime-mode');
        const fallbackReason = document.getElementById('fallback-reason');

        function setState(data) {{
          const usedAi = Boolean(data && data.used_ai);
          const modeLabel = usedAi ? 'OpenAI runtime' : 'Mocked/offline fallback';
          if (runtimeMode) {{
            runtimeMode.textContent = 'Mode: ' + modeLabel;
          }}
          if (fallbackReason) {{
            const reason = data && data.fallback_reason ? data.fallback_reason : 'none';
            const summary = data && data.error_summary ? ' (' + data.error_summary + ')' : '';
            fallbackReason.textContent = 'Fallback reason: ' + reason + summary;
            fallbackReason.classList.toggle('muted', !data || !data.fallback_reason);
          }}
          if (output) {{
            output.textContent = data && typeof data.output === 'string' && data.output.trim()
              ? data.output
              : 'No output returned.';
            output.classList.remove('muted');
          }}
        }}

        async function runGenerate() {{
          const prompt = input ? input.value.trim() : '';
          const response = await fetch('/api/generate', {{
            method: 'POST',
            headers: {{ 'Content-Type': 'application/json' }},
            body: JSON.stringify({{ prompt }})
          }});
          const data = await response.json();
          setState(data);
        }}

        if (submit) {{
          submit.addEventListener('click', () => {{
            if (output) {{
              output.textContent = 'Generating locally...';
              output.classList.add('muted');
            }}
            if (runtimeMode) {{
              runtimeMode.textContent = 'Mode: generating...';
            }}
            if (fallbackReason) {{
              fallbackReason.textContent = 'Fallback reason: waiting for response...';
              fallbackReason.classList.add('muted');
            }}
            runGenerate().catch((error) => {{
              setState({{
                ok: false,
                used_ai: false,
                output: 'Local request failed before the app could respond.',
                fallback_reason: 'The local app request failed.',
                error_summary: error && error.message ? error.message : 'Unknown browser error.'
              }});
            }});
          }});
        }}

        {feedback_js}
        """
    ).strip() + "\n"


