def build_pack_metadata(
    ctx: Dict[str, Any],
    files_generated: List[str],
) -> Dict[str, Any]:
    metadata = {
        "build_pack_id": ctx["build_pack_id"],
        "project_id": ctx["project_id"],
        "project_title": ctx["project_title"],
        "prototype_id": ctx["prototype_id"],
        "deploy_pack_id": ctx["deploy_pack_id"],
        "build_target": ctx["build_target"],
        "created_at": ctx["created_at"],
        "source_prototype_path": ctx["source_prototype_path"],
        "source_deploy_pack_path": ctx["source_deploy_pack_path"],
        "files_generated": files_generated,
        "run_command": ctx["run_command"],
        "test_command": ctx["test_command"],
        "suggested_first_codex_task": ctx["suggested_first_codex_task"],
        "suggested_share_message": ctx["suggested_share_message"],
        "non_goals": ctx["non_goals"],
    }
    if ctx["build_target"] == "ai_tool_stub":
        metadata.update(
            {
                "ai_runtime_available": True,
                "ai_runtime_default_mode": "mocked",
                "ai_runtime_provider": "openai",
                "ai_runtime_requires_key": False,
                "ai_runtime_env_file": ".env.example",
                "api_endpoint": "/api/generate",
            }
        )
    return metadata


def build_pack_file_contents(
    project: Dict[str, Any],
    prototype: Dict[str, Any],
    deploy_pack: Optional[Dict[str, Any]],
    build_target: str,
    build_pack_id: str,
    created_at: str,
) -> Tuple[Dict[str, str], Dict[str, Any]]:
    build_target = normalize_build_target(build_target)
    ctx = build_pack_context(project, prototype, deploy_pack, build_target, build_pack_id=build_pack_id, created_at=created_at)
    prototype_index = prototype_file_path(prototype, "index.html").read_text(encoding="utf-8")
    prototype_style = prototype_file_path(prototype, "style.css").read_text(encoding="utf-8")
    prototype_js = prototype_file_path(prototype, "app.js").read_text(encoding="utf-8")
    files_generated = build_pack_files_for_target(build_target)
    files: Dict[str, str] = {
        "README.md": build_pack_readme(ctx),
        "AGENTS.md": build_pack_agents_md(ctx),
        "IMPLEMENTATION_BRIEF.md": build_pack_implementation_brief(ctx),
        "ACCEPTANCE_CRITERIA.md": build_pack_acceptance_criteria_md(ctx),
        "TEST_PLAN.md": build_pack_test_plan_md(ctx),
        "ROADMAP.md": build_pack_roadmap_md(ctx),
        ".gitignore": build_pack_gitignore(build_target),
    }
    files["CODEX_BUILD_PROMPT.md"] = build_pack_codex_prompt_md(ctx, files_generated)
    metadata = build_pack_metadata(ctx, files_generated)
    files["build-pack.json"] = json.dumps(metadata, indent=2) + "\n"

    if build_target == "static_app":
        files["src/index.html"] = replace_asset_links(prototype_index, "style.css", "app.js")
        files["src/style.css"] = prototype_style
        files["src/app.js"] = prototype_js
        files["tests/smoke_static.py"] = build_pack_static_smoke_test()
    elif build_target == "python_stdlib_app":
        files["app.py"] = build_pack_python_app(ctx, enable_mock_api=False)
        files["src/templates/index.html"] = replace_asset_links(prototype_index, "/static/style.css", "/static/app.js")
        files["src/static/style.css"] = prototype_style
        files["src/static/app.js"] = prototype_js
        files["tests/smoke_app.py"] = build_pack_python_smoke_test(build_target)
    elif build_target == "ai_tool_stub":
        files["app.py"] = build_pack_ai_runtime_app(ctx)
        files["src/templates/index.html"] = build_pack_ai_index_html(ctx)
        files["src/static/style.css"] = prototype_style
        files["src/static/app.js"] = build_pack_ai_app_js(ctx)
        files[".env.example"] = build_pack_env_example(build_target)
        files["tests/smoke_app.py"] = build_pack_python_smoke_test(build_target)
    else:
        files["prototype-reference.md"] = build_pack_prototype_reference_md(ctx)
        files["feedback-reference.md"] = build_pack_feedback_reference_md(ctx)
        files["deploy-reference.md"] = build_pack_deploy_reference_md(ctx)
    return files, metadata


def write_build_pack(
    project: Dict[str, Any],
    prototype: Dict[str, Any],
    build_target: str,
    deploy_pack: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    build_target = normalize_build_target(build_target)
    created_at = now_iso()
    build_pack_id = str(uuid.uuid4())
    project_slug = slugify(str(project.get("title") or project.get("sprint", {}).get("title") or "build-pack"), "build-pack")
    base_name = f"{project_slug}-{build_target.replace('_', '-')}-{prototype_folder_timestamp(created_at)}"
    package_dir = build_pack_export_dir() / base_name
    counter = 2
    while package_dir.exists():
        package_dir = build_pack_export_dir() / f"{base_name}-{counter}"
        counter += 1
    package_dir.mkdir(parents=True, exist_ok=True)
    files, metadata = build_pack_file_contents(project, prototype, deploy_pack, build_target, build_pack_id, created_at)
    for relative_path, content in files.items():
        target = package_dir / relative_path
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")
    title = f"{project.get('title', 'Sprint')} — {BUILD_TARGETS[build_target]}"
    with db() as conn:
        conn.execute(
            """
            INSERT INTO build_packs (id, project_id, prototype_id, deploy_pack_id, created_at, build_target, title, path, metadata_json)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                build_pack_id,
                project["id"],
                prototype["id"],
                str((deploy_pack or {}).get("id") or "") or None,
                created_at,
                build_target,
                title,
                str(package_dir),
                json.dumps(metadata),
            ),
        )
        conn.execute("UPDATE projects SET updated_at = ? WHERE id = ?", (created_at, project["id"]))
        conn.commit()
    build_pack = get_build_pack(build_pack_id, include_prompt=True)
    if build_pack is None:
        raise ValueError("Build Pack was not saved correctly")
    record_activity_event(
        project["id"],
        "build_pack_generated",
        "Build Pack generated",
        f"Generated a {build_target.replace('_', ' ')} build pack.",
        event_status="success",
        actor="sprintos",
        related_type="build_pack",
        related_id=build_pack_id,
        next_tiny_action=str(build_pack.get("suggested_first_codex_task") or "Export the workspace and continue inside it."),
        report_path=str(package_dir),
        metadata={"build_target": build_target, "prototype_id": prototype.get("id"), "deploy_pack_id": (deploy_pack or {}).get("id")},
    )
    return build_pack


def build_pack_response(row: sqlite3.Row | Dict[str, Any], include_prompt: bool = False) -> Dict[str, Any]:
    data = dict(row)
    metadata = safe_json_loads(str(data.get("metadata_json") or "{}"), {}) or {}
    path = Path(str(data.get("path") or ""))
    build_target = str(data.get("build_target") or metadata.get("build_target") or "static_app")
    preview_path = build_pack_preview_path(build_target)
    build_pack_id = str(data.get("id") or metadata.get("build_pack_id") or "")
    result = {
        "id": build_pack_id,
        "project_id": str(data.get("project_id") or metadata.get("project_id") or ""),
        "prototype_id": str(data.get("prototype_id") or metadata.get("prototype_id") or ""),
        "deploy_pack_id": str(data.get("deploy_pack_id") or metadata.get("deploy_pack_id") or "") or None,
        "title": str(data.get("title") or "Build Pack"),
        "build_target": build_target,
        "build_target_label": BUILD_TARGETS.get(build_target, "Build Pack"),
        "path": str(path),
        "created_at": str(data.get("created_at") or metadata.get("created_at") or ""),
        "metadata": metadata,
        "files_generated": list(metadata.get("files_generated") or build_pack_files_for_target(build_target)),
        "run_command": str(metadata.get("run_command") or build_pack_run_command(build_target)),
        "test_command": str(metadata.get("test_command") or build_pack_test_command(build_target)),
        "suggested_first_codex_task": str(metadata.get("suggested_first_codex_task") or ""),
        "suggested_share_message": str(metadata.get("suggested_share_message") or ""),
        "non_goals": list(metadata.get("non_goals") or []),
        "zip_url": f"/api/build_pack_zip?id={urllib.parse.quote(build_pack_id)}",
        "prompt_url": f"/api/build_pack_file?id={urllib.parse.quote(build_pack_id)}&file=CODEX_BUILD_PROMPT.md",
        "preview_url": f"/build_pack/{urllib.parse.quote(build_pack_id)}/{preview_path}" if preview_path else None,
    }
    if include_prompt:
        prompt_path = path / "CODEX_BUILD_PROMPT.md"
        result["codex_prompt"] = prompt_path.read_text(encoding="utf-8") if prompt_path.exists() else ""
    return result


def get_build_pack(build_pack_id: str, include_prompt: bool = False) -> Optional[Dict[str, Any]]:
    with db() as conn:
        row = conn.execute("SELECT * FROM build_packs WHERE id = ?", (build_pack_id,)).fetchone()
    if not row:
        return None
    return build_pack_response(row, include_prompt=include_prompt)


def latest_project_build_pack(project_id: str, prototype_id: Optional[str] = None, include_prompt: bool = False) -> Optional[Dict[str, Any]]:
    with db() as conn:
        if prototype_id:
            row = conn.execute(
                "SELECT * FROM build_packs WHERE project_id = ? AND prototype_id = ? ORDER BY created_at DESC, rowid DESC LIMIT 1",
                (project_id, prototype_id),
            ).fetchone()
        else:
            row = conn.execute(
                "SELECT * FROM build_packs WHERE project_id = ? ORDER BY created_at DESC, rowid DESC LIMIT 1",
                (project_id,),
            ).fetchone()
    if not row:
        return None
    return build_pack_response(row, include_prompt=include_prompt)


def build_pack_file_path(build_pack: Dict[str, Any], relative_file_path: str) -> Path:
    return safe_relative_file_path(
        Path(str(build_pack.get("path") or "")),
        relative_file_path,
        build_pack.get("files_generated") or [],
        "Invalid build pack file",
    )


def build_build_pack_zip(build_pack: Dict[str, Any]) -> Tuple[str, bytes]:
    base = slugify(str(build_pack.get("title") or "build-pack"), "build-pack")
    stamp = prototype_folder_timestamp(str(build_pack.get("created_at") or now_iso()))
    filename = sanitize_filename(f"{base}-{stamp}.zip", default_stem="build-pack", default_suffix=".zip")
    payload = build_zip_from_reader(
        build_pack.get("files_generated") or [],
        lambda name: build_pack_file_path(build_pack, name).read_text(encoding="utf-8"),
    )
    return filename, payload


def workspace_source_file_names(build_pack: Dict[str, Any]) -> List[str]:
    base = Path(str(build_pack.get("path") or "")).resolve()
    names: List[str] = []
    for path in sorted(base.rglob("*")):
        if not path.is_file():
            continue
        rel = path.relative_to(base).as_posix()
        if any(part in {"__pycache__", ".git"} for part in Path(rel).parts):
            continue
        if path.name == ".env" or path.suffix == ".pyc" or path.suffix == ".zip":
            continue
        names.append(rel)
    return names


def workspace_added_files() -> List[str]:
    return list(WORKSPACE_ADDED_FILES)


def workspace_file_names(files_copied: List[str]) -> List[str]:
    return files_copied + workspace_added_files()


def workspace_folder_path(project: Dict[str, Any], workspace_id: str) -> Path:
    slug = slugify(str(project.get("title") or project.get("sprint", {}).get("title") or "workspace"), "workspace")
    preferred = workspace_export_dir() / slug
    if not preferred.exists():
        return preferred
    fallback = workspace_export_dir() / f"{slug}-{workspace_id[:8]}"
    counter = 2
    candidate = fallback
    while candidate.exists():
        candidate = workspace_export_dir() / f"{slug}-{workspace_id[:8]}-{counter}"
        counter += 1
    return candidate


def workspace_context(
    project: Dict[str, Any],
    build_pack: Dict[str, Any],
    workspace_id: str,
    created_at: str,
    workspace_path: Path,
) -> Dict[str, Any]:
    latest_prototype = project.get("latest_prototype") or latest_project_prototype(project["id"], include_prompt=True)
    latest_deploy_pack = project.get("latest_deploy_pack") or latest_project_deploy_pack(
        project["id"],
        prototype_id=str((latest_prototype or {}).get("id") or "") or None,
        include_instructions=True,
    )
    latest_pipeline_run = project.get("latest_pipeline_run") or latest_project_pipeline_run(project["id"], include_prompt=True)
    latest_quick_launch = project.get("latest_quick_launch") or latest_project_quick_launch(project["id"])
    latest_verification_run = project.get("latest_verification_run") or latest_project_verification_run(project["id"])
    latest_workspace = project.get("latest_workspace") or latest_project_workspace(project["id"], include_prompt=True)
    latest_workspace_snapshot = project.get("latest_workspace_snapshot") or latest_project_workspace_snapshot(project["id"])
    latest_workspace_sync = project.get("latest_workspace_sync") or latest_project_workspace_sync(project["id"])
    latest_workspace_release_pack = project.get("latest_workspace_release_pack") or latest_project_workspace_release_pack(project["id"])
    current_scope = build_feature_bullets(project)
    if not current_scope:
        sprint = project.get("sprint") or {}
        current_scope = [
            plain_text(str(sprint.get("best_first_version") or project_restart_goal(project)), 120),
            plain_text(str(sprint.get("done_definition") or "Keep the first version visibly testable."), 120),
        ]
    build_metadata = build_pack.get("metadata") or {}
    return {
        "workspace_id": workspace_id,
        "project_id": project["id"],
        "project_title": str(project.get("title") or project.get("sprint", {}).get("title") or "Workspace"),
        "build_pack_id": str(build_pack.get("id") or ""),
        "build_target": str(build_pack.get("build_target") or ""),
        "build_target_label": str(build_pack.get("build_target_label") or BUILD_TARGETS.get(str(build_pack.get("build_target") or ""), "Build Pack")),
        "created_at": created_at,
        "workspace_title": f"{str(project.get('title') or 'Sprint')} Workspace",
        "workspace_path": str(workspace_path),
        "workspace_path_relative": export_relative_path(workspace_path),
        "source_build_pack_path": str(build_pack.get("path") or ""),
        "source_build_pack_path_relative": export_relative_path(Path(str(build_pack.get("path") or ""))),
        "source_prototype_path": str((latest_prototype or {}).get("path") or ""),
        "source_deploy_pack_path": str((latest_deploy_pack or {}).get("path") or ""),
        "pipeline_run_path": str((latest_pipeline_run or {}).get("report_path") or ""),
        "quick_launch_path": str((latest_quick_launch or {}).get("report_path") or ""),
        "verification_run_path": str((latest_verification_run or {}).get("report_path") or ""),
        "latest_verification_status": str((latest_verification_run or {}).get("status") or ""),
        "objective": plain_text(str(project.get("desired_output") or project_restart_goal(project)), 160) or "a visible, locally testable app",
        "raw_idea": plain_text(str(project.get("raw_idea") or ""), 500),
        "one_sentence": first_sentence(str((project.get("sprint") or {}).get("one_sentence") or project.get("title") or "")),
        "target_user": infer_target_user(project),
        "current_scope": current_scope[:5],
        "run_command": str(build_pack.get("run_command") or "n/a"),
        "test_command": str(build_pack.get("test_command") or "n/a"),
        "suggested_first_codex_task": str(build_pack.get("suggested_first_codex_task") or ""),
        "non_goals": list(build_pack.get("non_goals") or build_metadata.get("non_goals") or []),
        "ai_runtime_available": bool(build_metadata.get("ai_runtime_available")),
        "latest_prototype": latest_prototype,
        "latest_deploy_pack": latest_deploy_pack,
        "latest_pipeline_run": latest_pipeline_run,
        "latest_quick_launch": latest_quick_launch,
        "latest_verification_run": latest_verification_run,
    }


def workspace_manual_test_checklist(ctx: Dict[str, Any]) -> List[str]:
    items = [
        "Run the documented local start command.",
        "Run the documented smoke or test command.",
        "Click through the main user-visible path once.",
        "Confirm the app stays locally runnable with no cloud setup.",
        "Confirm no sensitive personal data is requested or stored by default.",
    ]
    if ctx["build_target"] == "ai_tool_stub":
        items.append("Confirm mocked/offline mode still works without a local `.env` file.")
        items.append("If you enable local AI later, confirm the browser still only calls `/api/generate`.")
    return items


def build_workspace_origin_md(ctx: Dict[str, Any]) -> str:
    return textwrap.dedent(
        f"""\
        # SprintOS Origin

        - Project title: {ctx["project_title"]}
        - Project ID: {ctx["project_id"]}
        - Build Pack ID: {ctx["build_pack_id"]}
        - Source Build Pack path: {ctx["source_build_pack_path"] or 'n/a'}
        - Prototype path: {ctx["source_prototype_path"] or 'n/a'}
        - Deploy Pack path: {ctx["source_deploy_pack_path"] or 'n/a'}
        - Pipeline run path: {ctx["pipeline_run_path"] or 'n/a'}
        - Quick Launch path: {ctx["quick_launch_path"] or 'n/a'}
        - Verification run path: {ctx["verification_run_path"] or 'n/a'}
        - Created at: {ctx["created_at"]}

        ## What this workspace is
        This is a stable local app workspace exported from a timestamped SprintOS Build Pack so Codex can continue development here without editing SprintOS internals or regenerating over the same folder.

        ## What is intentionally not included
        - No GitHub repo or remote
        - No automatic deployment setup
        - No SprintOS database internals
        - No copied `.env` file
        - No production hardening beyond the generated Build Pack scope
        """
    ).strip() + "\n"


def build_workspace_readme_md(ctx: Dict[str, Any]) -> str:
    scope_lines = "\n".join(f"- {item}" for item in ctx["current_scope"])
    non_goal_lines = "\n".join(f"- {item}" for item in ctx["non_goals"]) or "- Do not overbuild."
    return textwrap.dedent(
        f"""\
        # Workspace Readme

        ## What this workspace is
        This folder is a stable local workspace exported from SprintOS so Codex can keep developing the app without touching SprintOS internals.

        ## What app idea it represents
        {ctx["raw_idea"]}

        ## Target user
        {ctx["target_user"]}

        ## Current MVP scope
        {scope_lines}

        ## How to run locally
        ```bash
        {ctx["run_command"]}
        ```

        ## How to test
        ```bash
        {ctx["test_command"]}
        ```

        ## How to use with Codex
        1. Open `CODEX_START_HERE.md`.
        2. Paste it into Codex with this workspace as the working directory.
        3. Keep changes local-first and PR-sized.

        ## How to return improvements or feedback back to SprintOS manually
        - Keep notes on what changed in this workspace.
        - If the app still includes local feedback/export flows, bring tester feedback back into SprintOS manually.
        - Re-run SprintOS Build Pack or Run & Verify flows only when you want a fresh generated artifact or updated SprintOS reports.

        ## What not to build yet
        {non_goal_lines}

        ## Safety note
        Do not collect sensitive personal data in prototypes or test apps unless the app is explicitly hardened for that later.
        """
    ).strip() + "\n"


