def workspace_release_report_url(release_pack_id: str, filename: str = "RELEASE.md") -> str:
    return f"/api/workspace_release_file?id={urllib.parse.quote(release_pack_id)}&file={urllib.parse.quote(filename)}"


def workspace_release_zip_url(release_pack_id: str) -> str:
    return f"/api/workspace_release_zip?id={urllib.parse.quote(release_pack_id)}"


def normalize_release_label(value: Any, created_at: str) -> str:
    label = " ".join(str(value or "").strip().split())
    if label:
        return label[:80]
    return f"release-{prototype_folder_timestamp(created_at)}"


def workspace_release_folder_path(project_title: str, release_label: str, created_at: str) -> Path:
    suffix = slugify(release_label, prototype_folder_timestamp(created_at))
    base_name = f"{slugify(project_title, 'project')}-{suffix}"
    candidate = workspace_release_export_dir() / base_name
    counter = 2
    while candidate.exists():
        candidate = workspace_release_export_dir() / f"{base_name}-{counter}"
        counter += 1
    candidate.mkdir(parents=True, exist_ok=True)
    return candidate


def workspace_release_row_metadata_json(metadata: Dict[str, Any]) -> str:
    return json.dumps(json.loads(json.dumps(metadata or {})))


def workspace_release_status_from_state(*, warnings: List[str], blockers: List[str], partial: bool = False) -> str:
    if blockers:
        return "blocked"
    if partial:
        return "partial"
    if warnings:
        return "ready_with_warnings"
    return "ready"


def workspace_release_check(name: str, status: str, message: str, path: str = "") -> Dict[str, Any]:
    return {
        "name": name,
        "status": status,
        "message": message,
        "path": path,
    }


def workspace_release_is_ai_tool(workspace_metadata: Dict[str, Any], build_pack: Optional[Dict[str, Any]], base: Path) -> bool:
    build_target = str(workspace_metadata.get("build_target") or (build_pack or {}).get("build_target") or "").strip().lower()
    if build_target == "ai_tool_stub":
        return True
    app_path = base / "app.py"
    if not app_path.exists():
        return False
    try:
        app_text = app_path.read_text(encoding="utf-8")
    except OSError:
        return False
    return "/api/generate" in app_text and "AI_ENABLED" in app_text


def detect_workspace_release_type(
    workspace: Dict[str, Any],
    workspace_metadata: Dict[str, Any],
    build_pack: Optional[Dict[str, Any]] = None,
) -> str:
    build_target = str(
        workspace_metadata.get("build_target")
        or (workspace.get("metadata") or {}).get("build_target")
        or (build_pack or {}).get("build_target")
        or ""
    ).strip().lower()
    mapping = {
        "static_app": "static_site",
        "python_stdlib_app": "local_python_app",
        "ai_tool_stub": "ai_tool_app",
        "codex_repo_brief": "repo_brief",
    }
    if build_target in mapping:
        return mapping[build_target]
    base = Path(str(workspace.get("path") or "")).resolve()
    if (base / "src" / "index.html").exists():
        return "static_site"
    if (base / "app.py").exists():
        if workspace_release_is_ai_tool(workspace_metadata, build_pack, base):
            return "ai_tool_app"
        return "local_python_app"
    return "repo_brief"


def workspace_release_should_exclude_relative_path(relative_path: str) -> bool:
    path = Path(relative_path)
    name = path.name
    if not relative_path:
        return True
    if name == ".DS_Store":
        return True
    if name.startswith(".env") and name != ".env.example":
        return True
    if path.suffix.lower() in WORKSPACE_RELEASE_BINARY_SUFFIXES:
        return True
    if path.suffix.lower() == ".zip":
        return True
    if any(part in WORKSPACE_RELEASE_DIR_EXCLUDES for part in path.parts):
        return True
    if path.parts and path.parts[0] in WORKSPACE_RELEASE_TOP_LEVEL_EXCLUDES:
        return True
    return False


def workspace_release_source_paths(base: Path) -> List[Path]:
    resolved_base = base.resolve()
    files: List[Path] = []
    for path in sorted(resolved_base.rglob("*")):
        if not path.is_file() or path.is_symlink():
            continue
        try:
            resolved = path.resolve()
            relative_path = resolved.relative_to(resolved_base).as_posix()
        except ValueError:
            continue
        if workspace_release_should_exclude_relative_path(relative_path):
            continue
        files.append(resolved)
    return files


def workspace_release_find_key_path(base: Path) -> Optional[Path]:
    for path in workspace_release_source_paths(base):
        try:
            text = path.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            continue
        if OBVIOUS_SECRET_PATTERN.search(text):
            return path
    return None


def workspace_release_copy_app_files(source_base: Path, app_dir: Path) -> List[str]:
    copied: List[str] = []
    resolved_app_dir = app_dir.resolve()
    for source in workspace_release_source_paths(source_base):
        relative_path = source.relative_to(source_base).as_posix()
        target = (resolved_app_dir / relative_path).resolve()
        try:
            target.relative_to(resolved_app_dir)
        except ValueError as exc:
            raise ValueError("Workspace release copy escaped the allowed app folder") from exc
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, target)
        copied.append(f"app/{relative_path}")
    return copied


def workspace_release_file_path(release_pack: Dict[str, Any], relative_file_path: str) -> Path:
    return safe_relative_file_path(
        Path(str(release_pack.get("path") or "")),
        relative_file_path,
        release_pack.get("files_generated") or [],
        "Invalid workspace release file",
    )


def build_workspace_release_zip(release_pack: Dict[str, Any]) -> Tuple[str, bytes]:
    filename = sanitize_filename(
        f"{slugify(str((release_pack.get('metadata') or {}).get('project_title') or 'workspace-release'), 'workspace-release')}-{prototype_folder_timestamp(str(release_pack.get('created_at') or now_iso()))}.zip",
        default_stem="workspace-release",
        default_suffix=".zip",
    )
    payload = build_zip_from_reader(
        release_pack.get("files_generated") or [],
        lambda name: workspace_release_file_path(release_pack, name).read_text(encoding="utf-8"),
    )
    return filename, payload


def workspace_release_sync_reference(project_id: str, workspace_id: str, run_checks: bool) -> Optional[Dict[str, Any]]:
    latest_sync = latest_project_workspace_sync(project_id, workspace_id=workspace_id)
    if latest_sync:
        return latest_sync
    if not run_checks:
        return None
    return run_workspace_sync(project_id, workspace_id=workspace_id, run_checks=False)


def workspace_release_verification_reference(project_id: str, run_checks: bool) -> Optional[Dict[str, Any]]:
    latest_verification = latest_project_verification_run(project_id)
    if latest_verification:
        return latest_verification
    if not run_checks:
        return None
    return run_project_verification(project_id, verification_scope="all_latest")


def workspace_release_frontend_fetches_local_api(text: str) -> bool:
    normalized = text.replace('"', "'")
    return "/api/generate" in normalized and "http://" not in normalized and "https://" not in normalized


def workspace_release_required_paths_for_type(release_type: str) -> List[str]:
    if release_type == "static_site":
        return ["src/index.html", "src/style.css", "src/app.js"]
    if release_type in {"local_python_app", "ai_tool_app"}:
        return ["app.py"]
    return ["README.md", "ACCEPTANCE_CRITERIA.md", "TEST_PLAN.md"]


def workspace_release_summary_from_sync(workspace_sync: Optional[Dict[str, Any]]) -> str:
    if not workspace_sync:
        return "No workspace sync exists yet."
    return str(workspace_sync.get("what_likely_changed") or workspace_sync_change_summary(list(workspace_sync.get("changed_files") or [])))


def workspace_release_notes_markdown(project: Dict[str, Any], payload: Dict[str, Any]) -> str:
    workspace_sync = payload.get("workspace_sync") or {}
    verification_run = payload.get("verification_run") or {}
    snapshot = payload.get("snapshot") or {}
    changed_files = list((workspace_sync.get("changed_files") or []))
    lines = [
        f"# Release Notes — {project.get('title') or 'Sprint'}",
        "",
        "## Latest Workspace Sync Summary",
        workspace_release_summary_from_sync(payload.get("workspace_sync")),
        "",
        "## Changed Files Count",
        str(len(changed_files)),
        "",
        "## Changed Files List",
    ]
    lines.extend([f"- `{item.get('path')}`" for item in changed_files] or ["- No changed files were recorded."])
    lines.extend(
        [
            "",
            "## Latest Snapshot Reference",
            str(snapshot.get("snapshot_path") or snapshot.get("snapshot_label") or "No snapshot exists yet."),
            "",
            "## Latest Verification Result",
            f"{verification_run.get('status') or 'No verification exists yet.'}",
            "",
            "## What Likely Changed",
            workspace_release_summary_from_sync(payload.get("workspace_sync")),
            "",
            "## Known Limitations",
        ]
    )
    lines.extend([f"- {item}" for item in (payload.get("warnings") or [])] or ["- No extra limitations recorded."])
    lines.extend(["", "## Follow-Up Tasks"])
    lines.extend([f"- {item}" for item in payload.get("follow_up_tasks", [])] or [f"- {payload.get('next_tiny_action') or 'Review the release checklist.'}"])
    lines.append("")
    return "\n".join(lines)


def workspace_release_change_summary_markdown(payload: Dict[str, Any]) -> str:
    workspace_sync = payload.get("workspace_sync") or {}
    changed_files = list(workspace_sync.get("changed_files") or [])
    lines = [
        f"# Change Summary — {payload.get('project_title') or 'Sprint'}",
        "",
        "## What Changed",
        workspace_release_summary_from_sync(payload.get("workspace_sync")),
        "",
        "## Changed Files",
    ]
    lines.extend([f"- `{item.get('path')}` ({item.get('change_type') or 'changed'})" for item in changed_files] or ["- No changed files were recorded."])
