def workspace_release_checklist_markdown(payload: Dict[str, Any]) -> str:
    command_summary = payload.get("command_center") or {}
    recommended_action = command_summary.get("recommended_action") or {}
    checks = list(payload.get("checks") or [])
    lines = [
        f"# Release Checklist — {payload.get('project_title') or 'Sprint'}",
        "",
        f"- Release status: {payload.get('release_status') or ''}",
        f"- Release type: {payload.get('release_type') or ''}",
        f"- Share ready: {bool(payload.get('share_ready'))}",
        f"- Codex ready: {bool(payload.get('codex_ready'))}",
        f"- Command Center next action: {recommended_action.get('label') or 'No action'}",
        "",
        "## Checks",
    ]
    for item in checks:
        marker = {"pass": "[x]", "warn": "[!]", "fail": "[ ]", "partial": "[-]"}.get(str(item.get("status") or ""), "[-]")
        lines.append(f"- {marker} {item.get('name')}: {item.get('message')}")
    lines.append("")
    return "\n".join(lines)


