def workspace_release_readme(project: Dict[str, Any], payload: Dict[str, Any]) -> str:
    command_summary = payload.get("command_center") or {}
    recommended_action = command_summary.get("recommended_action") or {}
    latest_focus_session = project.get("latest_focus_session") or latest_project_focus_session(project["id"])
    warnings = payload.get("warnings") or []
    blockers = payload.get("blockers") or []
    share_readiness = "Share-ready after manual review." if payload.get("share_ready") else "Not share-ready yet."
    codex_readiness = "Codex-ready for the next iteration." if payload.get("codex_ready") else "Not Codex-ready yet."
    lines = [
        f"# Release — {project.get('title') or 'Sprint'}",
        "",
        "## Project Title",
        str(project.get("title") or ""),
        "",
        "## Release Label",
        str(payload.get("release_label") or ""),
        "",
        "## Release Type",
        WORKSPACE_RELEASE_TEXT_MARKERS.get(str(payload.get("release_type") or ""), str(payload.get("release_type") or "")),
        "",
        "## Status",
        str(payload.get("release_status") or ""),
        "",
        "## What This App Does",
        str(payload.get("what_this_app_does") or ""),
        "",
        "## Target User",
        str(payload.get("target_user") or ""),
        "",
        "## Current MVP Scope",
    ]
    lines.extend([f"- {item}" for item in (payload.get("current_scope") or [])] or ["- No scope summary recorded."])
    lines.extend(
        [
            "",
            "## What Is Simulated/Fake",
        ]
    )
    lines.extend([f"- {item}" for item in (payload.get("simulated") or [])] or ["- No extra simulated pieces were recorded."])
    lines.extend(
        [
            "",
            "## How To Run",
            str(payload.get("run_command") or "See DEPLOY_OR_SHARE.md."),
            "",
            "## How To Test",
            str(payload.get("test_command") or "See RUN_AND_TEST.md."),
            "",
            "## Share Readiness",
            share_readiness,
            "",
            "## Codex Readiness",
            codex_readiness,
            "",
            "## Warnings/Blockers",
        ]
    )
    lines.extend([f"- Warning: {item}" for item in warnings])
    lines.extend([f"- Blocker: {item}" for item in blockers])
    if not warnings and not blockers:
        lines.append("- none")
    lines.extend(
        [
            "",
            "## Next Tiny Action",
            str(payload.get("next_tiny_action") or ""),
            "",
            "## Command Center Recommended Action",
            f"{recommended_action.get('label') or 'No action'}",
            str(command_summary.get("next_tiny_action") or recommended_action.get("reason") or ""),
            "",
        ]
    )
    if latest_focus_session:
        lines.extend(
            [
                "## Latest Focus Session",
                f"- Status: {latest_focus_session.get('session_status') or ''}",
                f"- Next tiny action: {latest_focus_session.get('next_tiny_action') or ''}",
                "",
            ]
        )
    return "\n".join(lines)


def workspace_release_next_prompt(project: Dict[str, Any], payload: Dict[str, Any]) -> str:
    warnings = "\n".join(f"- {item}" for item in (payload.get("warnings") or [])) or "- none"
    blockers = "\n".join(f"- {item}" for item in (payload.get("blockers") or [])) or "- none"
    checks = list(payload.get("checks") or [])
    failed_checks = "\n".join(f"- {item.get('name')}: {item.get('message')}" for item in checks if item.get("status") == "fail") or "- none"
    likely_touched = "\n".join(f"- `{item}`" for item in payload.get("files_likely_touched", [])) or "- Inspect the release app folder."
    objective = (
        "Improve the current release candidate with one small next iteration while preserving current run/test behavior."
        if payload.get("release_status") in {"ready", "ready_with_warnings"}
        else "Fix the release blockers so this release candidate becomes locally runnable, testable, and safe to share manually."
    )
    acceptance_lines = [
        "- Keep the app locally runnable.",
        "- Preserve current run/test behavior unless a blocker requires a targeted fix.",
        "- Keep the change PR-sized and avoid overbuilding.",
        "- Do not expose API keys or read/export `.env` contents.",
    ]
    if payload.get("release_status") not in {"ready", "ready_with_warnings"}:
        acceptance_lines.insert(0, "- Clear the failed release checks listed below.")
    non_goals = "\n".join(
        [
            "- Do not edit SprintOS internals from this release app.",
            "- Do not add auth, cloud sync, GitHub automation, or deployment automation.",
            "- Do not commit or share `.env`.",
            "- Do not overbuild.",
        ]
    )
    acceptance_text = "\n".join(acceptance_lines)
    verification_commands = "\n".join(payload.get("verification_commands") or DEFAULT_VERIFICATION_COMMANDS)
    return textwrap.dedent(
        f"""\
        # Codex Next Prompt — {project.get("title") or "Sprint"}

        Read AGENTS.md first.

        You are working inside the release app/workspace, not SprintOS internals.

        ## Objective
        {objective}

        ## Current Status
        - Release label: {payload.get("release_label") or ""}
        - Release status: {payload.get("release_status") or ""}
        - Release type: {payload.get("release_type") or ""}
        - Release path: {payload.get("path") or ""}
        - App path: {payload.get("app_path") or ""}

        ## Warnings
        {warnings}

        ## Blockers
        {blockers}

        ## Failed Checks
        {failed_checks}

        ## Files Likely Touched
        {likely_touched}

        ## Acceptance Criteria
        {acceptance_text}

        ## Verification Commands
        ```bash
        {verification_commands}
        ```

        ## Non-Goals
        {non_goals}

        Preserve existing behavior.
        Keep the app locally runnable.
        Do not expose API keys.
        Do not overbuild.
        """
    ).strip() + "\n"


def workspace_release_release_pack_json(payload: Dict[str, Any]) -> str:
    export = {
        "release_pack_id": payload.get("release_pack_id"),
        "project_id": payload.get("project_id"),
        "workspace_id": payload.get("workspace_id"),
        "workspace_sync_id": payload.get("workspace_sync_id"),
        "verification_run_id": payload.get("verification_run_id"),
        "snapshot_id": payload.get("snapshot_id"),
        "created_at": payload.get("created_at"),
        "release_label": payload.get("release_label"),
        "release_status": payload.get("release_status"),
        "release_type": payload.get("release_type"),
        "path": payload.get("path"),
        "app_path": payload.get("app_path"),
        "files_copied": payload.get("files_copied") or [],
        "files_added": payload.get("files_added") or [],
        "warnings": payload.get("warnings") or [],
        "blockers": payload.get("blockers") or [],
        "run_command": payload.get("run_command") or "",
        "test_command": payload.get("test_command") or "",
        "share_ready": bool(payload.get("share_ready")),
        "codex_ready": bool(payload.get("codex_ready")),
        "next_tiny_action": payload.get("next_tiny_action") or "",
        "tester_message": payload.get("tester_message") or "",
        "codex_next_prompt_path": payload.get("codex_next_prompt_path") or "",
    }
    return json.dumps(export, indent=2) + "\n"


def workspace_release_smoke_result(base: Path, smoke_path: str) -> Dict[str, Any]:
    if not safe_file_exists(base, smoke_path):
        return {"present": False, "result": None}
    return {"present": True, "result": run_safe_generated_check(["python3", smoke_path], base)}


def create_workspace_release_pack(
    project_id: str,
    *,
    workspace_id: Optional[str] = None,
    release_label: str = "",
    run_checks: bool = True,
) -> Dict[str, Any]:
    if not project_id:
        raise ValueError("project_id is required")
    project = get_project(project_id)
    if not project:
        raise ValueError("Project not found")
    workspace = get_workspace(workspace_id, include_prompt=True) if workspace_id else (project.get("latest_workspace") or latest_project_workspace(project_id, include_prompt=True))
    if not workspace:
        raise ValueError("No workspace exists for this project yet")
    if str(workspace.get("project_id") or "") != project_id:
        raise ValueError("Workspace does not belong to this project")
    base = Path(str(workspace.get("path") or "")).resolve()
    if not base.exists() or not base.is_dir():
        raise ValueError("Workspace folder is missing")
    build_pack = get_build_pack(str(workspace.get("build_pack_id") or ""), include_prompt=True) if workspace.get("build_pack_id") else None
    workspace_json_path = base / "workspace.json"
    workspace_metadata = safe_json_loads(workspace_json_path.read_text(encoding="utf-8") if workspace_json_path.exists() else "", None)
    if not isinstance(workspace_metadata, dict):
        workspace_metadata = {}
    resolved_workspace_id = str(workspace.get("workspace_id") or workspace.get("id") or "")
    workspace_sync = workspace_release_sync_reference(project_id, resolved_workspace_id, run_checks)
    verification_run = workspace_release_verification_reference(project_id, run_checks)
    snapshot = latest_project_workspace_snapshot(project_id, workspace_id=resolved_workspace_id)
    release_type = detect_workspace_release_type(workspace, workspace_metadata, build_pack)
    checks: List[Dict[str, Any]] = []
    warnings: List[str] = []
    blockers: List[str] = []
    partial = False
    for name in ("workspace.json", "CODEX_START_HERE.md", "RUN_AND_TEST.md", "AGENTS.md"):
        target = base / name
        if target.exists():
            checks.append(workspace_release_check(f"{name} exists", "pass", f"{name} exists.", str(target)))
        else:
            checks.append(workspace_release_check(f"{name} exists", "fail", f"Missing required workspace file: {name}.", str(target)))
            blockers.append(f"Missing required workspace file: {name}.")
    if workspace_json_path.exists() and isinstance(safe_json_loads(workspace_json_path.read_text(encoding="utf-8"), None), dict):
        checks.append(workspace_release_check("workspace.json parses", "pass", "workspace.json parses successfully.", str(workspace_json_path)))
    else:
        checks.append(workspace_release_check("workspace.json parses", "fail", "workspace.json is not valid JSON.", str(workspace_json_path)))
        blockers.append("workspace.json is not valid JSON.")
    env_paths = [
        path
        for path in base.rglob("*")
        if path.is_file() and path.name.startswith(".env") and path.name != ".env.example"
    ]
    if env_paths:
        first_env = env_paths[0]
        checks.append(workspace_release_check("no .env copied", "fail", "A .env file exists in the workspace.", str(first_env)))
        blockers.append("A .env file exists in the workspace.")
    else:
        checks.append(workspace_release_check("no .env copied", "pass", "No .env file was copied into the workspace.", str(base)))
    hardcoded_key_path = workspace_release_find_key_path(base)
    if hardcoded_key_path:
        checks.append(workspace_release_check("no obvious hardcoded API keys", "fail", "An obvious hardcoded API key pattern was detected.", str(hardcoded_key_path)))
        blockers.append("An obvious hardcoded API key pattern was detected.")
    else:
        checks.append(workspace_release_check("no obvious hardcoded API keys", "pass", "No obvious hardcoded API key pattern was detected.", str(base)))
    if workspace_sync:
        sync_status = str(workspace_sync.get("sync_status") or "partial")
        status = "pass" if sync_status == "passed" else "warn" if sync_status in {"passed_with_warnings", "partial"} else "fail"
        checks.append(workspace_release_check("latest workspace sync exists", status, f"Latest Workspace Sync status: {sync_status}.", str(workspace_sync.get("report_path") or workspace_sync.get("path") or "")))
        if sync_status == "failed":
            blockers.append("Latest Workspace Sync failed.")
        elif sync_status in {"passed_with_warnings", "partial"}:
            warnings.append(f"Latest Workspace Sync status: {sync_status}.")
            partial = partial or sync_status == "partial"
    else:
        checks.append(workspace_release_check("latest workspace sync exists", "partial", "No workspace sync exists yet.", str(base)))
        warnings.append("No workspace sync exists yet.")
        partial = True
    if verification_run:
        verification_status = str(verification_run.get("status") or "partial")
        status = "pass" if verification_status == "passed" else "warn" if verification_status in {"passed_with_warnings", "partial"} else "fail"
        checks.append(workspace_release_check("latest verification exists", status, f"Latest verification status: {verification_status}.", str(verification_run.get("report_path") or "")))
        if verification_status == "failed":
            blockers.append("Latest verification run failed.")
        elif verification_status in {"passed_with_warnings", "partial"}:
            warnings.append(f"Latest verification status: {verification_status}.")
            partial = partial or verification_status == "partial"
    else:
        checks.append(workspace_release_check("latest verification exists", "partial", "No verification run exists yet.", str(base)))
        warnings.append("No verification run exists yet.")
        partial = True

    run_command = str(workspace_metadata.get("run_command") or workspace.get("run_command") or "")
    test_command = str(workspace_metadata.get("test_command") or workspace.get("test_command") or "")
    files_likely_touched: List[str] = []
    if workspace_sync:
        files_likely_touched = [str(item.get("path") or "") for item in (workspace_sync.get("changed_files") or []) if str(item.get("path") or "").strip()]

    if release_type == "static_site":
        required = {
            "src/index.html": base / "src" / "index.html",
            "src/style.css": base / "src" / "style.css",
            "src/app.js": base / "src" / "app.js",
        }
        texts: Dict[str, str] = {}
        for relative_name, target in required.items():
            if target.exists():
                checks.append(workspace_release_check(f"{relative_name} exists", "pass", f"{relative_name} exists.", str(target)))
                texts[relative_name] = target.read_text(encoding="utf-8")
            else:
                checks.append(workspace_release_check(f"{relative_name} exists", "fail", f"Missing required file: {relative_name}.", str(target)))
                blockers.append(f"Missing required file: {relative_name}.")
        index_text = texts.get("src/index.html", "")
        if 'style.css' in index_text and 'app.js' in index_text:
            checks.append(workspace_release_check("index.html references style.css/app.js", "pass", "index.html references style.css and app.js.", str(required["src/index.html"])))
        else:
            checks.append(workspace_release_check("index.html references style.css/app.js", "fail", "index.html is missing style.css or app.js references.", str(required["src/index.html"])))
            blockers.append("index.html is missing style.css or app.js references.")
        network_blockers = []
        for relative_name in ("src/index.html", "src/app.js"):
            for item in external_network_markers(relative_name, texts.get(relative_name, "")):
                network_blockers.append(item)
        if network_blockers:
            checks.append(workspace_release_check("no browser-side external provider calls", "fail", network_blockers[0], str(required["src/app.js"])))
            blockers.extend(dedupe_items(network_blockers))
        else:
            checks.append(workspace_release_check("no browser-side external provider calls", "pass", "No obvious browser-side external provider calls were found.", str(required["src/app.js"])))
        feedback_text = " ".join(texts.values()).lower()
        if "feedback" in feedback_text and "export" in feedback_text:
            checks.append(workspace_release_check("feedback/export flow exists", "pass", "Feedback/export markers are present.", str(required["src/app.js"])))
        else:
            checks.append(workspace_release_check("feedback/export flow exists", "warn", "Feedback/export markers are not obvious in the static release.", str(required["src/app.js"])))
            warnings.append("Feedback/export markers are not obvious in the static release.")
    elif release_type == "local_python_app":
        app_path = base / "app.py"
        if app_path.exists():
            checks.append(workspace_release_check("app.py exists", "pass", "app.py exists.", str(app_path)))
            try:
                py_compile.compile(str(app_path), doraise=True)
                checks.append(workspace_release_check("app.py syntax-compiles", "pass", "app.py syntax-compiles.", str(app_path)))
            except py_compile.PyCompileError as exc:
                checks.append(workspace_release_check("app.py syntax-compiles", "fail", plain_text(exc.msg, 220), str(app_path)))
                blockers.append("app.py failed to syntax-compile.")
        else:
            checks.append(workspace_release_check("app.py exists", "fail", "Missing required file: app.py.", str(app_path)))
            blockers.append("Missing required file: app.py.")
        for relative_name in ("src/templates/index.html", "src/static/style.css", "src/static/app.js"):
            target = base / relative_name
            if target.exists():
                checks.append(workspace_release_check(f"{relative_name} exists", "pass", f"{relative_name} exists.", str(target)))
            else:
                checks.append(workspace_release_check(f"{relative_name} exists", "fail", f"Missing required file: {relative_name}.", str(target)))
                blockers.append(f"Missing required file: {relative_name}.")
        smoke = workspace_release_smoke_result(base, "tests/smoke_app.py")
        if smoke["present"]:
            result = smoke["result"] or {}
            if result.get("returncode") == 0 and not result.get("timed_out"):
                checks.append(workspace_release_check("generated smoke test passes", "pass", "tests/smoke_app.py passed.", str(base / "tests" / "smoke_app.py")))
            else:
                checks.append(workspace_release_check("generated smoke test passes", "fail", "tests/smoke_app.py failed.", str(base / "tests" / "smoke_app.py")))
                blockers.append("tests/smoke_app.py failed.")
    elif release_type == "ai_tool_app":
        app_path = base / "app.py"
        frontend_path = base / "src" / "static" / "app.js"
        html_path = base / "src" / "templates" / "index.html"
        readme_path = base / "README.md"
        env_example_path = base / ".env.example"
        app_text = app_path.read_text(encoding="utf-8") if app_path.exists() else ""
        frontend_text = frontend_path.read_text(encoding="utf-8") if frontend_path.exists() else ""
        html_text = html_path.read_text(encoding="utf-8") if html_path.exists() else ""
        readme_text = readme_path.read_text(encoding="utf-8") if readme_path.exists() else ""
        if app_path.exists():
            checks.append(workspace_release_check("app.py exists", "pass", "app.py exists.", str(app_path)))
            try:
                py_compile.compile(str(app_path), doraise=True)
                checks.append(workspace_release_check("app.py syntax-compiles", "pass", "app.py syntax-compiles.", str(app_path)))
            except py_compile.PyCompileError as exc:
                checks.append(workspace_release_check("app.py syntax-compiles", "fail", plain_text(exc.msg, 220), str(app_path)))
                blockers.append("app.py failed to syntax-compile.")
        else:
            checks.append(workspace_release_check("app.py exists", "fail", "Missing required file: app.py.", str(app_path)))
            blockers.append("Missing required file: app.py.")
        if env_example_path.exists():
            checks.append(workspace_release_check(".env.example exists", "pass", ".env.example exists.", str(env_example_path)))
        else:
            checks.append(workspace_release_check(".env.example exists", "fail", "Missing required file: .env.example.", str(env_example_path)))
            blockers.append("Missing required file: .env.example.")
        if "/api/generate" in app_text and "do_POST" in app_text:
            checks.append(workspace_release_check("POST /api/generate behavior exists", "pass", "app.py includes POST /api/generate behavior.", str(app_path)))
        else:
            checks.append(workspace_release_check("POST /api/generate behavior exists", "fail", "app.py is missing POST /api/generate behavior.", str(app_path)))
            blockers.append("app.py is missing POST /api/generate behavior.")
        if all(marker in app_text for marker in ("mocked_output", "fallback_result", "used_ai")):
            checks.append(workspace_release_check("mocked fallback behavior exists", "pass", "Mocked fallback markers are present.", str(app_path)))
        else:
            checks.append(workspace_release_check("mocked fallback behavior exists", "fail", "Mocked fallback markers are missing.", str(app_path)))
            blockers.append("Mocked fallback markers are missing.")
        if workspace_release_frontend_fetches_local_api(frontend_text + "\n" + html_text):
            checks.append(workspace_release_check("frontend calls local /api/generate only", "pass", "Frontend calls local /api/generate only.", str(frontend_path)))
        else:
            checks.append(workspace_release_check("frontend calls local /api/generate only", "fail", "Frontend does not clearly call local /api/generate only.", str(frontend_path)))
            blockers.append("Frontend does not clearly call local /api/generate only.")
        readme_lower = readme_text.lower()
        if "mocked/offline" in readme_lower and ".env.example" in readme_text and "do not commit `.env`" in readme_lower:
            checks.append(workspace_release_check("README explains mocked/offline default", "pass", "README explains mocked/offline default and local AI opt-in.", str(readme_path)))
        else:
            checks.append(workspace_release_check("README explains mocked/offline default", "fail", "README is missing mocked/offline or local AI instructions.", str(readme_path)))
            blockers.append("README is missing mocked/offline or local AI instructions.")
        smoke = workspace_release_smoke_result(base, "tests/smoke_app.py")
        if smoke["present"]:
            result = smoke["result"] or {}
            if result.get("returncode") == 0 and not result.get("timed_out"):
                checks.append(workspace_release_check("generated smoke test passes", "pass", "tests/smoke_app.py passed.", str(base / "tests" / "smoke_app.py")))
            else:
                checks.append(workspace_release_check("generated smoke test passes", "fail", "tests/smoke_app.py failed.", str(base / "tests" / "smoke_app.py")))
                blockers.append("tests/smoke_app.py failed.")
    else:
        for relative_name in ("README.md", "ACCEPTANCE_CRITERIA.md", "TEST_PLAN.md"):
            target = base / relative_name
            if target.exists():
                checks.append(workspace_release_check(f"{relative_name} exists", "pass", f"{relative_name} exists.", str(target)))
            else:
                checks.append(workspace_release_check(f"{relative_name} exists", "fail", f"Missing required file: {relative_name}.", str(target)))
                blockers.append(f"Missing required file: {relative_name}.")
        start_here = base / "CODEX_START_HERE.md"
        build_prompt = base / "CODEX_BUILD_PROMPT.md"
        if start_here.exists() or build_prompt.exists():
            checks.append(workspace_release_check("Codex prompt doc exists", "pass", "A Codex prompt document exists.", str(start_here if start_here.exists() else build_prompt)))
        else:
            checks.append(workspace_release_check("Codex prompt doc exists", "fail", "Missing CODEX_START_HERE.md and CODEX_BUILD_PROMPT.md.", str(base)))
            blockers.append("Missing CODEX_START_HERE.md and CODEX_BUILD_PROMPT.md.")

    warnings = dedupe_items(warnings)
    blockers = dedupe_items(blockers)
    release_status = workspace_release_status_from_state(warnings=warnings, blockers=blockers, partial=partial)
    share_ready = release_status in {"ready", "ready_with_warnings"}
    codex_ready = release_status != "blocked"
    next_tiny_action = (
        "Review RELEASE.md, zip the release pack, and send it to one tester."
        if share_ready
        else first_sentence(blockers[0]) if blockers else "Run Workspace Sync and Run & Verify, then rebuild the release pack."
    ) or "Review the release checklist."
    tester_message = (
        f"Please test this local release candidate for {project.get('title') or 'the app'} and tell me the first confusing or broken step in the main flow."
        if share_ready
        else "This release candidate is not ready for wider testing yet. Please review the blockers first."
    )
    simulated = []
    if release_type == "ai_tool_app":
        simulated.append("AI output stays mocked/offline by default unless a tester opts into local `.env` setup.")
    if release_type == "repo_brief":
        simulated.append("This pack may contain planning/reference docs instead of a runnable app.")
    if release_type == "static_site":
        simulated.append("Any feedback/export path is still local-only and manual.")
    follow_up_tasks = []
    if blockers:
        follow_up_tasks.extend(blockers[:3])
    elif warnings:
        follow_up_tasks.extend(warnings[:3])
    else:
        follow_up_tasks.append("Collect one round of tester feedback and apply one tiny follow-up fix.")

    created_at = now_iso()
    resolved_label = normalize_release_label(release_label, created_at)
    release_pack_id = str(uuid.uuid4())
    release_dir = workspace_release_folder_path(str(project.get("title") or "project"), resolved_label, created_at)
    app_dir = release_dir / "app"
    app_dir.mkdir(parents=True, exist_ok=True)
    files_copied = workspace_release_copy_app_files(base, app_dir)
    files_added = list(WORKSPACE_RELEASE_REPORT_FILES)
    files_generated = list(WORKSPACE_RELEASE_REPORT_FILES) + files_copied
    verification_commands = dedupe_items(
        list((verification_run or {}).get("metadata", {}).get("verification_commands") or [])
        + list((workspace_sync or {}).get("metadata", {}).get("verification_commands") or [])
        + [cmd for cmd in (run_command, test_command) if cmd]
    )
    payload = {
        "release_pack_id": release_pack_id,
        "project_id": project_id,
        "project_title": str(project.get("title") or "Sprint"),
        "workspace_id": resolved_workspace_id,
        "workspace_sync_id": str((workspace_sync or {}).get("workspace_sync_id") or "") or None,
        "verification_run_id": str((verification_run or {}).get("verification_run_id") or "") or None,
        "snapshot_id": str((snapshot or {}).get("snapshot_id") or "") or None,
        "created_at": created_at,
        "release_label": resolved_label,
        "release_status": release_status,
        "release_type": release_type,
        "path": str(release_dir),
        "app_path": str(app_dir),
        "files_copied": files_copied,
        "files_added": files_added,
        "files_generated": files_generated,
        "warnings": warnings,
        "blockers": blockers,
        "run_command": run_command,
        "test_command": test_command,
        "share_ready": share_ready,
        "codex_ready": codex_ready,
        "next_tiny_action": next_tiny_action,
        "tester_message": tester_message,
        "target_user": infer_target_user(project),
        "current_scope": build_feature_bullets(project),
        "what_this_app_does": first_sentence(str((project.get("sprint") or {}).get("one_sentence") or project.get("raw_idea") or "")),
        "simulated": simulated,
        "follow_up_tasks": follow_up_tasks,
        "workspace_sync": workspace_sync,
        "verification_run": verification_run,
        "snapshot": snapshot,
        "checks": checks,
        "files_likely_touched": files_likely_touched[:20],
        "verification_commands": verification_commands,
    }
    payload["command_center"] = build_project_command_summary(project, overrides={"latest_workspace_release_pack": payload})
    codex_next_prompt = workspace_release_next_prompt(project, payload)
    payload["codex_next_prompt_path"] = str(release_dir / "CODEX_NEXT_PROMPT.md")
    report_files = {
        "RELEASE.md": workspace_release_readme(project, payload),
        "RELEASE_NOTES.md": workspace_release_notes_markdown(project, payload),
        "RUN_AND_TEST.md": workspace_release_run_and_test_markdown(payload),
        "TESTER_INSTRUCTIONS.md": workspace_release_tester_instructions(project, payload),
        "DEPLOY_OR_SHARE.md": workspace_release_deploy_or_share(project, payload),
        "CHANGE_SUMMARY.md": workspace_release_change_summary_markdown(payload),
        "RELEASE_CHECKLIST.md": workspace_release_checklist_markdown(payload),
        "CODEX_NEXT_PROMPT.md": codex_next_prompt,
        "release-pack.json": workspace_release_release_pack_json(payload),
    }
    write_text_files(release_dir, report_files)
    metadata = {
        **payload,
        "codex_next_prompt_path": payload["codex_next_prompt_path"],
        "release_markdown_path": str(release_dir / "RELEASE.md"),
        "tester_instructions_path": str(release_dir / "TESTER_INSTRUCTIONS.md"),
        "deploy_or_share_path": str(release_dir / "DEPLOY_OR_SHARE.md"),
    }
    with db() as conn:
        conn.execute(
            """
            INSERT INTO workspace_release_packs (
                id, project_id, workspace_id, workspace_sync_id, verification_run_id, snapshot_id,
                created_at, release_label, release_status, release_type, path, metadata_json
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                release_pack_id,
                project_id,
                resolved_workspace_id,
                payload["workspace_sync_id"],
                payload["verification_run_id"],
                payload["snapshot_id"],
                created_at,
                resolved_label,
                release_status,
                release_type,
                str(release_dir),
                workspace_release_row_metadata_json(metadata),
            ),
        )
        conn.execute("UPDATE projects SET updated_at = ? WHERE id = ?", (created_at, project_id))
        conn.commit()
    stored = get_workspace_release_pack(release_pack_id)
    if stored is None:
        raise ValueError("Workspace Release Pack was not saved correctly")
    record_activity_event(
        project_id,
        "workspace_release_pack_created",
        "Workspace release pack created",
        f"Created release pack {resolved_label} with status {release_status}.",
        event_status=activity_status_from_release_status(release_status),
        actor="sprintos",
        related_type="workspace_release",
        related_id=release_pack_id,
        next_tiny_action=next_tiny_action,
        report_path=str(release_dir),
        metadata={"workspace_id": resolved_workspace_id, "release_type": release_type, "warnings": warnings[:3], "blockers": blockers[:3]},
    )
    return stored


def workspace_release_response(row: sqlite3.Row | Dict[str, Any]) -> Dict[str, Any]:
    data = dict(row)
    metadata = safe_json_loads(str(data.get("metadata_json") or "{}"), {}) or {}
    release_pack_id = str(data.get("id") or metadata.get("release_pack_id") or "")
    release_path = Path(str(data.get("path") or metadata.get("path") or ""))
    result = {
        "id": release_pack_id,
        "release_pack_id": release_pack_id,
        "project_id": str(data.get("project_id") or metadata.get("project_id") or ""),
        "workspace_id": str(data.get("workspace_id") or metadata.get("workspace_id") or ""),
        "workspace_sync_id": str(data.get("workspace_sync_id") or metadata.get("workspace_sync_id") or "") or None,
        "verification_run_id": str(data.get("verification_run_id") or metadata.get("verification_run_id") or "") or None,
        "snapshot_id": str(data.get("snapshot_id") or metadata.get("snapshot_id") or "") or None,
        "created_at": str(data.get("created_at") or metadata.get("created_at") or ""),
        "release_label": str(data.get("release_label") or metadata.get("release_label") or ""),
        "release_status": normalize_workspace_release_status(data.get("release_status") or metadata.get("release_status") or "partial"),
        "release_type": normalize_workspace_release_type(data.get("release_type") or metadata.get("release_type") or "repo_brief"),
        "path": str(release_path),
        "app_path": str(metadata.get("app_path") or release_path / "app"),
        "files_copied": list(metadata.get("files_copied") or []),
        "files_added": list(metadata.get("files_added") or []),
        "files_generated": list(metadata.get("files_generated") or list(WORKSPACE_RELEASE_REPORT_FILES)),
        "warnings": list(metadata.get("warnings") or []),
        "blockers": list(metadata.get("blockers") or []),
        "run_command": str(metadata.get("run_command") or ""),
        "test_command": str(metadata.get("test_command") or ""),
        "share_ready": bool(metadata.get("share_ready")),
        "codex_ready": bool(metadata.get("codex_ready")),
        "next_tiny_action": str(metadata.get("next_tiny_action") or ""),
        "tester_message": str(metadata.get("tester_message") or ""),
        "metadata": metadata,
        "zip_url": workspace_release_zip_url(release_pack_id),
        "report_url": workspace_release_report_url(release_pack_id, "RELEASE.md"),
        "release_url": workspace_release_report_url(release_pack_id, "RELEASE.md"),
        "tester_instructions_url": workspace_release_report_url(release_pack_id, "TESTER_INSTRUCTIONS.md"),
        "deploy_or_share_url": workspace_release_report_url(release_pack_id, "DEPLOY_OR_SHARE.md"),
        "codex_next_prompt_path": str(metadata.get("codex_next_prompt_path") or release_path / "CODEX_NEXT_PROMPT.md"),
    }
    for name, key in (
        ("RELEASE.md", "release_markdown"),
        ("TESTER_INSTRUCTIONS.md", "tester_instructions"),
        ("DEPLOY_OR_SHARE.md", "deploy_or_share"),
        ("CODEX_NEXT_PROMPT.md", "codex_next_prompt"),
    ):
        target = release_path / name
        result[key] = target.read_text(encoding="utf-8") if target.exists() else ""
    return result


def get_workspace_release_pack(release_pack_id: str) -> Optional[Dict[str, Any]]:
    with db() as conn:
        row = conn.execute("SELECT * FROM workspace_release_packs WHERE id = ?", (release_pack_id,)).fetchone()
    if not row:
        return None
    return workspace_release_response(row)


def latest_project_workspace_release_pack(project_id: str, workspace_id: Optional[str] = None) -> Optional[Dict[str, Any]]:
    with db() as conn:
        if workspace_id:
            row = conn.execute(
                "SELECT * FROM workspace_release_packs WHERE project_id = ? AND workspace_id = ? ORDER BY created_at DESC, rowid DESC LIMIT 1",
                (project_id, workspace_id),
            ).fetchone()
        else:
            row = conn.execute(
                "SELECT * FROM workspace_release_packs WHERE project_id = ? ORDER BY created_at DESC, rowid DESC LIMIT 1",
                (project_id,),
            ).fetchone()
    if not row:
        return None
    return workspace_release_response(row)


