def create_timestamped_export_dir(root: Path, project_title: str, created_at: str) -> Path:
    stamp = prototype_folder_timestamp(created_at)
    base_name = f"{slugify(project_title, 'project')}-{stamp}"
    candidate = root / base_name
    counter = 2
    while candidate.exists():
        candidate = root / f"{base_name}-{counter}"
        counter += 1
    candidate.mkdir(parents=True, exist_ok=True)
    return candidate


def local_backup_report_url(backup_id: str, filename: str = "backup-report.md") -> str:
    return f"/api/local_backup_file?id={urllib.parse.quote(backup_id)}&file={urllib.parse.quote(filename)}"


def local_backup_zip_url(backup_id: str) -> str:
    return f"/api/local_backup_zip?id={urllib.parse.quote(backup_id)}"


def local_restore_report_url(restore_id: str, filename: str = "restore-report.md") -> str:
    return f"/api/local_restore_file?id={urllib.parse.quote(restore_id)}&file={urllib.parse.quote(filename)}"


def normalize_backup_label(value: Any, created_at: str) -> str:
    label = " ".join(str(value or "").strip().split())
    safe = slugify(label, "")
    if safe:
        return safe[:64]
    return f"manual-{prototype_folder_timestamp(created_at)}"


def backup_manifest_relative_path(path: Path) -> str:
    return path.resolve().relative_to(sprintos_repo_root()).as_posix()


def local_backup_is_binary_path(relative_path: str) -> bool:
    path = Path(relative_path)
    suffix = path.suffix.lower()
    return suffix in LOCAL_BACKUP_BINARY_SUFFIXES


def local_backup_is_scannable_text_path(relative_path: str) -> bool:
    path = Path(relative_path)
    suffix = path.suffix.lower()
    if suffix in LOCAL_BACKUP_ALLOWED_SQLITE_SUFFIXES:
        return False
    return not local_backup_is_binary_path(relative_path)


def local_backup_should_exclude_relative_path(relative_path: str) -> bool:
    path = Path(relative_path)
    name = path.name
    if not relative_path:
        return True
    if name == ".DS_Store":
        return True
    if name.startswith(".env") and name != ".env.example":
        return True
    if any(part in {"__pycache__", ".pytest_cache", "node_modules", ".git", "backups"} for part in path.parts):
        return True
    if path.parts[:2] == ("exports", "local_backups"):
        return True
    if path.suffix.lower() == ".zip":
        return True
    if local_backup_is_binary_path(relative_path):
        return True
    if "authorization" in relative_path.lower():
        return True
    return False


def local_backup_should_include_root(root_name: str) -> bool:
    candidate = (sprintos_repo_root() / root_name).resolve()
    try:
        candidate.relative_to(sprintos_repo_root())
    except ValueError:
        return False
    return candidate.exists()


def local_backup_read_text_if_safe(path: Path) -> Tuple[Optional[str], Optional[str]]:
    try:
        return path.read_text(encoding="utf-8"), None
    except UnicodeDecodeError:
        return None, "non_utf8"
    except OSError:
        return None, "read_error"


def local_backup_text_secret_matches(text: str) -> List[str]:
    matches: List[str] = []
    for pattern in LOCAL_BACKUP_TEXT_SCAN_PATTERNS:
        found = pattern.search(text)
        if found:
            matches.append(found.group(0)[:120])
    return matches


def local_backup_secret_scan_entry(relative_path: str, text: Optional[str]) -> Dict[str, Any]:
    findings = local_backup_text_secret_matches(text or "")
    return {
        "path": relative_path,
        "scanned": bool(text is not None),
        "flagged": bool(findings),
        "findings": findings[:5],
    }


def local_backup_source_paths() -> Tuple[List[Path], List[str], Dict[str, Any]]:
    files: List[Path] = []
    warnings: List[str] = []
    secret_scan_entries: List[Dict[str, Any]] = []
    resolved_base = sprintos_repo_root()
    seen: set[str] = set()
    for root_name in LOCAL_BACKUP_INCLUDED_ROOTS:
        if not local_backup_should_include_root(root_name):
            continue
        root_path = (resolved_base / root_name).resolve()
        candidates = [root_path] if root_path.is_file() else sorted(root_path.rglob("*"))
        for path in candidates:
            if not path.exists() or path.is_symlink() or path.is_dir():
                continue
            try:
                resolved = path.resolve()
                relative_path = resolved.relative_to(resolved_base).as_posix()
            except ValueError:
                warnings.append(f"Skipped unsafe path outside repo root: {path}")
                continue
            if relative_path in seen or local_backup_should_exclude_relative_path(relative_path):
                continue
            text, read_error = (None, None)
            if local_backup_is_scannable_text_path(relative_path):
                text, read_error = local_backup_read_text_if_safe(resolved)
                if read_error == "read_error":
                    warnings.append(f"Skipped unreadable file: {relative_path}")
                    continue
                if text is not None:
                    entry = local_backup_secret_scan_entry(relative_path, text)
                    secret_scan_entries.append(entry)
                    if entry["flagged"]:
                        warnings.append(f"Excluded possible secret file: {relative_path}")
                        continue
                elif read_error == "non_utf8":
                    warnings.append(f"Skipped non-UTF-8 file: {relative_path}")
                    continue
            files.append(resolved)
            seen.add(relative_path)
    summary = {
        "scanned_files": len(secret_scan_entries),
        "flagged_files": len([item for item in secret_scan_entries if item.get("flagged")]),
        "entries": secret_scan_entries[:200],
    }
    return sorted(files), warnings, summary


def local_backup_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(65536), b""):
            digest.update(chunk)
    return digest.hexdigest()


def local_backup_manifest_entries(files: List[Path]) -> List[Dict[str, Any]]:
    entries: List[Dict[str, Any]] = []
    for path in files:
        relative_path = backup_manifest_relative_path(path)
        stat = path.stat()
        entries.append(
            {
                "path": relative_path,
                "size": int(stat.st_size),
                "modified_time": _dt.datetime.fromtimestamp(stat.st_mtime).replace(microsecond=0).isoformat(),
                "sha256": local_backup_sha256(path),
            }
        )
    return entries


def local_backup_report_markdown(manifest: Dict[str, Any]) -> str:
    warnings = list(manifest.get("warnings") or [])
    lines = [
        f"# Local Backup Report — {manifest.get('backup_label') or ''}",
        "",
        "## Backup Label",
        str(manifest.get("backup_label") or ""),
        "",
        "## Backup Path",
        str(manifest.get("backup_path") or ""),
        "",
        "## Created Time",
        str(manifest.get("created_at") or ""),
        "",
        "## Included Roots",
        ", ".join(str(item) for item in (manifest.get("included_roots") or [])) or "none",
        "",
        "## Excluded Patterns",
        ", ".join(str(item) for item in (manifest.get("excluded_patterns") or [])) or "none",
        "",
        "## File Count",
        str(manifest.get("total_files") or 0),
        "",
        "## Total Size",
        str(manifest.get("total_size_bytes") or 0),
        "",
        "## Warnings",
    ]
    lines.extend([f"- {item}" for item in warnings] or ["- none"])
    lines.extend(
        [
            "",
            "## Restore Instructions",
            f"Use `/api/restore_local_backup` with backup ID `{manifest.get('backup_id') or ''}`. Dry run is the default.",
            "",
            "## Safety Note",
            "- `.env` and API keys are excluded.",
            "- Backup is local only.",
            "- Review the backup contents before sharing it.",
            "",
        ]
    )
    return "\n".join(lines)


def local_backup_restore_instructions() -> str:
    return textwrap.dedent(
        """\
        # Local Backup Restore Instructions

        ## What restore does
        SprintOS reads the backup manifest, validates the ZIP, and restores safe files back into the local SprintOS repo root.

        ## What restore does not do
        - It does not restore `.env` or `.env*` files.
        - It does not restore `.git` internals.
        - It does not run commands.
        - It does not call external APIs.

        ## Important safety rules
        - Restore defaults to dry run.
        - Real restore requires explicit confirmation through SprintOS.
        - `.env` must be recreated manually if needed.
        - Only restore from a backup you trust and have reviewed locally.
        """
    ).strip() + "\n"


def local_backup_metadata_json(metadata: Dict[str, Any]) -> str:
    sanitized = json.loads(json.dumps(metadata or {}))
    return json.dumps(sanitized, sort_keys=True)


def local_backup_response(row: sqlite3.Row | Dict[str, Any]) -> Dict[str, Any]:
    data = dict(row)
    metadata = safe_json_loads(str(data.get("metadata_json") or "{}"), {}) or {}
    backup_id = str(data.get("id") or metadata.get("backup_id") or "")
    backup_path = Path(str(data.get("backup_path") or metadata.get("backup_path") or ""))
    manifest_path = Path(str(data.get("manifest_path") or metadata.get("manifest_path") or ""))
    report_path = Path(str(metadata.get("report_path") or manifest_path.parent))
    return {
        "id": backup_id,
        "backup_id": backup_id,
        "created_at": str(data.get("created_at") or metadata.get("created_at") or ""),
        "backup_label": str(data.get("backup_label") or metadata.get("backup_label") or ""),
        "backup_status": normalize_local_backup_status(data.get("backup_status") or metadata.get("backup_status") or "created"),
        "backup_path": str(backup_path),
        "manifest_path": str(manifest_path),
        "report_path": str(report_path),
        "total_files": int(data.get("total_files") or metadata.get("total_files") or 0),
        "total_size_bytes": int(data.get("total_size_bytes") or metadata.get("total_size_bytes") or 0),
        "warnings": list(metadata.get("warnings") or []),
        "blockers": list(metadata.get("blockers") or []),
        "verified": bool(metadata.get("verified")),
        "manifest": metadata.get("manifest") if isinstance(metadata.get("manifest"), dict) else {},
        "secret_scan_summary": metadata.get("secret_scan_summary") if isinstance(metadata.get("secret_scan_summary"), dict) else {},
        "metadata": metadata,
        "report_url": local_backup_report_url(backup_id),
        "manifest_url": local_backup_report_url(backup_id, "backup-manifest.json"),
        "instructions_url": local_backup_report_url(backup_id, "restore-instructions.md"),
        "zip_url": local_backup_zip_url(backup_id),
    }


def get_local_backup(backup_id: str) -> Optional[Dict[str, Any]]:
    with db() as conn:
        row = conn.execute("SELECT * FROM local_backups WHERE id = ?", (backup_id,)).fetchone()
    if not row:
        return None
    return local_backup_response(row)


def list_local_backups(limit: int = 20) -> List[Dict[str, Any]]:
    try:
        max_items = max(1, min(int(limit), 100))
    except (TypeError, ValueError):
        max_items = 20
    with db() as conn:
        rows = conn.execute("SELECT * FROM local_backups ORDER BY created_at DESC, rowid DESC LIMIT ?", (max_items,)).fetchall()
    return [local_backup_response(row) for row in rows]


def latest_local_backup() -> Optional[Dict[str, Any]]:
    items = list_local_backups(limit=1)
    return items[0] if items else None


def local_backup_file_path(backup: Dict[str, Any], filename: str) -> Path:
    return safe_flat_file_path(
        Path(str(backup.get("report_path") or "")),
        filename,
        LOCAL_BACKUP_REPORT_FILES,
        "Invalid local backup file",
    )


def update_local_backup_metadata(backup_id: str, metadata: Dict[str, Any], *, backup_status: Optional[str] = None) -> Dict[str, Any]:
    backup = get_local_backup(backup_id)
    if not backup:
        raise ValueError("Local backup not found")
    next_status = normalize_local_backup_status(backup_status or backup.get("backup_status") or "created")
    with db() as conn:
        conn.execute(
            "UPDATE local_backups SET backup_status = ?, metadata_json = ? WHERE id = ?",
            (next_status, local_backup_metadata_json(metadata), backup_id),
        )
        conn.commit()
    stored = get_local_backup(backup_id)
    if stored is None:
        raise ValueError("Local backup metadata was not saved correctly")
    return stored


def persist_local_backup_record(backup: Dict[str, Any]) -> None:
    metadata = dict(backup.get("metadata") or {})
    with db() as conn:
        conn.execute(
            """
            INSERT OR REPLACE INTO local_backups (
                id, created_at, backup_label, backup_status, backup_path, manifest_path, total_files, total_size_bytes, metadata_json
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                str(backup.get("backup_id") or backup.get("id") or ""),
                str(backup.get("created_at") or ""),
                str(backup.get("backup_label") or ""),
                normalize_local_backup_status(backup.get("backup_status") or metadata.get("backup_status") or "created"),
                str(backup.get("backup_path") or ""),
                str(backup.get("manifest_path") or ""),
                int(backup.get("total_files") or 0),
                int(backup.get("total_size_bytes") or 0),
                local_backup_metadata_json(metadata),
            ),
        )
        conn.commit()


