def create_local_backup(*, backup_label: str = "") -> Dict[str, Any]:
    ensure_dirs()
    created_at = now_iso()
    backup_id = str(uuid.uuid4())
    safe_label = normalize_backup_label(backup_label, created_at)
    stamp = prototype_folder_timestamp(created_at)
    report_dir = local_backup_export_dir() / f"{stamp}-{safe_label}"
    counter = 2
    while report_dir.exists():
        report_dir = local_backup_export_dir() / f"{stamp}-{safe_label}-{counter}"
        counter += 1
    report_dir.mkdir(parents=True, exist_ok=True)
    backup_path = local_backup_dir() / f"sprintos-backup-{stamp}-{safe_label}.zip"
    files, warnings, secret_scan_summary = local_backup_source_paths()
    manifest_entries = local_backup_manifest_entries(files)
    manifest = {
        "backup_id": backup_id,
        "created_at": created_at,
        "backup_label": safe_label,
        "backup_path": str(backup_path),
        "included_roots": [item for item in LOCAL_BACKUP_INCLUDED_ROOTS if local_backup_should_include_root(item)],
        "excluded_patterns": list(LOCAL_BACKUP_EXCLUDED_PATTERNS),
        "required_paths_if_present": [backup_manifest_relative_path(DB_PATH)] if DB_PATH.exists() else [],
        "total_files": len(manifest_entries),
        "total_size_bytes": sum(int(item.get("size") or 0) for item in manifest_entries),
        "files": manifest_entries,
        "warnings": warnings,
        "secret_scan_summary": secret_scan_summary,
    }
    with zipfile.ZipFile(backup_path, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        for source in files:
            zf.write(source, arcname=backup_manifest_relative_path(source))
    report_files = {
        "backup-manifest.json": json.dumps(manifest, indent=2) + "\n",
        "backup-report.md": local_backup_report_markdown(manifest),
        "restore-instructions.md": local_backup_restore_instructions(),
    }
    write_text_files(report_dir, report_files)
    metadata = {
        "backup_id": backup_id,
        "created_at": created_at,
        "backup_label": safe_label,
        "backup_status": "created",
        "backup_path": str(backup_path),
        "manifest_path": str(report_dir / "backup-manifest.json"),
        "report_path": str(report_dir),
        "total_files": manifest["total_files"],
        "total_size_bytes": manifest["total_size_bytes"],
        "warnings": warnings,
        "blockers": [],
        "verified": False,
        "manifest": manifest,
        "secret_scan_summary": secret_scan_summary,
    }
    with db() as conn:
        conn.execute(
            """
            INSERT INTO local_backups (
                id, created_at, backup_label, backup_status, backup_path, manifest_path, total_files, total_size_bytes, metadata_json
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                backup_id,
                created_at,
                safe_label,
                "created",
                str(backup_path),
                str(report_dir / "backup-manifest.json"),
                manifest["total_files"],
                manifest["total_size_bytes"],
                local_backup_metadata_json(metadata),
            ),
        )
        conn.commit()
    record_activity_event(
        None,
        "local_backup_created",
        "Local backup created",
        f"Created local backup {safe_label} with {manifest['total_files']} files.",
        event_status="success",
        actor="sprintos",
        related_type=None,
        related_id=backup_id,
        next_tiny_action="Verify the backup before relying on it.",
        report_path=str(report_dir),
        metadata={"backup_id": backup_id, "total_files": manifest["total_files"], "total_size_bytes": manifest["total_size_bytes"]},
    )
    stored = get_local_backup(backup_id)
    if stored is None:
        raise ValueError("Local backup was not saved correctly")
    return stored


def verify_local_backup(backup_id: str) -> Dict[str, Any]:
    backup = get_local_backup(backup_id)
    if not backup:
        raise ValueError("Local backup not found")
    blockers: List[str] = []
    warnings = list(backup.get("warnings") or [])
    manifest_path = Path(str(backup.get("manifest_path") or ""))
    backup_path = Path(str(backup.get("backup_path") or ""))
    if not backup_path.exists() or not backup_path.is_file():
        blockers.append("Backup ZIP is missing.")
    if not manifest_path.exists() or not manifest_path.is_file():
        blockers.append("Backup manifest is missing.")
    manifest = None
    zip_names: set[str] = set()
    if not blockers:
        try:
            manifest = safe_json_loads(manifest_path.read_text(encoding="utf-8"), None)
        except OSError:
            blockers.append("Backup manifest could not be read.")
        if not isinstance(manifest, dict):
            blockers.append("Backup manifest is malformed.")
    if not blockers:
        try:
            with zipfile.ZipFile(backup_path, "r") as zf:
                zip_names = {Path(info.filename).as_posix() for info in zf.infolist() if not info.is_dir()}
                for name in sorted(zip_names):
                    zip_path = Path(name)
                    if zip_path.is_absolute() or ".." in zip_path.parts:
                        blockers.append(f"Unsafe path found in ZIP: {name}")
                    if Path(name).name.startswith(".env") and Path(name).name != ".env.example":
                        blockers.append(f"Forbidden env file found in ZIP: {name}")
                    if any(part == ".git" for part in Path(name).parts):
                        blockers.append(f"Forbidden git path found in ZIP: {name}")
                for name in sorted(zip_names):
                    if not local_backup_is_scannable_text_path(name):
                        continue
                    try:
                        text = zf.read(name).decode("utf-8")
                    except UnicodeDecodeError:
                        warnings.append(f"Skipped UTF-8 verification for file: {name}")
                        continue
                    findings = local_backup_text_secret_matches(text)
                    if findings:
                        blockers.append(f"Possible secret found in ZIP text file: {name}")
        except zipfile.BadZipFile:
            blockers.append("Backup ZIP is malformed.")
    if isinstance(manifest, dict):
        manifest_paths = {str(item.get("path") or "") for item in (manifest.get("files") or []) if str(item.get("path") or "").strip()}
        if manifest_paths != zip_names:
            blockers.append("ZIP contents do not match manifest paths.")
        for required_path in manifest.get("required_paths_if_present") or []:
            if required_path and required_path not in zip_names:
                blockers.append(f"Required backup path is missing: {required_path}")
    verified = not blockers
    metadata = dict(backup.get("metadata") or {})
    metadata["warnings"] = dedupe_items(warnings)
    metadata["blockers"] = dedupe_items(blockers)
    metadata["verified"] = verified
    metadata["verified_at"] = now_iso()
    stored = update_local_backup_metadata(backup_id, metadata, backup_status="verified" if verified else "failed")
    record_activity_event(
        None,
        "local_backup_verified" if verified else "local_backup_failed",
        "Local backup verified" if verified else "Local backup verification failed",
        ("Verified local backup " if verified else "Local backup verification failed for ") + f"{stored.get('backup_label') or backup_id}.",
        event_status="success" if verified else "failed",
        actor="sprintos",
        next_tiny_action="Restore dry run is safe to test next." if verified else "Inspect the backup report and create a new backup.",
        report_path=str(stored.get("report_path") or ""),
        metadata={"backup_id": backup_id, "warnings": warnings, "blockers": blockers},
    )
    return {"backup_id": backup_id, "verified": verified, "warnings": dedupe_items(warnings), "blockers": dedupe_items(blockers), "backup": stored}


def local_restore_report_markdown(payload: Dict[str, Any]) -> str:
    lines = [
        f"# Local Restore Report — {payload.get('backup_label') or payload.get('backup_id') or ''}",
        "",
        "## Restore Status",
        str(payload.get("restore_status") or ""),
        "",
        "## Restore Path",
        str(payload.get("restore_path") or ""),
        "",
        "## Files Restored",
        str(payload.get("files_restored") or 0),
        "",
        "## Target Paths",
    ]
    lines.extend([f"- {item}" for item in (payload.get("target_paths") or [])] or ["- none"])
    lines.extend(["", "## Warnings"])
    lines.extend([f"- {item}" for item in (payload.get("warnings") or [])] or ["- none"])
    lines.extend(["", "## Blockers"])
    lines.extend([f"- {item}" for item in (payload.get("blockers") or [])] or ["- none"])
    lines.extend(["", "## Next Tiny Action", str(payload.get("next_tiny_action") or ""), ""])
    return "\n".join(lines)


def local_restore_report_files(payload: Dict[str, Any]) -> Dict[str, str]:
    return {
        "restore-report.md": local_restore_report_markdown(payload),
        "restore-result.json": json.dumps(payload, indent=2) + "\n",
        "post-restore-next-action.md": str(payload.get("next_tiny_action") or "") + "\n",
    }


def restore_local_backup(backup_id: str, *, dry_run: bool = True, confirm_restore: bool = False) -> Dict[str, Any]:
    backup = get_local_backup(backup_id)
    if not backup:
        raise ValueError("Local backup not found")
    if not dry_run and not confirm_restore:
        raise ValueError("confirm_restore=true is required for a real restore")
    verify_payload = verify_local_backup(backup_id)
    blockers = list(verify_payload.get("blockers") or [])
    warnings = list(verify_payload.get("warnings") or [])
    manifest = (get_local_backup(backup_id) or backup).get("manifest") or {}
    manifest_files = list(manifest.get("files") or [])
    target_paths = [str(item.get("path") or "") for item in manifest_files if str(item.get("path") or "").strip()]
    restore_id = str(uuid.uuid4())
    created_at = now_iso()
    safe_label = normalize_backup_label((backup.get("backup_label") or ""), created_at)
    report_dir = local_restore_export_dir() / f"{prototype_folder_timestamp(created_at)}-{safe_label}"
    counter = 2
    while report_dir.exists():
        report_dir = local_restore_export_dir() / f"{prototype_folder_timestamp(created_at)}-{safe_label}-{counter}"
        counter += 1
    report_dir.mkdir(parents=True, exist_ok=True)
    files_restored = 0
    pre_restore_backup_id = ""
    pre_restore_backup: Optional[Dict[str, Any]] = None
    if not dry_run and not blockers:
        pre_restore_backup = create_local_backup(backup_label=f"pre-restore-{safe_label}")
        pre_restore_backup_id = str(pre_restore_backup.get("backup_id") or "")
        backup_zip_path = Path(str(backup.get("backup_path") or "")).resolve()
        with zipfile.ZipFile(backup_zip_path, "r") as zf:
            for item in manifest_files:
                relative_path = str(item.get("path") or "")
                if not relative_path:
                    continue
                rel = Path(relative_path)
                if rel.is_absolute() or ".." in rel.parts:
                    raise ValueError("Local restore blocked an unsafe path from the backup manifest")
                if rel.name.startswith(".env") or any(part == ".git" for part in rel.parts):
                    warnings.append(f"Skipped forbidden restore path: {relative_path}")
                    continue
                if rel.parts[0] not in LOCAL_BACKUP_RESTORE_ROOTS and relative_path not in LOCAL_BACKUP_TOP_LEVEL_FILE_RESTORES:
                    warnings.append(f"Skipped non-managed restore path: {relative_path}")
                    continue
                target = (sprintos_repo_root() / relative_path).resolve()
                try:
                    target.relative_to(sprintos_repo_root())
                except ValueError as exc:
                    blockers.append(f"Skipped unsafe restore path: {relative_path}")
                    raise ValueError("Local restore path escaped the SprintOS repo root") from exc
                target.parent.mkdir(parents=True, exist_ok=True)
                with zf.open(relative_path, "r") as source, target.open("wb") as handle:
                    shutil.copyfileobj(source, handle)
                files_restored += 1
        persist_local_backup_record(backup)
        if pre_restore_backup:
            persist_local_backup_record(pre_restore_backup)
    restore_status = "dry_run" if dry_run else ("completed" if not blockers and not warnings else "completed_with_warnings")
    if blockers:
        restore_status = "failed" if not dry_run else "dry_run"
    payload = {
        "restore_id": restore_id,
        "backup_id": backup_id,
        "backup_label": str(backup.get("backup_label") or ""),
        "created_at": created_at,
        "restore_status": restore_status,
        "restore_path": str(sprintos_repo_root()),
        "report_path": str(report_dir),
        "target_paths": target_paths[:200],
        "files_restored": files_restored,
        "warnings": dedupe_items(warnings),
        "blockers": dedupe_items(blockers),
        "dry_run": bool(dry_run),
        "pre_restore_backup_id": pre_restore_backup_id,
        "next_tiny_action": "Review the restore report. If this was a dry run and blockers are empty, run the confirmed restore only when you are ready.",
    }
    write_text_files(report_dir, local_restore_report_files(payload))
    metadata = dict(payload)
    with db() as conn:
        conn.execute(
            """
            INSERT INTO local_restores (
                id, backup_id, created_at, restore_status, restore_path, report_path, files_restored, metadata_json
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                restore_id,
                backup_id,
                created_at,
                restore_status,
                str(sprintos_repo_root()),
                str(report_dir),
                files_restored,
                local_backup_metadata_json(metadata),
            ),
        )
        conn.commit()
    if not dry_run and not blockers:
        backup_metadata = dict((get_local_backup(backup_id) or backup).get("metadata") or {})
        restores = list(backup_metadata.get("restores") or [])
        restores.append({"restore_id": restore_id, "created_at": created_at, "restore_status": restore_status, "files_restored": files_restored})
        backup_metadata["restores"] = restores[-5:]
        update_local_backup_metadata(backup_id, backup_metadata, backup_status="restored")
    event_type = "local_backup_restore_dry_run" if dry_run else ("local_backup_restored" if not blockers else "local_backup_failed")
    event_title = "Local backup restore dry run" if dry_run else ("Local backup restored" if not blockers else "Local backup restore failed")
    record_activity_event(
        None,
        event_type,
        event_title,
        f"{event_title} for backup {backup.get('backup_label') or backup_id}.",
        event_status="info" if dry_run else ("success" if not blockers else "failed"),
        actor="sprintos",
        next_tiny_action=payload["next_tiny_action"],
        report_path=str(report_dir),
        metadata={"backup_id": backup_id, "restore_id": restore_id, "files_restored": files_restored, "dry_run": dry_run},
    )
    stored = get_local_restore(restore_id)
    if stored is None:
        raise ValueError("Local restore was not saved correctly")
    return stored


def workspace_snapshot_report_url(snapshot_id: str, filename: str = "snapshot-report.md") -> str:
    return f"/api/workspace_snapshot_file?id={urllib.parse.quote(snapshot_id)}&file={urllib.parse.quote(filename)}"


def workspace_snapshot_zip_url(snapshot_id: str) -> str:
    return f"/api/workspace_snapshot_zip?id={urllib.parse.quote(snapshot_id)}"


def workspace_restore_report_url(restore_id: str, filename: str = "restore-report.md") -> str:
    return f"/api/workspace_restore_report?id={urllib.parse.quote(restore_id)}&file={urllib.parse.quote(filename)}"


def workspace_snapshot_should_exclude_relative_path(relative_path: str) -> bool:
    path = Path(relative_path)
    name = path.name
    if not relative_path:
        return True
    if name == ".DS_Store" or name.startswith(".env"):
        return True
    if name in set(WORKSPACE_SNAPSHOT_REPORT_FILES):
        return True
    if any(part in {"__pycache__", ".git", "node_modules"} for part in path.parts):
        return True
    if path.suffix.lower() in WORKSPACE_SNAPSHOT_BINARY_SUFFIXES:
        return True
    return False


def workspace_snapshot_file_paths(base: Path) -> List[Path]:
    resolved_base = base.resolve()
    files: List[Path] = []
    for path in sorted(resolved_base.rglob("*")):
        if not path.is_file() or path.is_symlink():
            continue
        try:
            resolved = path.resolve()
            relative_path = resolved.relative_to(resolved_base).as_posix()
        except ValueError:
            continue
        if workspace_snapshot_should_exclude_relative_path(relative_path):
            continue
        files.append(resolved)
    return files


def workspace_snapshot_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(65536), b""):
            digest.update(chunk)
    return digest.hexdigest()


def workspace_snapshot_manifest_entries(base: Path, files: List[Path]) -> List[Dict[str, Any]]:
    entries: List[Dict[str, Any]] = []
    for path in files:
        relative_path = path.relative_to(base).as_posix()
        stat = path.stat()
        entries.append(
            {
                "path": relative_path,
                "size": int(stat.st_size),
                "modified_time": _dt.datetime.fromtimestamp(stat.st_mtime).replace(microsecond=0).isoformat(),
                "sha256": workspace_snapshot_sha256(path),
            }
        )
    return entries


def workspace_snapshot_summary_text(summary: Optional[Dict[str, Any]]) -> str:
    if not isinstance(summary, dict):
        return "No comparison has been recorded yet."
    return (
        f"Added: {int(summary.get('added_count') or 0)} · "
        f"Modified: {int(summary.get('modified_count') or 0)} · "
        f"Removed: {int(summary.get('removed_count') or 0)} · "
        f"Unchanged: {int(summary.get('unchanged_count') or 0)}"
    )


def redact_obvious_secret_text(value: str) -> str:
    return OBVIOUS_SECRET_PATTERN.sub("[redacted]", str(value or ""))


def workspace_snapshot_row_metadata_json(metadata: Dict[str, Any]) -> str:
    sanitized = json.loads(json.dumps(metadata or {}))
    return json.dumps(sanitized)


def workspace_snapshot_restore_instructions(project_title: str, snapshot: Dict[str, Any]) -> str:
    return textwrap.dedent(
        f"""\
        # Restore Instructions — {project_title}

        ## What restore does
        SprintOS copies the snapshot files back into the workspace path and removes restore-managed workspace files that are not present in the snapshot manifest.

        ## Important safety rules
        - Restore replaces files inside the workspace path.
        - Restore preserves the workspace root folder.
        - `.env` is not restored from the snapshot.
        - Existing `.env` files in the workspace are preserved.
        - `.git` internals are not restored.
        - SprintOS does not push, deploy, or run commands during restore.

        ## Restore in SprintOS
        1. Open the project in SprintOS.
        2. Use the latest Workspace Snapshot panel or the restore API with this snapshot ID: `{snapshot.get('snapshot_id') or snapshot.get('id') or ''}`.
        3. After restore, run Workspace Sync.
        4. Run Run & Verify before handing the workspace back to Codex.
        """
    ).strip() + "\n"


def workspace_snapshot_report_markdown(project: Dict[str, Any], snapshot: Dict[str, Any]) -> str:
    excluded = ", ".join(WORKSPACE_SNAPSHOT_EXCLUDED_PATTERNS)
    warnings = snapshot.get("warnings") or []
    lines = [
        f"# Workspace Snapshot — {project.get('title') or 'Sprint'}",
        "",
        "## Project Title",
        str(project.get("title") or ""),
        "",
        "## Workspace Path",
        redact_obvious_secret_text(str(snapshot.get("source_workspace_path") or "")),
        "",
        "## Snapshot Path",
        redact_obvious_secret_text(str(snapshot.get("snapshot_path") or "")),
        "",
        "## Label",
        str(snapshot.get("snapshot_label") or ""),
        "",
        "## File Count",
        str(snapshot.get("files_count") or 0),
        "",
        "## Excluded Items Summary",
        excluded,
        "",
        "## How To Restore Through SprintOS",
        f"Use `/api/restore_workspace_snapshot` with snapshot ID `{snapshot.get('snapshot_id') or snapshot.get('id') or ''}`.",
        "",
        "## Safety Note",
        ".env and secrets are not copied into snapshots.",
    ]
    if warnings:
        lines.extend(["", "## Warnings"])
        lines.extend(f"- {redact_obvious_secret_text(item)}" for item in warnings)
    lines.append("")
    return "\n".join(lines)


def workspace_snapshot_file_names(manifest_entries: List[Dict[str, Any]]) -> List[str]:
    names = [str(item.get("path") or "") for item in manifest_entries if str(item.get("path") or "").strip()]
    for name in WORKSPACE_SNAPSHOT_REPORT_FILES:
        names.append(name)
    return names


def workspace_snapshot_response(row: sqlite3.Row | Dict[str, Any]) -> Dict[str, Any]:
    data = dict(row)
    metadata = safe_json_loads(str(data.get("metadata_json") or "{}"), {}) or {}
    snapshot_id = str(data.get("id") or metadata.get("snapshot_id") or "")
    snapshot_path = Path(str(data.get("snapshot_path") or metadata.get("snapshot_path") or ""))
    manifest = metadata.get("manifest") if isinstance(metadata.get("manifest"), dict) else {}
    files_generated = list(metadata.get("files_generated") or workspace_snapshot_file_names(list(manifest.get("files") or [])))
    latest_comparison = metadata.get("latest_comparison") if isinstance(metadata.get("latest_comparison"), dict) else None
    return {
        "id": snapshot_id,
        "snapshot_id": snapshot_id,
        "project_id": str(data.get("project_id") or metadata.get("project_id") or ""),
        "workspace_id": str(data.get("workspace_id") or metadata.get("workspace_id") or ""),
        "created_at": str(data.get("created_at") or metadata.get("created_at") or ""),
        "snapshot_label": str(data.get("snapshot_label") or metadata.get("snapshot_label") or ""),
        "snapshot_status": normalize_workspace_snapshot_status(data.get("snapshot_status") or metadata.get("snapshot_status") or "created"),
        "source_workspace_path": str(data.get("source_workspace_path") or metadata.get("source_workspace_path") or ""),
        "snapshot_path": str(snapshot_path),
        "files_count": int(data.get("files_count") or metadata.get("files_count") or 0),
        "manifest": manifest,
        "metadata": metadata,
        "files_generated": files_generated,
        "warnings": list(metadata.get("warnings") or []),
        "report_url": workspace_snapshot_report_url(snapshot_id),
        "zip_url": workspace_snapshot_zip_url(snapshot_id),
        "latest_comparison": latest_comparison,
    }


def get_workspace_snapshot(snapshot_id: str) -> Optional[Dict[str, Any]]:
    with db() as conn:
        row = conn.execute("SELECT * FROM workspace_snapshots WHERE id = ?", (snapshot_id,)).fetchone()
    if not row:
        return None
    return workspace_snapshot_response(row)


def latest_project_workspace_snapshot(project_id: str, workspace_id: Optional[str] = None) -> Optional[Dict[str, Any]]:
    with db() as conn:
        if workspace_id:
            row = conn.execute(
                "SELECT * FROM workspace_snapshots WHERE project_id = ? AND workspace_id = ? ORDER BY created_at DESC, rowid DESC LIMIT 1",
                (project_id, workspace_id),
            ).fetchone()
        else:
            row = conn.execute(
                "SELECT * FROM workspace_snapshots WHERE project_id = ? ORDER BY created_at DESC, rowid DESC LIMIT 1",
                (project_id,),
            ).fetchone()
    if not row:
        return None
    return workspace_snapshot_response(row)


def workspace_snapshot_file_path(snapshot: Dict[str, Any], filename: str) -> Path:
    return safe_flat_file_path(
        Path(str(snapshot.get("snapshot_path") or "")),
        filename,
        WORKSPACE_SNAPSHOT_REPORT_FILES,
        "Invalid workspace snapshot file",
    )


def build_workspace_snapshot_zip(snapshot: Dict[str, Any]) -> Tuple[str, bytes]:
    filename = sanitize_filename(
        f"{slugify(str((snapshot.get('metadata') or {}).get('project_title') or 'workspace-snapshot'), 'workspace-snapshot')}-{prototype_folder_timestamp(str(snapshot.get('created_at') or now_iso()))}.zip",
        default_stem="workspace-snapshot",
        default_suffix=".zip",
    )
    payload = build_zip_from_reader(
        snapshot.get("files_generated") or [],
        lambda name: safe_relative_file_path(
            Path(str(snapshot.get("snapshot_path") or "")),
            name,
            snapshot.get("files_generated") or [],
            "Invalid workspace snapshot file",
        ).read_text(encoding="utf-8"),
    )
    return filename, payload


def workspace_restore_response(row: sqlite3.Row | Dict[str, Any]) -> Dict[str, Any]:
    data = dict(row)
    metadata = safe_json_loads(str(data.get("metadata_json") or "{}"), {}) or {}
    restore_id = str(data.get("id") or metadata.get("restore_id") or "")
    report_path = Path(str(data.get("report_path") or metadata.get("report_path") or ""))
    return {
        "id": restore_id,
        "restore_id": restore_id,
        "snapshot_id": str(data.get("snapshot_id") or metadata.get("snapshot_id") or ""),
        "project_id": str(data.get("project_id") or metadata.get("project_id") or ""),
        "workspace_id": str(data.get("workspace_id") or metadata.get("workspace_id") or ""),
        "created_at": str(data.get("created_at") or metadata.get("created_at") or ""),
        "restore_status": str(data.get("restore_status") or metadata.get("restore_status") or ""),
        "report_path": str(report_path),
        "report_url": workspace_restore_report_url(restore_id),
        "files_restored": int(data.get("files_restored") or metadata.get("files_restored") or 0),
        "warnings": list(metadata.get("warnings") or []),
        "blockers": list(metadata.get("blockers") or []),
        "next_tiny_action": str(metadata.get("next_tiny_action") or ""),
        "metadata": metadata,
    }


def get_workspace_restore(restore_id: str) -> Optional[Dict[str, Any]]:
    with db() as conn:
        row = conn.execute("SELECT * FROM workspace_restores WHERE id = ?", (restore_id,)).fetchone()
    if not row:
        return None
    return workspace_restore_response(row)


def latest_project_workspace_restore(project_id: str, workspace_id: Optional[str] = None) -> Optional[Dict[str, Any]]:
    with db() as conn:
        if workspace_id:
            row = conn.execute(
                "SELECT * FROM workspace_restores WHERE project_id = ? AND workspace_id = ? ORDER BY created_at DESC, rowid DESC LIMIT 1",
                (project_id, workspace_id),
            ).fetchone()
        else:
            row = conn.execute(
                "SELECT * FROM workspace_restores WHERE project_id = ? ORDER BY created_at DESC, rowid DESC LIMIT 1",
                (project_id,),
            ).fetchone()
    if not row:
        return None
    return workspace_restore_response(row)


def latest_snapshot_restore(snapshot_id: str) -> Optional[Dict[str, Any]]:
    with db() as conn:
        row = conn.execute(
            "SELECT * FROM workspace_restores WHERE snapshot_id = ? ORDER BY created_at DESC, rowid DESC LIMIT 1",
            (snapshot_id,),
        ).fetchone()
    if not row:
        return None
    return workspace_restore_response(row)


def workspace_restore_file_path(restore: Dict[str, Any], filename: str) -> Path:
    return safe_flat_file_path(
        Path(str(restore.get("report_path") or "")),
        filename,
        WORKSPACE_RESTORE_REPORT_FILES,
        "Invalid workspace restore report file",
    )


def update_workspace_snapshot_metadata(snapshot_id: str, metadata: Dict[str, Any], *, snapshot_status: Optional[str] = None) -> Dict[str, Any]:
    snapshot = get_workspace_snapshot(snapshot_id)
    if not snapshot:
        raise ValueError("Workspace snapshot not found")
    next_status = normalize_workspace_snapshot_status(snapshot_status or snapshot.get("snapshot_status") or "created")
    with db() as conn:
        conn.execute(
            "UPDATE workspace_snapshots SET snapshot_status = ?, metadata_json = ? WHERE id = ?",
            (next_status, workspace_snapshot_row_metadata_json(metadata), snapshot_id),
        )
        conn.commit()
    stored = get_workspace_snapshot(snapshot_id)
    if stored is None:
        raise ValueError("Workspace snapshot metadata was not saved correctly")
    return stored


def create_workspace_snapshot(project_id: str, *, workspace_id: Optional[str] = None, snapshot_label: str = "", update_project_timestamp: bool = True) -> Dict[str, Any]:
    if not project_id:
        raise ValueError("project_id is required")
    project = get_project(project_id)
    if not project:
        raise ValueError("Project not found")
    workspace = get_workspace(workspace_id, include_prompt=True) if workspace_id else (project.get("latest_workspace") or latest_project_workspace(project_id, include_prompt=True))
    if not workspace:
        raise ValueError("No workspace exists for this project yet")
    if str(workspace.get("project_id") or "") != project_id:
        raise ValueError("Workspace does not belong to this project")
    source_workspace_path = Path(str(workspace.get("path") or "")).resolve()
    if not source_workspace_path.exists() or not source_workspace_path.is_dir():
        raise ValueError("Workspace folder is missing")
    created_at = now_iso()
    snapshot_id = str(uuid.uuid4())
    snapshot_dir = create_timestamped_export_dir(workspace_snapshot_export_dir(), str(project.get("title") or "project"), created_at)
    resolved_snapshot_dir = snapshot_dir.resolve()
    files = workspace_snapshot_file_paths(source_workspace_path)
    manifest_entries = workspace_snapshot_manifest_entries(source_workspace_path, files)
    warnings: List[str] = []
    for entry in manifest_entries:
        source = (source_workspace_path / str(entry.get("path") or "")).resolve()
        target = (snapshot_dir / str(entry.get("path") or "")).resolve()
        try:
            source.relative_to(source_workspace_path)
            target.relative_to(resolved_snapshot_dir)
        except ValueError as exc:
            raise ValueError("Workspace snapshot path escaped the allowed folder") from exc
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, target)
    manifest = {
        "snapshot_id": snapshot_id,
        "project_id": project_id,
        "workspace_id": str(workspace.get("workspace_id") or workspace.get("id") or ""),
        "created_at": created_at,
        "snapshot_label": str(snapshot_label or "manual-snapshot").strip() or "manual-snapshot",
        "source_workspace_path": str(source_workspace_path),
        "snapshot_path": str(snapshot_dir),
        "files": manifest_entries,
        "excluded_patterns": list(WORKSPACE_SNAPSHOT_EXCLUDED_PATTERNS),
        "files_count": len(manifest_entries),
        "total_size_bytes": sum(int(item.get("size") or 0) for item in manifest_entries),
    }
    snapshot_payload = {
        "snapshot_id": snapshot_id,
        "id": snapshot_id,
        "project_id": project_id,
        "workspace_id": manifest["workspace_id"],
        "created_at": created_at,
        "snapshot_label": manifest["snapshot_label"],
        "snapshot_status": "created",
        "source_workspace_path": str(source_workspace_path),
        "snapshot_path": str(snapshot_dir),
        "files_count": len(manifest_entries),
        "warnings": warnings,
    }
    report_files = {
        "snapshot-manifest.json": json.dumps(manifest, indent=2) + "\n",
        "snapshot-report.md": workspace_snapshot_report_markdown(project, snapshot_payload),
        "restore-instructions.md": workspace_snapshot_restore_instructions(str(project.get("title") or "Sprint"), snapshot_payload),
    }
    write_text_files(snapshot_dir, report_files)
    metadata = {
        "snapshot_id": snapshot_id,
        "project_id": project_id,
        "project_title": str(project.get("title") or "Sprint"),
        "workspace_id": manifest["workspace_id"],
        "created_at": created_at,
        "snapshot_label": manifest["snapshot_label"],
        "snapshot_status": "created",
        "source_workspace_path": str(source_workspace_path),
        "snapshot_path": str(snapshot_dir),
        "files_count": len(manifest_entries),
        "warnings": warnings,
        "manifest": manifest,
        "files_generated": workspace_snapshot_file_names(manifest_entries),
        "latest_comparison": {
            "workspace_id": manifest["workspace_id"],
            "snapshot_id": snapshot_id,
            "added_count": 0,
            "modified_count": 0,
            "removed_count": 0,
            "unchanged_count": len(manifest_entries),
            "warnings": [],
            "created_at": created_at,
        },
    }
    with db() as conn:
        conn.execute(
            """
            INSERT INTO workspace_snapshots (
                id, project_id, workspace_id, created_at, snapshot_label, snapshot_status,
                source_workspace_path, snapshot_path, files_count, metadata_json
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                snapshot_id,
                project_id,
                manifest["workspace_id"],
                created_at,
                manifest["snapshot_label"],
                "created",
                str(source_workspace_path),
                str(snapshot_dir),
                len(manifest_entries),
                workspace_snapshot_row_metadata_json(metadata),
            ),
        )
        if update_project_timestamp:
            conn.execute("UPDATE projects SET updated_at = ? WHERE id = ?", (created_at, project_id))
        conn.commit()
    stored = get_workspace_snapshot(snapshot_id)
    if stored is None:
        raise ValueError("Workspace snapshot was not saved correctly")
    record_activity_event(
        project_id,
        "workspace_snapshot_created",
        "Workspace snapshot created",
        f"Created snapshot {manifest['snapshot_label']} with {len(manifest_entries)} files.",
        event_status="success",
        actor="sprintos",
        related_type="workspace_snapshot",
        related_id=snapshot_id,
        next_tiny_action="Use Compare Snapshot after more workspace changes.",
        report_path=str(snapshot_dir),
        metadata={"workspace_id": manifest["workspace_id"], "files_count": len(manifest_entries)},
    )
    return stored


def compare_workspace_to_snapshot(workspace_id: str, snapshot_id: str, *, persist: bool = True) -> Dict[str, Any]:
    workspace = get_workspace(workspace_id, include_prompt=False)
    if not workspace:
        raise ValueError("Workspace not found")
    snapshot = get_workspace_snapshot(snapshot_id)
    if not snapshot:
        raise ValueError("Workspace snapshot not found")
    if str(snapshot.get("workspace_id") or "") != str(workspace.get("workspace_id") or workspace.get("id") or ""):
        raise ValueError("Workspace snapshot does not belong to this workspace")
    base = Path(str(workspace.get("path") or "")).resolve()
    if not base.exists() or not base.is_dir():
        raise ValueError("Workspace folder is missing")
    manifest_files = list(((snapshot.get("manifest") or {}).get("files") or []))
    manifest_by_path = {str(item.get("path") or ""): item for item in manifest_files if str(item.get("path") or "").strip()}
    current_files = workspace_snapshot_manifest_entries(base, workspace_snapshot_file_paths(base))
    current_by_path = {str(item.get("path") or ""): item for item in current_files if str(item.get("path") or "").strip()}
    added = sorted(path for path in current_by_path if path not in manifest_by_path)
    removed = sorted(path for path in manifest_by_path if path not in current_by_path)
    modified = sorted(
        path
        for path in current_by_path
        if path in manifest_by_path and str(current_by_path[path].get("sha256") or "") != str(manifest_by_path[path].get("sha256") or "")
    )
    unchanged_count = sum(
        1
        for path in current_by_path
        if path in manifest_by_path and str(current_by_path[path].get("sha256") or "") == str(manifest_by_path[path].get("sha256") or "")
    )
    payload = {
        "workspace_id": str(workspace.get("workspace_id") or workspace.get("id") or ""),
        "snapshot_id": snapshot_id,
        "added_files": added,
        "removed_files": removed,
        "modified_files": modified,
        "added_count": len(added),
        "removed_count": len(removed),
        "modified_count": len(modified),
        "unchanged_count": unchanged_count,
        "warnings": [],
        "created_at": now_iso(),
    }
    if persist:
        metadata = dict(snapshot.get("metadata") or {})
        metadata["latest_comparison"] = payload
        update_workspace_snapshot_metadata(snapshot_id, metadata)
    return payload


def restore_workspace_report_markdown(project: Dict[str, Any], payload: Dict[str, Any]) -> str:
    lines = [
        f"# Workspace Restore Report — {project.get('title') or 'Sprint'}",
        "",
        "## Restored Snapshot",
        str(payload.get("restored_snapshot_label") or payload.get("snapshot_id") or ""),
        "",
        "## Target Workspace",
        redact_obvious_secret_text(str(payload.get("target_workspace_path") or "")),
        "",
        "## Files Restored",
        str(payload.get("files_restored") or 0),
        "",
        "## Files Preserved",
    ]
    lines.extend(f"- {item}" for item in (payload.get("preserved_items") or []) or ["- none"])
    lines.extend(["", "## Warnings / Blockers"])
    lines.extend(f"- Warning: {item}" for item in (payload.get("warnings") or []))
    lines.extend(f"- Blocker: {item}" for item in (payload.get("blockers") or []))
    if not payload.get("warnings") and not payload.get("blockers"):
        lines.append("- none")
    lines.extend(
        [
            "",
            "## Next Tiny Action",
            str(payload.get("next_tiny_action") or ""),
            "",
            "## Suggested Verification Command / Action",
            str(payload.get("suggested_verification_action") or "Run Workspace Sync, then Run & Verify."),
            "",
        ]
    )
    return "\n".join(lines)


def restore_workspace_snapshot(snapshot_id: str) -> Dict[str, Any]:
    snapshot = get_workspace_snapshot(snapshot_id)
    if not snapshot:
        raise ValueError("Workspace snapshot not found")
    project = get_project(str(snapshot.get("project_id") or ""))
    if not project:
        raise ValueError("Project not found")
    workspace = get_workspace(str(snapshot.get("workspace_id") or ""), include_prompt=True)
    if not workspace:
        raise ValueError("Workspace not found")
    snapshot_dir = Path(str(snapshot.get("snapshot_path") or "")).resolve()
    workspace_dir = Path(str(workspace.get("path") or "")).resolve()
    if not snapshot_dir.exists() or not snapshot_dir.is_dir():
        raise ValueError("Workspace snapshot folder is missing")
    if not workspace_dir.exists() or not workspace_dir.is_dir():
        raise ValueError("Workspace folder is missing")
    try:
        pre_restore_snapshot = create_workspace_snapshot(
            str(project.get("id") or ""),
            workspace_id=str(workspace.get("workspace_id") or workspace.get("id") or ""),
            snapshot_label=f"before-restore-{snapshot_id}",
            update_project_timestamp=False,
        )
    except ValueError as exc:
        raise ValueError(f"Could not create pre-restore safety snapshot. {exc}") from exc
    manifest = (snapshot.get("manifest") or {})
    manifest_files = list(manifest.get("files") or [])
    desired_paths = {str(item.get("path") or "") for item in manifest_files if str(item.get("path") or "").strip()}
    for item in manifest_files:
        relative_path = str(item.get("path") or "")
        if not relative_path:
            continue
        source = (snapshot_dir / relative_path).resolve()
        try:
            source.relative_to(snapshot_dir)
        except ValueError as exc:
            raise ValueError("Workspace restore path escaped the allowed folder") from exc
        if not source.exists() or not source.is_file():
            raise ValueError(f"Workspace snapshot is missing file: {relative_path}")
    current_paths = {
        path.relative_to(workspace_dir).as_posix(): path
        for path in workspace_snapshot_file_paths(workspace_dir)
    }
    warnings: List[str] = []
    blockers: List[str] = []
    preserved_items = ["Existing .env files are preserved.", ".git internals are preserved and not restored."]
    files_restored = 0
    files_removed = 0
    for relative_path, current_path in current_paths.items():
        if relative_path not in desired_paths:
            try:
                target = current_path.resolve()
                target.relative_to(workspace_dir)
            except ValueError:
                blockers.append(f"Skipped unsafe workspace path during cleanup: {relative_path}")
                continue
            current_path.unlink()
            files_removed += 1
    for item in manifest_files:
        relative_path = str(item.get("path") or "")
        if not relative_path:
            continue
        source = (snapshot_dir / relative_path).resolve()
        target = (workspace_dir / relative_path).resolve()
        try:
            source.relative_to(snapshot_dir)
            target.relative_to(workspace_dir)
        except ValueError as exc:
            raise ValueError("Workspace restore path escaped the allowed folder") from exc
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, target)
        files_restored += 1
    for path in sorted(workspace_dir.rglob(".env")):
        if path.is_file():
            rel = path.relative_to(workspace_dir).as_posix()
            preserved_items.append(f"Preserved `{rel}`.")
    restore_id = str(uuid.uuid4())
    created_at = now_iso()
    report_dir = create_timestamped_export_dir(workspace_restore_export_dir(), str(project.get("title") or "project"), created_at)
    next_tiny_action = "Run Workspace Sync."
    suggested_verification_action = "Run Run & Verify."
    payload = {
        "restore_id": restore_id,
        "snapshot_id": snapshot_id,
        "project_id": str(project.get("id") or ""),
        "workspace_id": str(workspace.get("workspace_id") or workspace.get("id") or ""),
        "created_at": created_at,
        "restore_status": "completed" if not blockers else "failed",
        "restored_snapshot_label": str(snapshot.get("snapshot_label") or snapshot_id),
        "target_workspace_path": str(workspace_dir),
        "files_restored": files_restored,
        "files_removed": files_removed,
        "warnings": warnings,
        "blockers": blockers,
        "preserved_items": dedupe_items(preserved_items),
        "pre_restore_snapshot_id": str(pre_restore_snapshot.get("snapshot_id") or ""),
        "next_tiny_action": next_tiny_action,
        "suggested_verification_action": suggested_verification_action,
        "report_path": str(report_dir),
    }
    report_files = {
        "restore-report.md": restore_workspace_report_markdown(project, payload),
        "restore-result.json": json.dumps(payload, indent=2) + "\n",
        "post-restore-next-action.md": "Run Workspace Sync.\nRun Run & Verify.\nOpen CODEX_START_HERE.md again.\nPaste the generated fix prompt into Codex.\n",
    }
    write_text_files(report_dir, report_files)
    metadata = dict(payload)
    metadata["report_url"] = workspace_restore_report_url(restore_id)
    with db() as conn:
        conn.execute(
            """
            INSERT INTO workspace_restores (
                id, snapshot_id, project_id, workspace_id, created_at, restore_status, report_path, files_restored, metadata_json
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                restore_id,
                snapshot_id,
                payload["project_id"],
                payload["workspace_id"],
                created_at,
                payload["restore_status"],
                str(report_dir),
                files_restored,
                json.dumps(metadata),
            ),
        )
        conn.execute("UPDATE projects SET updated_at = ? WHERE id = ?", (created_at, payload["project_id"]))
        conn.commit()
    snapshot_metadata = dict(snapshot.get("metadata") or {})
    restores = list(snapshot_metadata.get("restores") or [])
    restores.append(
        {
            "restore_id": restore_id,
            "created_at": created_at,
            "restore_status": payload["restore_status"],
            "files_restored": files_restored,
            "report_path": str(report_dir),
        }
    )
    snapshot_metadata["restores"] = restores[-5:]
    snapshot_metadata["last_restore"] = restores[-1]
    update_workspace_snapshot_metadata(snapshot_id, snapshot_metadata, snapshot_status="restored" if not blockers else "failed")
    stored_restore = get_workspace_restore(restore_id) or {
        "restore_id": restore_id,
        "snapshot_id": snapshot_id,
        "project_id": payload["project_id"],
        "workspace_id": payload["workspace_id"],
        "restore_status": payload["restore_status"],
        "report_path": str(report_dir),
        "files_restored": files_restored,
        "warnings": warnings,
        "blockers": blockers,
        "next_tiny_action": next_tiny_action,
        "metadata": metadata,
    }
    record_activity_event(
        payload["project_id"],
        "workspace_restored",
        "Workspace restored",
        f"Restored snapshot {payload['restored_snapshot_label']} into the workspace.",
        event_status="success" if not blockers else "failed",
        actor="sprintos",
        related_type="workspace_restore",
        related_id=restore_id,
        next_tiny_action=next_tiny_action,
        report_path=str(report_dir),
        metadata={"snapshot_id": snapshot_id, "files_restored": files_restored, "files_removed": files_removed},
    )
    return stored_restore


