def create_pipeline_report_dir(project_title: str, pipeline_goal: str, created_at: str) -> Path:
    return create_report_dir(
        pipeline_export_dir(),
        project_title,
        pipeline_goal,
        prototype_folder_timestamp(created_at),
    )


def write_pipeline_report_folder(project: Dict[str, Any], payload: Dict[str, Any], report_dir: Optional[Path] = None) -> Path:
    report_dir = report_dir or create_pipeline_report_dir(payload["project_title"], payload["pipeline_goal"], payload["created_at"])
    file_contents = {
        "pipeline-report.md": pipeline_report_markdown(project, payload),
        "artifact-index.md": pipeline_artifact_index_markdown(payload),
        "next-action.md": (payload.get("next_tiny_action") or "").strip() + "\n",
        "codex-next-prompt.md": str(payload.get("codex_prompt") or "").strip() + "\n",
        "share-message.md": str(payload.get("share_message") or "").strip() + "\n",
        "manual-test-checklist.md": pipeline_manual_test_checklist_markdown(),
        "pipeline-run.json": json.dumps(
            {
                "pipeline_run_id": payload["pipeline_run_id"],
                "project_id": payload["project_id"],
                "project_title": payload["project_title"],
                "pipeline_goal": payload["pipeline_goal"],
                "status": payload["status"],
                "created_at": payload["created_at"],
                "selected_workflow": payload["selected_workflow"],
                "prototype_type": payload["prototype_type"],
                "hosting_target": payload["hosting_target"],
                "build_target": payload["build_target"],
                "prototype_id": payload["prototype_id"],
                "deploy_pack_id": payload["deploy_pack_id"],
                "build_pack_id": payload["build_pack_id"],
                "warnings": payload["warnings"],
                "blockers": payload["blockers"],
                "files_generated": payload["files_generated"],
                "preview_urls": payload["preview_urls"],
                "zip_urls": payload["zip_urls"],
                "run_command": payload["run_command"],
                "test_command": payload["test_command"],
                "next_tiny_action": payload["next_tiny_action"],
                "suggested_first_codex_task": payload["suggested_first_codex_task"],
            },
            indent=2,
        )
        + "\n",
    }
    return write_text_files(report_dir, file_contents)


def pipeline_run_response(row: sqlite3.Row | Dict[str, Any], include_prompt: bool = False) -> Dict[str, Any]:
    data = dict(row)
    metadata = safe_json_loads(str(data.get("metadata_json") or "{}"), {}) or {}
    report_path = Path(str(data.get("report_path") or metadata.get("report_path") or ""))
    pipeline_run_id = str(data.get("id") or metadata.get("pipeline_run_id") or "")
    result = {
        "id": pipeline_run_id,
        "pipeline_run_id": pipeline_run_id,
        "project_id": str(data.get("project_id") or metadata.get("project_id") or ""),
        "created_at": str(data.get("created_at") or metadata.get("created_at") or ""),
        "pipeline_goal": str(data.get("pipeline_goal") or metadata.get("pipeline_goal") or "codex_build_ready"),
        "status": str(data.get("status") or metadata.get("status") or "partial"),
        "selected_workflow": str(data.get("selected_workflow") or metadata.get("selected_workflow") or ""),
        "prototype_type": str(data.get("prototype_type") or metadata.get("prototype_type") or "landing_page"),
        "hosting_target": str(data.get("hosting_target") or metadata.get("hosting_target") or "static"),
        "build_target": str(data.get("build_target") or metadata.get("build_target") or "static_app"),
        "prototype_id": str(data.get("prototype_id") or metadata.get("prototype_id") or "") or None,
        "deploy_pack_id": str(data.get("deploy_pack_id") or metadata.get("deploy_pack_id") or "") or None,
        "build_pack_id": str(data.get("build_pack_id") or metadata.get("build_pack_id") or "") or None,
        "report_path": str(report_path),
        "report_url": pipeline_report_url(pipeline_run_id),
        "warnings": list(metadata.get("warnings") or []),
        "blockers": list(metadata.get("blockers") or []),
        "preview_urls": dict(metadata.get("preview_urls") or {"pipeline_report": pipeline_report_url(pipeline_run_id)}),
        "zip_urls": dict(metadata.get("zip_urls") or {"pipeline_report": pipeline_zip_url(pipeline_run_id)}),
        "run_command": str(metadata.get("run_command") or "n/a"),
        "test_command": str(metadata.get("test_command") or "n/a"),
        "next_tiny_action": str(metadata.get("next_tiny_action") or ""),
        "suggested_first_codex_task": str(metadata.get("suggested_first_codex_task") or ""),
        "app_generation_fallback_mode": str(metadata.get("app_generation_fallback_mode") or "template"),
        "ai_generation_failed": bool(metadata.get("ai_generation_failed")),
        "app_generation_failure": dict(metadata.get("app_generation_failure") or {}),
        "failure_report_id": str(metadata.get("failure_report_id") or ""),
        "failure_report_path": str(metadata.get("failure_report_path") or ""),
        "failure_report_url": str(metadata.get("failure_report_url") or ""),
        "failure_category": str(metadata.get("failure_category") or ""),
        "sanitized_reason": str(metadata.get("sanitized_reason") or ""),
        "fallback_used": bool(metadata.get("fallback_used")) if metadata.get("fallback_used") is not None else None,
        "retry_available": bool(metadata.get("retry_available")),
        "files_generated": list(metadata.get("files_generated") or list(PIPELINE_REPORT_FILES)),
        "generation_mode_requested": str(metadata.get("generation_mode_requested") or "auto"),
        "used_ai": bool(metadata.get("used_ai")),
        "ai_provider": str(metadata.get("ai_provider") or "offline"),
        "ai_model": str(metadata.get("ai_model") or ""),
        "ai_task_name": str(metadata.get("ai_task_name") or ""),
        "ai_fallback_reason": str(metadata.get("ai_fallback_reason") or ""),
        "metadata": metadata,
    }
    if include_prompt:
        prompt_path = report_path / "codex-next-prompt.md"
        share_path = report_path / "share-message.md"
        result["codex_prompt"] = prompt_path.read_text(encoding="utf-8") if prompt_path.exists() else ""
        result["share_message"] = share_path.read_text(encoding="utf-8") if share_path.exists() else ""
    return result


def get_pipeline_run(pipeline_run_id: str, include_prompt: bool = False) -> Optional[Dict[str, Any]]:
    with db() as conn:
        row = conn.execute("SELECT * FROM pipeline_runs WHERE id = ?", (pipeline_run_id,)).fetchone()
    if not row:
        return None
    return pipeline_run_response(row, include_prompt=include_prompt)


def latest_project_pipeline_run(project_id: str, include_prompt: bool = False) -> Optional[Dict[str, Any]]:
    with db() as conn:
        row = conn.execute(
            "SELECT * FROM pipeline_runs WHERE project_id = ? ORDER BY created_at DESC, rowid DESC LIMIT 1",
            (project_id,),
        ).fetchone()
    if not row:
        return None
    return pipeline_run_response(row, include_prompt=include_prompt)


def pipeline_report_file_path(pipeline_run: Dict[str, Any], filename: str) -> Path:
    return safe_flat_file_path(
        Path(str(pipeline_run.get("report_path") or "")),
        filename,
        PIPELINE_REPORT_FILES,
        "Invalid pipeline report file",
    )


def build_pipeline_report_zip(pipeline_run: Dict[str, Any]) -> Tuple[str, bytes]:
    filename = sanitize_filename(
        f"{slugify(str(pipeline_run.get('project_id') or 'pipeline'), 'pipeline')}-{prototype_folder_timestamp(str(pipeline_run.get('created_at') or now_iso()))}.zip",
        default_stem="pipeline-report",
        default_suffix=".zip",
    )
    payload = build_zip_from_reader(
        PIPELINE_REPORT_FILES,
        lambda name: pipeline_report_file_path(pipeline_run, name).read_text(encoding="utf-8"),
    )
    return filename, payload


def run_testable_pipeline(
    project_id: str,
    pipeline_goal: str = "codex_build_ready",
    prototype_type: str = "",
    hosting_target: str = "",
    build_target: str = "",
    generation_mode: str = "auto",
    fallback_mode: str = "",
) -> Dict[str, Any]:
    goal = normalize_pipeline_goal(pipeline_goal or "codex_build_ready")
    defaults = pipeline_goal_defaults(goal)
    prototype_choice = normalize_pipeline_prototype_choice(prototype_type or defaults["prototype_type"])
    selected_hosting_target = normalize_hosting_target(hosting_target or defaults["hosting_target"])
    build_choice = normalize_pipeline_build_target(build_target or defaults["build_target"])
    project = get_project(project_id)
    if not project:
        raise ValueError("Project not found")

    pipeline_run_id = str(uuid.uuid4())
    created_at = now_iso()
    warnings: List[str] = []
    blockers: List[str] = []
    steps_completed: List[str] = []
    had_step_failure = False
    selected_workflow = str(project.get("workflow_id") or project.get("sprint", {}).get("_workflow_id") or "business_validation")
    resolved_prototype_type = "landing_page"
    resolved_build_target = "static_app"
    prototype: Optional[Dict[str, Any]] = None
    readiness: Optional[Dict[str, Any]] = None
    deploy_pack: Optional[Dict[str, Any]] = None
    build_pack: Optional[Dict[str, Any]] = None
    app_generation_failure: Optional[Dict[str, Any]] = None
    resolved_fallback_mode = normalize_app_generation_fallback_mode(fallback_mode)

    try:
        project = ensure_project_has_sprint(project)
        steps_completed.append("Loaded project and confirmed a sprint exists.")
    except Exception as exc:
        had_step_failure = True
        blockers.append(f"Could not ensure the project sprint exists: {exc}")

    try:
        project["generation_mode_requested"] = normalize_generation_mode(generation_mode)
        project = maybe_refresh_resume_plan(project)
        steps_completed.append("Confirmed resume context is available.")
    except Exception as exc:
        had_step_failure = True
        warnings.append(f"Resume plan refresh skipped: {exc}")

    if prototype_choice == "auto":
        resolved_prototype_type = auto_select_prototype_type(project)
        steps_completed.append(f"Auto-selected prototype type: {resolved_prototype_type}.")
    else:
        resolved_prototype_type = prototype_choice
        steps_completed.append(f"Used requested prototype type: {resolved_prototype_type}.")

    try:
        requested_mode = normalize_generation_mode(generation_mode)
        use_report_only = resolved_fallback_mode == "report_only"
        if requested_mode == "auto":
            if use_report_only:
                prototype = write_prototype_package(project, resolved_prototype_type, fallback_mode=resolved_fallback_mode)
            else:
                prototype = write_prototype_package(project, resolved_prototype_type)
        else:
            if use_report_only:
                prototype = write_prototype_package(
                    project,
                    resolved_prototype_type,
                    generation_mode=requested_mode,
                    fallback_mode=resolved_fallback_mode,
                )
            else:
                prototype = write_prototype_package(project, resolved_prototype_type, generation_mode=requested_mode)
        steps_completed.append("Generated prototype package.")
    except AppGenerationFailure as exc:
        had_step_failure = True
        app_generation_failure = exc.report
        blockers.append(str(exc.report.get("sanitized_reason") or "AI app generation failed."))
        steps_completed.append("Stopped before generating prototype files because AI app generation failed in report-only mode.")
    except Exception as exc:
        had_step_failure = True
        blockers.append(f"Prototype generation failed: {exc}")

    if prototype:
        try:
            readiness = check_deploy_readiness(prototype)
            steps_completed.append("Ran deploy readiness check.")
            warnings.extend(readiness.get("warnings") or [])
            if readiness.get("blockers"):
                blockers.extend(readiness.get("blockers") or [])
                steps_completed.append("Skipped Deploy Pack because readiness blockers were found.")
            else:
                deploy_pack = write_deploy_pack(project, prototype, selected_hosting_target)
                steps_completed.append(f"Generated Deploy Pack for {selected_hosting_target}.")
        except Exception as exc:
            had_step_failure = True
            warnings.append(f"Deploy readiness or Deploy Pack step failed: {exc}")

    if build_choice == "auto":
        resolved_build_target = auto_select_build_target(project, resolved_prototype_type, goal)
        steps_completed.append(f"Auto-selected build target: {resolved_build_target}.")
    else:
        resolved_build_target = build_choice
        steps_completed.append(f"Used requested build target: {resolved_build_target}.")

    if prototype:
        try:
            build_pack = write_build_pack(project, prototype, resolved_build_target, deploy_pack=deploy_pack)
            steps_completed.append("Generated Build Pack.")
        except Exception as exc:
            had_step_failure = True
            warnings.append(f"Build Pack generation failed: {exc}")

    status = "failed"
    if build_pack or deploy_pack or prototype:
        status = "completed"
        if blockers or had_step_failure:
            status = "partial"
        elif warnings:
            status = "completed_with_warnings"
    if not steps_completed:
        steps_completed.append("No pipeline steps completed.")

    report_dir = create_pipeline_report_dir(str(project.get("title") or "project"), goal, created_at)
    final_payload = build_pipeline_report_payload(
        pipeline_run_id,
        project,
        goal,
        status,
        selected_workflow,
        resolved_prototype_type,
        selected_hosting_target,
        resolved_build_target,
        prototype,
        readiness,
        deploy_pack,
        build_pack,
        report_dir,
        dedupe_items(warnings),
        dedupe_items(blockers),
        steps_completed,
        created_at,
        generation_mode_requested=normalize_generation_mode(generation_mode),
    )
    final_payload["app_generation_fallback_mode"] = resolved_fallback_mode
    final_payload["app_generation_failure"] = app_generation_failure or {}
    if app_generation_failure:
        final_payload.update(
            {
                "ai_generation_failed": True,
                "failure_report_id": app_generation_failure.get("report_id") or "",
                "failure_report_path": app_generation_failure.get("report_path") or "",
                "failure_report_url": app_generation_failure.get("report_url") or "",
                "failure_category": app_generation_failure.get("failure_category") or "",
                "sanitized_reason": app_generation_failure.get("sanitized_reason") or "",
                "provider": app_generation_failure.get("provider") or "",
                "model": app_generation_failure.get("model") or "",
                "fallback_used": False,
                "retry_available": True,
                "next_tiny_action": app_generation_failure.get("suggested_next_action") or final_payload.get("next_tiny_action") or "",
            }
        )
    write_pipeline_report_folder(project, final_payload, report_dir)

    with db() as conn:
        conn.execute(
            """
            INSERT INTO pipeline_runs (
                id, project_id, created_at, pipeline_goal, status, selected_workflow,
                prototype_type, hosting_target, build_target, prototype_id, deploy_pack_id,
                build_pack_id, report_path, metadata_json
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                pipeline_run_id,
                project["id"],
                created_at,
                goal,
                status,
                selected_workflow,
                resolved_prototype_type,
                selected_hosting_target,
                resolved_build_target,
                final_payload["prototype_id"],
                final_payload["deploy_pack_id"],
                final_payload["build_pack_id"],
                str(report_dir),
                json.dumps(final_payload),
            ),
        )
        conn.execute("UPDATE projects SET updated_at = ? WHERE id = ?", (created_at, project["id"]))
        conn.commit()
    stored = get_pipeline_run(pipeline_run_id, include_prompt=True)
    if stored is None:
        raise ValueError("Pipeline run was not saved correctly")
    record_activity_event(
        project["id"],
        "pipeline_run_completed",
        "Pipeline run completed" if status == "completed" else "Pipeline run partial" if status in {"partial", "completed_with_warnings"} else "Pipeline run failed",
        str(final_payload.get("summary") or f"Pipeline finished with status {status}."),
        event_status=activity_status_from_pipeline_status(status),
        actor="sprintos",
        related_type="pipeline_run",
        related_id=pipeline_run_id,
        next_tiny_action=str(stored.get("next_tiny_action") or ""),
        report_path=str(report_dir),
        metadata={"pipeline_goal": goal, "prototype_type": resolved_prototype_type, "hosting_target": selected_hosting_target, "build_target": resolved_build_target},
    )
    return stored


def quick_launch_report_url(quick_launch_id: str, filename: str = "quick-launch-report.md") -> str:
    return f"/api/quick_launch_report?id={urllib.parse.quote(quick_launch_id)}&file={urllib.parse.quote(filename)}"


def quick_launch_zip_url(quick_launch_id: str) -> str:
    return f"/api/quick_launch_zip?id={urllib.parse.quote(quick_launch_id)}"


def create_quick_launch_report_dir(project_title: str, launch_goal: str, created_at: str) -> Path:
    return create_report_dir(
        quick_launch_export_dir(),
        project_title,
        launch_goal,
        prototype_folder_timestamp(created_at),
    )


def quick_launch_done_definition(launch_goal: str, build_pack_path: str, deploy_pack_path: str) -> str:
    if build_pack_path:
        return "Done when the Build Pack exists, the Codex next prompt is copy-ready, and the next PR-sized task is obvious."
    if deploy_pack_path or launch_goal == "public_static_test":
        return "Done when the prototype package is ready to preview/share locally and the tester message is ready to send."
    return "Done when one testable local package exists and the next tiny action is clearer than the original idea."


def quick_launch_share_message(project: Dict[str, Any], pipeline_run: Dict[str, Any]) -> str:
    return str(pipeline_run.get("share_message") or suggested_share_message(project)).strip()


def quick_launch_codex_next_prompt(
    project: Dict[str, Any],
    pipeline_run: Dict[str, Any],
    report_dir: Path,
    build_pack: Optional[Dict[str, Any]],
    suggested_first_codex_task: str,
) -> str:
    quick_launch_path = str(report_dir)
    pipeline_path = str(pipeline_run.get("report_path") or "")
    build_pack_path = str((build_pack or {}).get("path") or "")
    if build_pack and build_pack.get("codex_prompt"):
        return (
            f"# Quick Launch Next Codex Prompt — {project.get('title', 'Sprint')}\n\n"
            "Read AGENTS.md first before editing.\n\n"
            f"Quick Launch report path: {quick_launch_path}\n"
            f"Pipeline report path: {pipeline_path}\n"
            f"Build Pack path: {build_pack_path}\n"
            f"Suggested first Codex task: {suggested_first_codex_task}\n\n"
            "Start with `CODEX_BUILD_PROMPT.md` from the generated Build Pack.\n\n"
            f"{str(build_pack.get('codex_prompt') or '').strip()}\n"
        )
    return (
        f"# Quick Launch Next Codex Prompt — {project.get('title', 'Sprint')}\n\n"
        "Read AGENTS.md first before editing.\n\n"
        f"Quick Launch report path: {quick_launch_path}\n"
        f"Pipeline report path: {pipeline_path}\n"
        f"Suggested first Codex task: {suggested_first_codex_task}\n\n"
        f"{str(pipeline_run.get('codex_prompt') or '').strip()}\n"
    )


