def artifact_history_limit(value: Any, default: int = 10, maximum: int = 50) -> int:
    try:
        resolved = int(value)
    except (TypeError, ValueError):
        resolved = default
    return max(1, min(resolved, maximum))


def artifact_history_item(
    *,
    item_id: str,
    created_at: str,
    label: str,
    artifact_type: str,
    status: str = "",
    title: Optional[str] = None,
    path: str = "",
    report_path: str = "",
    primary_action_label: str = "",
    primary_url: str = "",
    zip_url: str = "",
    summary: str = "",
    next_tiny_action: str = "",
    copy_prompt_label: str = "",
    copy_prompt_url: str = "",
    copy_text: str = "",
) -> Dict[str, Any]:
    return {
        "id": str(item_id or ""),
        "created_at": str(created_at or ""),
        "title": str(title or label or artifact_type.replace("_", " ").title()),
        "label": str(label or title or artifact_type.replace("_", " ").title()),
        "type": str(artifact_type or ""),
        "status": str(status or ""),
        "path": str(path or ""),
        "report_path": str(report_path or ""),
        "primary_action_label": str(primary_action_label or ""),
        "primary_url": str(primary_url or ""),
        "zip_url": str(zip_url or ""),
        "summary": str(summary or ""),
        "next_tiny_action": str(next_tiny_action or ""),
        "copy_prompt_label": str(copy_prompt_label or ""),
        "copy_prompt_url": str(copy_prompt_url or ""),
        "copy_text": str(copy_text or ""),
    }


def artifact_history_query(
    query: str,
    params: Tuple[Any, ...],
    limit: int,
    mapper: Callable[[sqlite3.Row], Dict[str, Any]],
) -> List[Dict[str, Any]]:
    with db() as conn:
        rows = conn.execute(query, params + (limit,)).fetchall()
    return [mapper(row) for row in rows]


def project_provider_eval_history(project_id: str, limit: int = 10) -> List[Dict[str, Any]]:
    matches: List[Dict[str, Any]] = []
    for item in list_ai_provider_evals(limit=200):
        metadata = item.get("metadata") or {}
        if str(metadata.get("project_id") or "") != str(project_id):
            continue
        matches.append(
            artifact_history_item(
                item_id=str(item.get("id") or ""),
                created_at=str(item.get("created_at") or ""),
                label=f"{str(item.get('task_name') or 'eval').replace('_', ' ')} · {str(item.get('provider') or 'offline')}",
                artifact_type="provider_eval",
                status=str(item.get("status") or ""),
                title=str(item.get("eval_name") or "Provider Eval"),
                primary_action_label="View AI Evals",
                primary_url="/api/ai_provider_evals?limit=20",
                summary=f"Score {int(item.get('score') or 0)} · model {str(item.get('model') or 'n/a')}",
                next_tiny_action=str(metadata.get("next_tiny_action") or ""),
            )
        )
        if len(matches) >= limit:
            break
    return matches


def latest_project_artifact_type(history_groups: Dict[str, List[Dict[str, Any]]]) -> str:
    latest_item: Optional[Dict[str, Any]] = None
    for group_key, items in history_groups.items():
        if group_key in {"activity_events", "provider_evals"}:
            continue
        for item in items:
            if latest_item is None or command_center_timestamp(item.get("created_at")) > command_center_timestamp(latest_item.get("created_at")):
                latest_item = item
    return str((latest_item or {}).get("type") or "")


