def verification_markdown(project: Dict[str, Any]) -> str:
    latest_verification = project.get("latest_verification_run") or latest_project_verification_run(project["id"])
    if not latest_verification:
        return ""
    command_summary = project.get("command_center") or build_project_command_summary(project)
    recommended_action = command_summary.get("recommended_action") or {}
    latest_snapshot = project.get("latest_workspace_snapshot") or latest_project_workspace_snapshot(project["id"])
    latest_release_pack = project.get("latest_workspace_release_pack") or latest_project_workspace_release_pack(project["id"])
    latest_focus_session = project.get("latest_focus_session") or latest_project_focus_session(project["id"])
    lines = [
        f"# Run & Verify — {project.get('title', 'Sprint')}",
        "",
        f"**Scope:** {latest_verification.get('verification_scope', '')}  ",
        f"**Status:** {latest_verification.get('status', '')}  ",
        f"**Created:** {latest_verification.get('created_at', '')}  ",
        f"**Share ready:** {latest_verification.get('share_ready', False)}  ",
        f"**Codex ready:** {latest_verification.get('codex_ready', False)}  ",
        f"**Report path:** {latest_verification.get('report_path', '')}  ",
        f"**Report URL:** {latest_verification.get('report_url', '')}  ",
        f"**ZIP:** {latest_verification.get('zip_url', '')}",
        "",
        "## Warnings",
    ]
    warnings = latest_verification.get("warnings") or []
    blockers = latest_verification.get("blockers") or []
    lines.extend([f"- {item}" for item in warnings] or ["- none"])
    lines.extend(["", "## Blockers"])
    lines.extend([f"- {item}" for item in blockers] or ["- none"])
    lines.extend(
        [
            "",
            "## Next Tiny Action",
            str(latest_verification.get("next_tiny_action") or ""),
            "",
            "## Current Command Center Recommendation",
            f"{recommended_action.get('label') or 'No action'} — {recommended_action.get('reason') or ''}",
        ]
    )
    if latest_snapshot:
        lines.extend(
            [
                "",
                "## Latest Workspace Snapshot",
                f"- Label: {latest_snapshot.get('snapshot_label', '')}",
                f"- Path: {latest_snapshot.get('snapshot_path', '')}",
                f"- Comparison: {workspace_snapshot_summary_text(latest_snapshot.get('latest_comparison'))}",
            ]
        )
    if latest_release_pack:
        lines.extend(
            [
                "",
                "## Latest Workspace Release Pack",
                f"- Label: {latest_release_pack.get('release_label', '')}",
                f"- Status: {latest_release_pack.get('release_status', '')}",
                f"- Type: {latest_release_pack.get('release_type', '')}",
                f"- Path: {latest_release_pack.get('path', '')}",
            ]
        )
        if latest_release_pack.get("release_status") == "blocked":
            lines.extend(
                [
                    "",
                    "## Release Follow-Up",
                    "Latest release pack is blocked. Open CODEX_NEXT_PROMPT.md from the release pack before another handoff.",
            ]
        )
    if latest_focus_session:
        lines.extend(
            [
                "",
                "## Latest Focus Session",
                f"- Title: {latest_focus_session.get('title') or ''}",
                f"- Status: {latest_focus_session.get('session_status') or ''}",
                f"- Next tiny action: {latest_focus_session.get('next_tiny_action') or ''}",
            ]
        )
    if latest_verification.get("status") in {"passed", "passed_with_warnings"}:
        lines.extend(
            [
                "",
                "## Suggested Next Step",
                "If the workspace looks stable, Create a Workspace Release Pack next.",
            ]
        )
    return "\n".join(lines).strip() + "\n"


